def _operator_effect_record(row: aiosqlite.Row) -> dict[str, Any]:
    record = dict(row)
    record["payload"] = _strict_json_loads(str(record["payload_json"]))
    raw_result = record.get("result_json")
    record["result"] = _strict_json_loads(str(raw_result)) if raw_result is not None else None
    version = record.get("delivery_contract_version")
    if version not in {
        OPERATOR_DELIVERY_CONTRACT_LEGACY,
        OPERATOR_DELIVERY_CONTRACT_EXACT_TURN,
    } or isinstance(version, bool):
        raise RuntimeError("stored operator delivery contract is invalid")
    if version == OPERATOR_DELIVERY_CONTRACT_LEGACY:
        return record
    payload = record["payload"]
    action_kind = record.get("action_kind")
    if not isinstance(payload, dict) or action_kind not in {
        OPERATOR_MESSAGE_ACTION,
        OPERATOR_HANDOFF_ACTION,
    }:
        raise RuntimeError("stored exact operator effect payload is invalid")
    if (
        payload.get("principal_id") != record.get("principal_id")
        or payload.get("action_kind") != action_kind
        or payload.get("idempotency_key") != record.get("idempotency_key")
        or payload.get("source_session_id") != record.get("source_session_id")
        or payload.get("target_session_id") != record.get("target_session_id")
        or payload.get("goal_id") != record.get("goal_id")
    ):
        raise RuntimeError("stored exact operator effect authority binding is corrupt")
    state = record.get("state")
    result = record["result"]
    if state in {"reserved", "dispatching"}:
        if result is not None or record.get("finished_at") is not None:
            raise RuntimeError("stored nonterminal operator effect has a terminal result")
        return record
    if (
        state not in OPERATOR_EFFECT_TERMINAL_STATES
        or not isinstance(result, dict)
        or record.get("finished_at") is None
    ):
        raise RuntimeError("stored terminal operator effect result is invalid")
    if action_kind == OPERATOR_MESSAGE_ACTION:
        vendor_session_id = payload.get("vendor_session_id")
        harness_type = payload.get("harness_type")
    else:
        vendor_session_id = payload.get("target_vendor_session_id")
        harness_type = payload.get("target_harness_type")
    try:
        normalized = _validate_operator_worker_delivery_result_binding(
            state=str(state),
            result=result,
            target_session_id=record.get("target_session_id"),
            vendor_session_id=vendor_session_id,
            harness_type=harness_type,
        )
    except (TypeError, ValueError) as exc:
        raise RuntimeError("stored operator delivery receipt is invalid") from exc
    if result.get("worker_delivery_receipt") != normalized:
        if result.get("worker_delivery_receipt") is not None or normalized is not None:
            raise RuntimeError("stored operator delivery receipt is corrupt")
    return record


def _human_operator_action_receipt_id(effect_id: str) -> str:
    digest = hashlib.sha256(
        f"pex.human-operator-terminal-action\0{effect_id}".encode()
    ).hexdigest()
    return f"human_operator_action_{digest}"


def _human_operator_action_reservation_payload(effect: dict[str, Any]) -> dict[str, Any]:
    payload = effect.get("payload")
    action_kind = effect.get("action_kind")
    if (
        not isinstance(payload, dict)
        or (
            action_kind == OPERATOR_MESSAGE_ACTION
            and payload.get("schema") != OPERATOR_ACTOR_PAYLOAD_SCHEMA
        )
        or (
            action_kind == OPERATOR_HANDOFF_ACTION
            and payload.get("schema") != OPERATOR_HANDOFF_ACTOR_PAYLOAD_SCHEMA
        )
        or action_kind not in {OPERATOR_MESSAGE_ACTION, OPERATOR_HANDOFF_ACTION}
    ):
        raise RuntimeError("assured operator reservation binding is invalid")
    if action_kind == OPERATOR_MESSAGE_ACTION:
        project_binding = validate_project_binding(payload.get("project_binding"))
        vendor_session_id = payload.get("vendor_session_id")
        harness_type = payload.get("harness_type")
    else:
        project_binding = validate_project_binding(payload.get("goal_project_binding"))
        vendor_session_id = payload.get("target_vendor_session_id")
        harness_type = payload.get("target_harness_type")
    expected = {
        "schema": "pex.human-operator-action-reservation.v1",
        "effect_id": str(effect["effect_id"]),
        "action_kind": action_kind,
        "principal_id": str(effect["principal_id"]),
        "actor_assurance": payload.get("actor_assurance"),
        "source_session_id": str(effect["source_session_id"]),
        "target_session_id": str(effect["target_session_id"]),
        "vendor_session_id": vendor_session_id,
        "harness_type": harness_type,
        "goal_id": str(effect["goal_id"]),
        "project_id": str(effect["project_id"]),
        "project_binding": project_binding,
        "request_hash": str(effect["request_hash"]),
        "delivery_contract_version": int(effect["delivery_contract_version"]),
        "reserved_at": str(effect["reserved_at"]),
        "schema_version": 1,
    }
    if (
        expected["principal_id"] != "local_bridge_operator"
        or expected["actor_assurance"] != OPERATOR_ACTOR_ASSURANCE
        or expected["delivery_contract_version"]
        != OPERATOR_DELIVERY_CONTRACT_EXACT_TURN
        or not isinstance(expected["vendor_session_id"], str)
        or not expected["vendor_session_id"]
        or not isinstance(expected["harness_type"], str)
        or not expected["harness_type"]
        or _SHA256_PATTERN.fullmatch(expected["request_hash"]) is None
    ):
        raise RuntimeError("assured operator reservation authority is corrupt")
    return expected


async def _insert_human_operator_action_reservation(
    transaction: aiosqlite.Connection,
    effect: dict[str, Any],
) -> dict[str, Any]:
    expected = _human_operator_action_reservation_payload(effect)
    await transaction.execute(
        "INSERT INTO human_operator_action_reservations("
        "effect_id, action_kind, principal_id, actor_assurance, source_session_id, "
        "target_session_id, goal_id, project_id, project_binding, request_hash, "
        "delivery_contract_version, reserved_at, schema_version, json) VALUES "
        "(?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, 1, ?)",
        (
            expected["effect_id"],
            expected["action_kind"],
            expected["principal_id"],
            expected["actor_assurance"],
            expected["source_session_id"],
            expected["target_session_id"],
            expected["goal_id"],
            expected["project_id"],
            expected["project_binding"],
            expected["request_hash"],
            expected["delivery_contract_version"],
            expected["reserved_at"],
            _canonical_json(expected),
        ),
    )
    return expected


def _human_operator_action_receipt_payload(effect: dict[str, Any]) -> dict[str, Any]:
    """Build the content-free actor receipt from one frozen terminal effect."""

    payload = effect.get("payload")
    result = effect.get("result")
    action_kind = effect.get("action_kind")
    if (
        not isinstance(payload, dict)
        or (
            action_kind == OPERATOR_MESSAGE_ACTION
            and payload.get("schema") != OPERATOR_ACTOR_PAYLOAD_SCHEMA
        )
        or (
            action_kind == OPERATOR_HANDOFF_ACTION
            and payload.get("schema") != OPERATOR_HANDOFF_ACTOR_PAYLOAD_SCHEMA
        )
        or action_kind not in {OPERATOR_MESSAGE_ACTION, OPERATOR_HANDOFF_ACTION}
        or effect.get("state") != "delivered"
        or not isinstance(result, dict)
        or not isinstance(effect.get("finished_at"), str)
    ):
        raise RuntimeError("assured operator effect is not a delivered direct message")
    if action_kind == OPERATOR_MESSAGE_ACTION:
        project_binding = validate_project_binding(payload.get("project_binding"))
        vendor_session_id = payload.get("vendor_session_id")
        harness_type = payload.get("harness_type")
    else:
        project_binding = validate_project_binding(payload.get("goal_project_binding"))
        vendor_session_id = payload.get("target_vendor_session_id")
        harness_type = payload.get("target_harness_type")
    result_hash = hashlib.sha256(_canonical_json(result).encode("utf-8")).hexdigest()
    expected = {
        "schema": OPERATOR_ACTOR_RECEIPT_SCHEMA,
        "id": _human_operator_action_receipt_id(str(effect["effect_id"])),
        "effect_id": str(effect["effect_id"]),
        "action_kind": action_kind,
        "principal_id": str(effect["principal_id"]),
        "actor_assurance": payload.get("actor_assurance"),
        "source_session_id": str(effect["source_session_id"]),
        "target_session_id": str(effect["target_session_id"]),
        "vendor_session_id": vendor_session_id,
        "harness_type": harness_type,
        "goal_id": str(effect["goal_id"]),
        "project_id": str(effect["project_id"]),
        "project_binding": project_binding,
        "request_hash": str(effect["request_hash"]),
        "delivery_contract_version": int(effect["delivery_contract_version"]),
        "effect_version": int(effect["version"]),
        "reserved_at": str(effect["reserved_at"]),
        "finished_at": str(effect["finished_at"]),
        "result_hash": result_hash,
    }
    if (
        expected["principal_id"] != "local_bridge_operator"
        or expected["actor_assurance"] != OPERATOR_ACTOR_ASSURANCE
        or expected["delivery_contract_version"]
        != OPERATOR_DELIVERY_CONTRACT_EXACT_TURN
        or not isinstance(expected["vendor_session_id"], str)
        or not expected["vendor_session_id"]
        or not isinstance(expected["harness_type"], str)
        or not expected["harness_type"]
        or _SHA256_PATTERN.fullmatch(expected["request_hash"]) is None
        or _SHA256_PATTERN.fullmatch(result_hash) is None
    ):
        raise RuntimeError("assured operator effect authority binding is corrupt")
    return expected


async def _validate_human_operator_action_receipt(
    transaction: aiosqlite.Connection,
    effect: dict[str, Any],
) -> dict[str, Any] | None:
    """Validate the prospective actor ledger without upgrading legacy effects."""

    payload = effect.get("payload")
    payload_assured = isinstance(payload, dict) and payload.get("schema") in {
        OPERATOR_ACTOR_PAYLOAD_SCHEMA,
        OPERATOR_HANDOFF_ACTOR_PAYLOAD_SCHEMA,
    }
    reservation_cursor = await transaction.execute(
        "SELECT * FROM human_operator_action_reservations WHERE effect_id = ?",
        (effect["effect_id"],),
    )
    reservation_row = await reservation_cursor.fetchone()
    cursor = await transaction.execute(
        "SELECT * FROM human_operator_terminal_actions WHERE effect_id = ?",
        (effect["effect_id"],),
    )
    row = await cursor.fetchone()
    if not payload_assured:
        if reservation_row is not None or row is not None:
            raise RuntimeError("legacy operator effect has an invented actor receipt")
        return None
    if reservation_row is None:
        raise RuntimeError("assured operator effect is missing its actor reservation")
    expected_reservation = _human_operator_action_reservation_payload(effect)
    reservation_fields = (
        "effect_id",
        "action_kind",
        "principal_id",
        "actor_assurance",
        "source_session_id",
        "target_session_id",
        "goal_id",
        "project_id",
        "project_binding",
        "request_hash",
        "delivery_contract_version",
        "reserved_at",
        "schema_version",
    )
    reservation_record = _strict_json_loads(str(reservation_row["json"]))
    if reservation_record != expected_reservation or any(
        reservation_row[field] != expected_reservation[field]
        for field in reservation_fields
    ):
        raise RuntimeError("human operator action reservation is corrupt")
    if effect.get("state") != "delivered":
        if row is not None:
            raise RuntimeError("non-delivered operator effect has an actor receipt")
        return None
    if row is None:
        raise RuntimeError("assured delivered operator effect is missing its actor receipt")
    expected = _human_operator_action_receipt_payload(effect)
    coverage_cursor = await transaction.execute(
        "SELECT * FROM human_operator_action_coverage WHERE action_kind = ?",
        (effect["action_kind"],),
    )
    coverage_row = await coverage_cursor.fetchone()
    if coverage_row is None:
        raise RuntimeError("assured operator action coverage is missing")
    coverage_record = _strict_json_loads(str(coverage_row["json"]))
    expected_coverage = {
        "schema": "pex.human-action-coverage.v1",
        "action_kind": str(effect["action_kind"]),
        "coverage_started_at": str(coverage_row["coverage_started_at"]),
        "actor_assurance": OPERATOR_ACTOR_ASSURANCE,
        "schema_version": 1,
    }
    if (
        coverage_record != expected_coverage
        or coverage_row["actor_assurance"] != OPERATOR_ACTOR_ASSURANCE
        or coverage_row["schema_version"] != 1
    ):
        raise RuntimeError("assured operator action coverage is corrupt")
    scalar_fields = (
        "id",
        "effect_id",
        "action_kind",
        "principal_id",
        "actor_assurance",
        "source_session_id",
        "target_session_id",
        "goal_id",
        "project_id",
        "project_binding",
        "request_hash",
        "delivery_contract_version",
        "effect_version",
        "reserved_at",
        "finished_at",
        "result_hash",
    )
    record = _strict_json_loads(str(row["json"]))
    if record != expected or any(row[field] != expected[field] for field in scalar_fields):
        raise RuntimeError("human operator terminal action receipt is corrupt")
    return expected


async def _insert_human_operator_action_receipt(
    transaction: aiosqlite.Connection,
    effect: dict[str, Any],
) -> dict[str, Any]:
    expected = _human_operator_action_receipt_payload(effect)
    await transaction.execute(
        "INSERT INTO human_operator_terminal_actions("
        "id, effect_id, action_kind, principal_id, actor_assurance, "
        "source_session_id, target_session_id, goal_id, project_id, project_binding, "
        "request_hash, delivery_contract_version, effect_version, reserved_at, "
        "finished_at, result_hash, json) VALUES "
        "(?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)",
        (
            expected["id"],
            expected["effect_id"],
            expected["action_kind"],
            expected["principal_id"],
            expected["actor_assurance"],
            expected["source_session_id"],
            expected["target_session_id"],
            expected["goal_id"],
            expected["project_id"],
            expected["project_binding"],
            expected["request_hash"],
            expected["delivery_contract_version"],
            expected["effect_version"],
            expected["reserved_at"],
            expected["finished_at"],
            expected["result_hash"],
            _canonical_json(expected),
        ),
    )
    validated = await _validate_human_operator_action_receipt(transaction, effect)
    if validated is None:  # pragma: no cover - insertion invariant
        raise RuntimeError("inserted human operator action receipt disappeared")
    return validated


def _overlay_operation_record(row: aiosqlite.Row) -> dict[str, Any]:
    record = dict(row)
    record["payload"] = _strict_json_loads(str(record["payload_json"]))
    raw_result = record.get("result_json")
    record["result"] = _strict_json_loads(str(raw_result)) if raw_result is not None else None
    return record


def _overlay_intent_payload(overlay: Overlay) -> dict[str, Any]:
    """Return the immutable overlay content, excluding lifecycle projection."""

    return {
        **overlay.model_dump(mode="json"),
        "applied_at": None,
        "expires_at": None,
        "reverted_at": None,
        "revert_reason": None,
        "promoted": False,
    }


def _overlay_hash(overlay: Overlay) -> str:
    return hashlib.sha256(
        _canonical_json(_overlay_intent_payload(overlay)).encode("utf-8")
    ).hexdigest()


def _overlay_time_value(overlay: Overlay, field: str) -> str | None:
    value = overlay.model_dump(mode="json").get(field)
    if value is None or isinstance(value, str):
        return value
    raise RuntimeError("overlay lifecycle timestamp is invalid")


def _overlay_timestamp(value: datetime) -> str:
    if value.tzinfo is None:
        raise ValueError("overlay timestamp must be timezone-aware")
    return value.astimezone(UTC).isoformat().replace("+00:00", "Z")


def _stored_overlay(raw: str | dict[str, Any]) -> Overlay:
    value = _strict_json_loads(raw) if isinstance(raw, str) else raw
    if not isinstance(value, dict):
        raise RuntimeError("stored overlay is not an object")
    payload = value.get("payload") if value.get("schema") == "pex.overlay-bound.v1" else value
    if not isinstance(payload, dict):
        raise RuntimeError("stored overlay payload is not an object")
    return Overlay.model_validate(payload)


def _bound_overlay_json(
    overlay: Overlay,
    *,
    session: HarnessSession,
    project_binding: str,
    overlay_hash: str,
    version: int,
) -> str:
    return _canonical_json(
        {
            "schema": "pex.overlay-bound.v1",
            "id": overlay.id,
            "session_id": session.id,
            "goal_id": session.goal_id,
            "project_id": _session_project(session),
            "project_binding": project_binding,
            "vendor_session_id": session.vendor_session_id,
            "harness_type": session.harness_type.value,
            "overlay_hash": overlay_hash,
            "version": version,
            "payload": overlay.model_dump(mode="json"),
        }
    )


def _overlay_action_hash(
    *,
    kind: str,
    overlay_hash: str,
    session_id: str,
    vendor_session_id: str,
    harness_type: str,
    goal_id: str | None,
    project_binding: str,
    adapter: str,
    apply_operation_id: str | None,
) -> str:
    payload = [
        "pex.overlay-action.v1",
        kind,
        overlay_hash,
        session_id,
        vendor_session_id,
        harness_type,
        goal_id,
        project_binding,
        adapter,
        apply_operation_id,
    ]
    return hashlib.sha256(_canonical_json(payload).encode("utf-8")).hexdigest()


def _overlay_request_hash(payload: dict[str, Any]) -> str:
    schema = payload.get("schema")
    if schema == "pex.overlay-apply.v1":
        request = {
            "schema": schema,
            "overlay": payload.get("overlay"),
            "adapter": payload.get("adapter"),
            "owner_intervention_id": payload.get("owner_intervention_id"),
            "parent_effect_id": payload.get("parent_effect_id"),
            "authorized_by": payload.get("authorized_by"),
            "idempotency_key": payload.get("idempotency_key"),
        }
    elif schema == "pex.overlay-revert.v1":
        request = {
            "schema": schema,
            "overlay_id": payload.get("overlay_id"),
            "session_id": payload.get("session_id"),
            "reason": payload.get("reason"),
            "adapter": payload.get("adapter"),
            "apply_operation_id": payload.get("apply_operation_id"),
            "trigger_intervention_id": payload.get("trigger_intervention_id"),
            "owner_intervention_id": payload.get("owner_intervention_id"),
            "parent_effect_id": payload.get("parent_effect_id"),
            "authorized_by": payload.get("authorized_by"),
            "idempotency_key": payload.get("idempotency_key"),
        }
    else:
        raise RuntimeError("overlay operation request schema is invalid")
    return hashlib.sha256(_canonical_json(request).encode("utf-8")).hexdigest()


def _overlay_operation_payload_json(
    operation: dict[str, Any],
    *,
    state: str,
    version: int,
) -> str:
    payload = dict(operation["payload"])
    payload["state"] = state
    payload["version"] = version
    return _canonical_json(payload)


def _overlay_operation_grant(
    operation: dict[str, Any],
    overlay: Overlay,
    session: HarnessSession,
    *,
    granted: bool,
    replayed: bool,
) -> dict[str, Any]:
    """Return the canonical frozen I/O bundle while retaining legacy flat keys."""

    return {
        **operation,
        "granted": granted,
        "replayed": replayed,
        "operation": operation,
        "overlay": overlay,
        "session": session,
        "adapter": str(operation["payload"].get("adapter") or ""),
        "rollback": dict(overlay.rollback),
    }


def event_semantic_payload(event: HarnessEvent) -> dict[str, Any]:
    """Return the exact collision payload, excluding only the ingest timestamp.

    Hook transports may synthesize a fresh top-level timestamp when replaying an
    otherwise identical vendor event.  Nested timestamps, metadata, content,
    and every identity binding remain semantic and therefore collision-bearing.
    """

    payload = event.model_dump(mode="json")
    payload.pop("ts", None)
    return payload


def event_semantic_hash(event: HarnessEvent) -> str:
    return hashlib.sha256(
        _canonical_json(event_semantic_payload(event)).encode("utf-8")
    ).hexdigest()


def stable_event_effect_id(event_id: str, effect_key: str) -> str:
    _validate_store_id(event_id, label="event id")
    _validate_store_id(effect_key, label="event effect key")
    encoded = _canonical_json(["pex.event-effect.v1", event_id, effect_key])
    digest = hashlib.sha256(encoded.encode("utf-8")).hexdigest()
    return f"effect_{digest[:40]}"


def stable_operator_effect_id(
    principal_id: str,
    action_kind: str,
    idempotency_key: str,
) -> str:
    _validate_store_id(principal_id, label="operator effect principal")
    _validate_store_id(action_kind, label="operator effect action")
    if _MCP_REQUEST_ID_PATTERN.fullmatch(idempotency_key) is None:
        raise ValueError("operator effect idempotency key is invalid")
    encoded = _canonical_json(
        ["pex.operator-effect.v1", principal_id, action_kind, idempotency_key]
    )
    digest = hashlib.sha256(encoded.encode("utf-8")).hexdigest()
    return f"operator_effect_{digest[:40]}"


def stable_operator_artifact_id(effect_id: str, artifact_kind: str) -> str:
    _validate_store_id(effect_id, label="operator effect id")
    _validate_store_id(artifact_kind, label="operator artifact kind")
    encoded = _canonical_json(["pex.operator-artifact.v1", effect_id, artifact_kind])
    digest = hashlib.sha256(encoded.encode("utf-8")).hexdigest()
    prefix = "handoff_request" if artifact_kind == "event" else "int_handoff"
    return f"{prefix}_{digest[:40]}"


def stable_overlay_operation_id(overlay_id: str, kind: str, *, attempt: int = 0) -> str:
    _validate_store_id(overlay_id, label="overlay id")
    if kind not in {"apply", "revert"}:
        raise ValueError("overlay operation kind is invalid")
    if not isinstance(attempt, int) or isinstance(attempt, bool) or attempt < 0:
        raise ValueError("overlay operation attempt is invalid")
    encoded = _canonical_json(
        ["pex.overlay-operation.v1", overlay_id, kind]
        if attempt == 0
        else ["pex.overlay-operation.v1", overlay_id, kind, attempt]
    )
    digest = hashlib.sha256(encoded.encode("utf-8")).hexdigest()
    return f"overlay_operation_{digest[:40]}"


def _overlay_session_binding(session: HarnessSession) -> dict[str, Any]:
    """Freeze the identity/config boundary an overlay was authorized against."""

    return {
        "session_id": session.id,
        "vendor_session_id": session.vendor_session_id,
        "harness_type": session.harness_type.value,
        "project_id": session.project_id,
        "goal_id": session.goal_id,
        "cwd": session.cwd,
    }


def _decision_session_binding(session: HarnessSession) -> dict[str, Any]:
    """Freeze the immutable vendor target for a later human-authorized dispatch."""

    return {
        **_overlay_session_binding(session),
        "capabilities": session.capabilities,
    }


def _resolution_session_target_matches(
    frozen: object,
    session: HarnessSession,
) -> bool:
    """Compare only the immutable adapter target during terminal bookkeeping."""

    if not isinstance(frozen, dict):
        return False
    target = _overlay_session_binding(session)
    return all(frozen.get(key) == value for key, value in target.items())


def _decision_intervention_binding(intervention: Intervention) -> dict[str, Any]:
    """Freeze the exact audited action rather than trusting caller-supplied ids."""

    return {
        "intervention_id": intervention.id,
        "session_id": intervention.session_id,
        "goal_id": intervention.goal_id,
        "created_at": intervention.created_at.isoformat(),
        "proposed_action": intervention.proposed_action.model_dump(mode="json"),
    }


def stable_event_artifact_id(
    event_id: str,
    artifact_key: str,
    *,
    index: int = 0,
) -> str:
    """Mint a replay-stable local projection id from one canonical event."""

    _validate_store_id(event_id, label="event id")
    _validate_store_id(artifact_key, label="event artifact key")
    if not isinstance(index, int) or isinstance(index, bool) or index < 0:
        raise ValueError("event artifact index is invalid")
    encoded = _canonical_json(["pex.event-artifact.v1", event_id, artifact_key, index])
    digest = hashlib.sha256(encoded.encode("utf-8")).hexdigest()
    prefix = re.sub(r"[^a-z0-9]+", "_", artifact_key.casefold()).strip("_")[:24]
    return f"{prefix or 'artifact'}_{digest[:40]}"


def _human_decision_response(
    *,
    intervention: Intervention,
    session: HarnessSession,
    decision: Decision,
    context: ContextItem,
    resolution: dict[str, Any],
) -> dict[str, Any]:
    public_resolution = {key: value for key, value in resolution.items() if key != "response"}
    status = str(public_resolution.get("status") or "")
    delivered = status == "delivered"
    return {
        "ok": delivered,
        "kind": "human_decision",
        "resolved": True,
        "decision_recorded": True,
        "delivered": delivered,
        "delivery_status": status,
        "session_status": session.status.value,
        "resolution": public_resolution,
        "decision": decision.model_dump(mode="json"),
        "context": context.model_dump(mode="json"),
        "intervention": intervention.model_dump(mode="json"),
        "session": session.model_dump(mode="json"),
    }


async def _update_human_decision_mutation_response(
    transaction: aiosqlite.Connection,
    *,
    intervention_id: str,
    response: dict[str, Any],
) -> None:
    response_json = _canonical_json(response)
    if len(response_json.encode("utf-8")) > 1_000_000:
        raise ValueError("MCP mutation response is too large")
    cursor = await transaction.execute(
        "SELECT mutation_id, json FROM mcp_mutations WHERE intervention_id = ? AND tool = ?",
        (intervention_id, MCP_REQUEST_DECISION_TOOL),
    )
    rows = await cursor.fetchall()
    if len(rows) != 1:
        raise ValueError("human decision mutation binding is missing or ambiguous")
    receipt = _strict_json_loads(str(rows[0]["json"]))
    if not isinstance(receipt, dict):
        raise RuntimeError("stored MCP mutation receipt is not an object")
    receipt["response"] = response
    await transaction.execute(
        "UPDATE mcp_mutations SET response_json = ?, json = ? WHERE mutation_id = ?",
        (response_json, _canonical_json(receipt), str(rows[0]["mutation_id"])),
    )


def _dump(model: Any) -> str:
    return model.model_dump_json()


def _context_bundle_wire_tokens(bundle: ContextBundle) -> int:
    """Recompute the complete UTF-8 wire estimate used by the mesh builder."""

    estimate = 0
    for _ in range(4):
        rendered = bundle.model_copy(update={"token_estimate": estimate}).model_dump_json()
        updated = max(1, (len(rendered.encode("utf-8", "replace")) + 3) // 4)
        if updated == estimate:
            break
        estimate = updated
    return estimate


def _context_bundle_digest(bundle: ContextBundle) -> str:
    return hashlib.sha256(
        _canonical_json(bundle.model_dump(mode="json")).encode("utf-8")
    ).hexdigest()


@dataclass(frozen=True)
class _ArtifactPath:
    relative: str
    windows_semantics: bool


def _canonical_project_artifact_path(
    value: object,
    *,
    project_id: str,
) -> _ArtifactPath | None:
    """Bind an exact path to its frozen project root without suffix matching."""

    if not isinstance(value, str) or not value or value != value.strip():
        return None
    if any(category(char).startswith("C") for char in value):
        return None
    if not isinstance(project_id, str) or not project_id:
        return None

    windows_root = bool(ntpath.splitdrive(project_id)[0]) and ntpath.isabs(project_id)
    windows_value = bool(ntpath.splitdrive(value)[0]) and ntpath.isabs(value)
    posix_root = posixpath.isabs(project_id) and not windows_root
    posix_value = posixpath.isabs(value) and not windows_value
    if windows_value:
        if not windows_root:
            return None
        _, raw_tail = ntpath.splitdrive(value)
        if any(part in {".", ".."} for part in raw_tail.replace("/", "\\").split("\\")):
            return None
        root = ntpath.normpath(project_id)
        candidate = ntpath.normpath(value)
        try:
            relative = ntpath.relpath(candidate, root)
        except ValueError:
            return None
        if relative in {"", ".", ".."} or relative.startswith(f"..{ntpath.sep}"):
            return None
        return _ArtifactPath(relative.replace("\\", "/"), True)
    if posix_value:
        if not posix_root:
            return None
        if any(part in {".", ".."} for part in value.split("/")):
            return None
        root = posixpath.normpath(project_id)
        candidate = posixpath.normpath(value)
        relative = posixpath.relpath(candidate, root)
        if relative in {"", ".", ".."} or relative.startswith("../"):
            return None
        return _ArtifactPath(relative, False)
    if windows_root and ntpath.isabs(value):
        # A drive-root-relative spelling such as \foo omits the frozen drive
        # authority and must not be treated as a project-relative artifact.
        return None
    if ntpath.splitdrive(value)[0]:
        # Drive-relative spellings such as C:foo are not rooted evidence.
        return None

    normalized_separators = value.replace("\\", "/") if windows_root else value
    normalized = posixpath.normpath(normalized_separators)
    if normalized in {"", ".", ".."} or normalized.startswith("../"):
        return None
    if normalized_separators.startswith("./"):
        normalized_separators = normalized_separators[2:]
    if posixpath.normpath(normalized_separators) != normalized:
        return None
    return _ArtifactPath(normalized, windows_root)


def _artifact_paths_match(left: _ArtifactPath, right: _ArtifactPath) -> bool:
    if left.windows_semantics and right.windows_semantics:
        return _windows_artifact_case_key(left.relative) == _windows_artifact_case_key(
            right.relative
        )
    return left.relative == right.relative


def _windows_artifact_case_key(value: str) -> str:
    """Conservatively fold ASCII without Unicode expansion false positives."""

    return value.translate(_WINDOWS_ASCII_LOWER)


def _artifact_path_hash(value: str) -> str:
    return hashlib.sha256(value.encode("utf-8")).hexdigest()


def _handoff_context_candidate_id(effect_id: str, context_item_id: str) -> str:
    identity = {
        "effect_id": effect_id,
        "context_item_id": context_item_id,
    }
    return "hcc_" + hashlib.sha256(
        _canonical_json(identity).encode("utf-8")
    ).hexdigest()[:40]


def _handoff_artifact_candidate_id(
    effect_id: str,
    context_item_id: str,
    path: _ArtifactPath,
) -> str:
    identity = {
        "effect_id": effect_id,
        "context_item_id": context_item_id,
        "source_relative_path": path.relative,
        "source_windows_semantics": path.windows_semantics,
    }
    return "hac_" + hashlib.sha256(
        _canonical_json(identity).encode("utf-8")
    ).hexdigest()[:40]


def _handoff_item_artifact_paths(
    bundle: ContextBundle,
    *,
    source_project_id: str,
) -> dict[str, set[_ArtifactPath]]:
    paths: dict[str, set[_ArtifactPath]] = {}
    for item in bundle.items:
        raw_paths = item.metadata.get("files")
        if not isinstance(raw_paths, list):
            continue
        normalized = {
            path
            for raw in raw_paths
            if (
                path := _canonical_project_artifact_path(
                    raw,
                    project_id=source_project_id,
                )
            )
            is not None
        }
        if normalized:
            paths[item.id] = normalized
    return paths


def _time_key(value: datetime | None) -> datetime:
    if value is None:
        return datetime.min.replace(tzinfo=UTC)
    if value.tzinfo is None:
        return value.replace(tzinfo=UTC)
    return value.astimezone(UTC)


def _project_key(value: str) -> str:
    return value.strip().replace("\\", "/").rstrip("/").casefold()


def _same_project(left: str, right: str) -> bool:
    return _project_key(left) == _project_key(right)


def _legacy_artifact_project_binding(project_id: str) -> str:
    """Bind historical evidence to its exact raw key without consulting live identity."""

    digest = hashlib.sha256(project_id.encode("utf-8")).hexdigest()
    return f"legacy:{digest}"


def _validate_store_id(value: str, *, label: str) -> None:
    if not isinstance(value, str) or not value.strip() or len(value) > MAX_STORE_ID_LENGTH:
        raise ValueError(f"{label} is invalid")


def _validate_query_page(*, label: str, limit: int, offset: int) -> None:
    if (
        not isinstance(limit, int)
        or isinstance(limit, bool)
        or not 1 <= limit <= MAX_LIST_QUERY_LIMIT
    ):
        raise ValueError(f"{label} limit must be between 1 and {MAX_LIST_QUERY_LIMIT}")
    if not isinstance(offset, int) or isinstance(offset, bool) or offset < 0:
        raise ValueError(f"{label} offset cannot be negative")


def _utc_iso(value: datetime) -> str:
    return _time_key(value).isoformat()


_GOAL_LEDGER_KINDS = frozenset(
    {"decision", "rejected_approach", "unresolved_question"}
)


def _reject_managed_goal_ledger_artifact(
    artifact: Decision | ContextItem,
    *,
    label: str,
) -> None:
    if str(artifact.metadata.get("kind") or "") in _GOAL_LEDGER_KINDS:
        raise ValueError(
            f"managed goal ledger {label} must use the atomic goal mutation boundary"
        )


def _canonical_active_goal_ledger(
    goal: Goal,
    decisions: Sequence[Decision],
    context_items: Sequence[ContextItem],
) -> list[dict[str, str]]:
    """Validate paired human ledger projections and discard only retired history."""

    decisions_by_id: dict[str, Decision] = {}
    for decision in decisions:
        if decision.id in decisions_by_id:
            raise ValueError("goal intent contains a duplicate Decision id")
        decisions_by_id[decision.id] = decision

    contexts_by_id: dict[str, ContextItem] = {}
    contexts_by_decision: dict[str, list[ContextItem]] = {}
    for context in context_items:
        if context.id in contexts_by_id:
            raise ValueError("goal intent contains a duplicate ContextItem id")
        contexts_by_id[context.id] = context
        metadata_decision_id = context.metadata.get("decision_id")
        referenced_decision_id = (
            context.source_refs[0] if len(context.source_refs) == 1 else None
        )
        candidate_ids = {
            value
            for value in (metadata_decision_id, referenced_decision_id)
            if isinstance(value, str) and value
        }
        for decision_id in candidate_ids:
            contexts_by_decision.setdefault(decision_id, []).append(context)

    managed_decisions = {
        decision.id: decision
        for decision in decisions
        if str(decision.metadata.get("kind") or "") in _GOAL_LEDGER_KINDS
    }
    for context in context_items:
        context_kind = str(context.metadata.get("kind") or "")
        if context_kind not in _GOAL_LEDGER_KINDS:
            continue
        decision_id = context.metadata.get("decision_id")
        if not isinstance(decision_id, str) or decision_id not in managed_decisions:
            raise ValueError("goal intent contains an orphan managed ContextItem")

    entries: list[dict[str, str]] = []
    semantic_keys: set[tuple[str, str]] = set()
    for decision in managed_decisions.values():
        kind = str(decision.metadata["kind"])
        if decision.goal_id != goal.id:
            raise ValueError("goal intent Decision goal binding is inconsistent")
        if decision.source != DecisionSource.HUMAN:
            raise ValueError("goal intent Decision must have human provenance")
        if decision.sensitivity != Sensitivity.INTERNAL:
            raise ValueError("goal intent Decision sensitivity is inconsistent")

        matching_contexts = contexts_by_decision.get(decision.id, [])
        if len(matching_contexts) != 1:
            raise ValueError("goal intent Decision must have exactly one ContextItem projection")
        context = matching_contexts[0]
        expected_status = (
            DecisionStatus.UNCERTAIN
            if kind == "unresolved_question"
            else DecisionStatus.ACTIVE
        )
        retired = decision.status == DecisionStatus.SUPERSEDED
        expected_context_status = (
            DecisionStatus.SUPERSEDED.value if retired else expected_status.value
        )
        if (
            context.goal_id != goal.id
            or context.project_id != goal.project_id
            or context.kind != ContextKind.DECISION
            or context.content != decision.statement
            or context.source_refs != [decision.id]
            or context.provenance != SourceKind.HUMAN
            or context.sensitivity != Sensitivity.INTERNAL
            or context.metadata.get("decision_id") != decision.id
            or context.metadata.get("kind") != kind
            or context.metadata.get("status") != expected_context_status
            or context.metadata.get("unresolved") is not (kind == "unresolved_question")
            or _time_key(context.valid_from) != _time_key(decision.created_at)
        ):
            raise ValueError("goal intent Decision/ContextItem projection is inconsistent")
        if retired:
            if context.stale_after is None:
                raise ValueError("superseded goal intent ContextItem is still live")
            continue
        if decision.status != expected_status:
            raise ValueError("live goal intent Decision status is inconsistent")
        if decision.metadata.get("superseded_at") is not None or context.stale_after is not None:
            raise ValueError("live goal intent projection is marked superseded")

        statement = decision.statement.strip()
        if not statement:
            raise ValueError("goal intent Decision statement is empty")
        semantic_key = (kind, statement.casefold())
        if semantic_key in semantic_keys:
            raise ValueError("goal intent contains a duplicate live semantic entry")
        semantic_keys.add(semantic_key)
        entries.append(
            {
                "kind": kind,
                "status": expected_status.value,
                "statement": statement,
            }
        )

    return sorted(
        entries,
        key=lambda item: (
            item["kind"],
            item["statement"].casefold(),
            item["statement"],
        ),
    )


def canonical_goal_intent_payload(
    goal: Goal,
    *,
    decisions: Sequence[Decision] = (),
    context_items: Sequence[ContextItem] = (),
) -> dict[str, Any]:
    """Return identity-free, execution-relevant persistent intent."""

    return {
        "schema": "pex.goal-intent-state.v1",
        "title": goal.title,
        "objective": goal.objective,
        "acceptance_criteria": list(goal.acceptance_criteria),
        "constraints": list(goal.constraints),
        "preferences": list(goal.preferences),
        "forbidden_outcomes": list(goal.forbidden_outcomes),
        "non_goals": list(goal.non_goals),
        "priority": goal.priority,
        "deadline": _utc_iso(goal.deadline) if goal.deadline is not None else None,
        "evidence_requirements": list(goal.evidence_requirements),
        "paused": goal.paused,
        "ledger": _canonical_active_goal_ledger(goal, decisions, context_items),
    }


def goal_intent_semantic_hash(
    goal: Goal,
    *,
    decisions: Sequence[Decision] = (),
    context_items: Sequence[ContextItem] = (),
) -> str:
    """Return lowercase SHA-256 of canonical persistent intent."""

    payload = canonical_goal_intent_payload(
        goal,
        decisions=decisions,
        context_items=context_items,
    )
    return hashlib.sha256(_canonical_json(payload).encode("utf-8")).hexdigest()


def _prospective_goal_intent_hash(
    goal: Goal,
    *,
    current_ledger: Sequence[dict[str, str]] = (),
    projections: Sequence[tuple[Decision, ContextItem]] = (),
    replace_ledger_kinds: frozenset[str] = frozenset(),
) -> str:
    invalid_kinds = replace_ledger_kinds - _GOAL_LEDGER_KINDS
    if invalid_kinds:
        raise ValueError(
            f"goal ledger replacement kind is invalid: {sorted(invalid_kinds)[0]}"
        )
    incoming = canonical_goal_intent_payload(
        goal,
        decisions=[pair[0] for pair in projections],
        context_items=[pair[1] for pair in projections],
    )["ledger"]
    ledger = [
        dict(item)
        for item in current_ledger
        if item["kind"] not in replace_ledger_kinds
    ]
    seen = {(item["kind"], item["statement"].strip().casefold()) for item in ledger}
    for item in incoming:
        key = (item["kind"], item["statement"].strip().casefold())
        if key in seen:
            continue
        ledger.append(dict(item))
        seen.add(key)
    ledger.sort(
        key=lambda item: (
            item["kind"],
            item["statement"].casefold(),
            item["statement"],
        )
    )
    payload = canonical_goal_intent_payload(goal)
    payload["ledger"] = ledger
    return hashlib.sha256(_canonical_json(payload).encode("utf-8")).hexdigest()


def _goal_ledger_projections_from_entries(
    goal: Goal,
    entries: Sequence[dict[str, str]],
) -> list[tuple[Decision, ContextItem]]:
    """Clone semantic ledger entries onto a successor without copying history identity."""

    created_at = utcnow()
    projections: list[tuple[Decision, ContextItem]] = []
    for entry in entries:
        kind = entry["kind"]
        if kind not in _GOAL_LEDGER_KINDS:
            raise ValueError("goal ledger inheritance kind is invalid")
        expected_status = (
            DecisionStatus.UNCERTAIN
            if kind == "unresolved_question"
            else DecisionStatus.ACTIVE
        )
        if entry["status"] != expected_status.value:
            raise ValueError("goal ledger inheritance status is invalid")
        statement = entry["statement"].strip()
        if not statement:
            raise ValueError("goal ledger inheritance statement is empty")
        decision = Decision(
            id=new_id("dec_"),
            goal_id=goal.id,
            statement=statement,
            rationale="Inherited from the superseded persistent intent ledger.",
            alternatives_rejected=[statement] if kind == "rejected_approach" else [],
            source=DecisionSource.HUMAN,
            status=expected_status,
            created_at=created_at,
            sensitivity=Sensitivity.INTERNAL,
            metadata={"kind": kind},
        )
        context = ContextItem(
            id=new_id("ctx_"),
            project_id=goal.project_id,
            goal_id=goal.id,
            kind=ContextKind.DECISION,
            content=statement,
            source_refs=[decision.id],
            provenance=SourceKind.HUMAN,
            confidence=0.9,
            relevance_tags=["decision", kind],
            valid_from=created_at,
            sensitivity=Sensitivity.INTERNAL,
            metadata={
                "decision_id": decision.id,
                "kind": kind,
                "status": expected_status.value,
                "unresolved": kind == "unresolved_question",
            },
        )
        projections.append((decision, context))
    return projections


async def _load_goal_intent_artifacts(
    transaction: aiosqlite.Connection,
    goal: Goal,
    binding: ArtifactBinding,
) -> tuple[list[Decision], list[ContextItem]]:
    """Load one bounded, scalar-bound Decision/Context projection snapshot."""

    decision_cursor = await transaction.execute(
        "SELECT id, goal_id, project_id, project_binding, json FROM decisions "
        "WHERE goal_id = ? AND project_binding = ? ORDER BY id LIMIT 10001",
        (goal.id, binding.project_binding),
    )
    decision_rows = await decision_cursor.fetchall()
    if len(decision_rows) > 10_000:
        raise RuntimeError("goal intent Decision scan is bounded")
    decisions: list[Decision] = []
    for row in decision_rows:
        try:
            decision = Decision.model_validate_json(row["json"])
        except (TypeError, ValueError) as exc:
            raise RuntimeError("stored goal intent Decision is corrupt") from exc
        if (
            decision.id != row["id"]
            or decision.goal_id != row["goal_id"]
            or decision.goal_id != goal.id
            or row["project_id"] != binding.project_id
            or row["project_binding"] != binding.project_binding
        ):
            raise RuntimeError("stored goal intent Decision binding is corrupt")
        decisions.append(decision)

    context_cursor = await transaction.execute(
        "SELECT id, project_id, project_binding, goal_id, json FROM context_items "
        "WHERE project_binding = ? AND goal_id = ? ORDER BY id LIMIT 10001",
        (binding.project_binding, goal.id),
    )
    context_rows = await context_cursor.fetchall()
    if len(context_rows) > 10_000:
        raise RuntimeError("goal intent ContextItem scan is bounded")
    context_items: list[ContextItem] = []
    for row in context_rows:
        try:
            context = ContextItem.model_validate_json(row["json"])
        except (TypeError, ValueError) as exc:
            raise RuntimeError("stored goal intent ContextItem is corrupt") from exc
        if (
            context.id != row["id"]
            or context.project_id != row["project_id"]
            or row["project_binding"] != binding.project_binding
            or context.goal_id != row["goal_id"]
        ):
            raise RuntimeError("stored goal intent ContextItem binding is corrupt")
        if context.goal_id != goal.id:
            raise RuntimeError("stored goal intent ContextItem goal binding is corrupt")
        context_items.append(context)
    return decisions, context_items


async def _goal_intent_hash_in_transaction(
    transaction: aiosqlite.Connection,
    goal: Goal,
    binding: ArtifactBinding,
) -> str:
    decisions, context_items = await _load_goal_intent_artifacts(
        transaction,
        goal,
        binding,
    )
    return goal_intent_semantic_hash(
        goal,
        decisions=decisions,
        context_items=context_items,
    )


def _validate_goal_intent_scalar_pair(
    revision: object,
    semantic_hash: object,
) -> tuple[int, str]:
    if (
        not isinstance(revision, int)
        or isinstance(revision, bool)
        or revision < 0
        or not isinstance(semantic_hash, str)
        or _SHA256_PATTERN.fullmatch(semantic_hash) is None
    ):
        raise RuntimeError("stored goal intent authority is corrupt")
    return revision, semantic_hash


def _validated_progress_evidence_refs(
    evidence_refs: list[ProgressEvidenceReference | dict[str, Any]]
    | tuple[ProgressEvidenceReference | dict[str, Any], ...],
) -> tuple[ProgressEvidenceReference, ...]:
    if not isinstance(evidence_refs, (list, tuple)) or not 1 <= len(evidence_refs) <= 24:
        raise ValueError("progress evidence refs must contain between 1 and 24 items")
    refs = tuple(ProgressEvidenceReference.model_validate(item) for item in evidence_refs)
    keys = [(item.type, item.id) for item in refs]
    if len(keys) != len(set(keys)):
        raise ValueError("progress evidence refs must be unique")
    return tuple(sorted(refs, key=lambda item: (item.type, item.id)))


def reported_progress_request_fingerprint(
    *,
    principal_id: str,
    tool: str,
    session_id: str,
    goal_id: str,
    project_id: str,
    summary: str,
    evidence_refs: list[ProgressEvidenceReference | dict[str, Any]]
    | tuple[ProgressEvidenceReference | dict[str, Any], ...],
) -> str:
    """Hash the canonical semantic request; transport request IDs are the replay key."""

    if tool != MCP_REPORT_PROGRESS_TOOL:
        raise ValueError("unsupported MCP mutation tool")
    _validate_store_id(principal_id, label="MCP principal id")
    _validate_store_id(session_id, label="progress session id")
    _validate_store_id(goal_id, label="progress goal id")
    if (
        not isinstance(project_id, str)
        or not project_id.strip()
        or len(project_id) > MAX_PROJECT_ID_LENGTH
    ):
        raise ValueError("progress project id is invalid")
    if not isinstance(summary, str) or not summary.strip() or len(summary) > 4_000:
        raise ValueError("progress summary is invalid")
    refs = _validated_progress_evidence_refs(evidence_refs)
    payload = {
        "schema": MCP_PROGRESS_FINGERPRINT_SCHEMA,
        "principal_id": principal_id,
        "tool": tool,
        "session_id": session_id,
        "goal_id": goal_id,
        "project": _project_key(project_id),
        "summary": summary,
        "evidence_refs": [item.model_dump(mode="json") for item in refs],
    }
    return hashlib.sha256(_canonical_json(payload).encode("utf-8")).hexdigest()


def human_decision_request_fingerprint(
    *,
    tool: str,
    session_id: str,
    goal_id: str,
    project_id: str,
    vendor_session_id: str,
    harness_type: str,
    question: str,
    options: list[str] | tuple[str, ...],
    urgency: str,
    context: str,
) -> str:
    """Hash one stable worker binding and its semantic decision request."""

    if tool != MCP_REQUEST_DECISION_TOOL:
        raise ValueError("unsupported MCP mutation tool")
    _validate_store_id(session_id, label="decision session id")
    _validate_store_id(goal_id, label="decision goal id")
    _validate_store_id(vendor_session_id, label="decision vendor session id")
    try:
        parsed_harness = HarnessType(harness_type)
    except (TypeError, ValueError) as exc:
        raise ValueError("decision harness type is invalid") from exc
    if (
        not isinstance(project_id, str)
        or not project_id.strip()
        or len(project_id) > MAX_PROJECT_ID_LENGTH
    ):
        raise ValueError("decision project id is invalid")
    request = HumanDecisionRequest.model_validate(
        {
            "idempotency_key": "fingerprint-only",
            "question": question,
            "options": options,
            "urgency": urgency,
            "context": context,
        }
    )
    payload = {
        "schema": MCP_DECISION_FINGERPRINT_SCHEMA,
        "tool": tool,
        "session_id": session_id,
        "goal_id": goal_id,
        "project": _project_key(project_id),
        "vendor_session_id": vendor_session_id,
        "harness_type": parsed_harness.value,
        "question": request.question,
        "options": list(request.options),
        "urgency": request.urgency,
        "context": request.context,
    }
    return hashlib.sha256(_canonical_json(payload).encode("utf-8")).hexdigest()


def human_decision_logical_key(
    *,
    tool: str,
    request_id: str,
    session_id: str,
    goal_id: str,
    project_id: str,
    vendor_session_id: str,
    harness_type: str,
) -> str:
    """Return a principal-independent key for one exact worker-bound request."""

    if tool != MCP_REQUEST_DECISION_TOOL:
        raise ValueError("unsupported MCP mutation tool")
    if _MCP_REQUEST_ID_PATTERN.fullmatch(request_id) is None:
        raise ValueError("MCP mutation request id is invalid")
    _validate_store_id(session_id, label="decision session id")
    _validate_store_id(goal_id, label="decision goal id")
    _validate_store_id(vendor_session_id, label="decision vendor session id")
    try:
        parsed_harness = HarnessType(harness_type)
    except (TypeError, ValueError) as exc:
        raise ValueError("decision harness type is invalid") from exc
    if (
        not isinstance(project_id, str)
        or not project_id.strip()
        or len(project_id) > MAX_PROJECT_ID_LENGTH
    ):
        raise ValueError("decision project id is invalid")
    payload = {
        "schema": MCP_DECISION_LOGICAL_KEY_SCHEMA,
        "tool": tool,
        "request_id": request_id,
        "session_id": session_id,
        "goal_id": goal_id,
        "project": _project_key(project_id),
        "vendor_session_id": vendor_session_id,
        "harness_type": parsed_harness.value,
    }
    return hashlib.sha256(_canonical_json(payload).encode("utf-8")).hexdigest()[:40]


def human_decision_choice_receipt(choice: str, *, freeform: bool) -> str:
    """Return the only form of a human choice permitted in durable records."""

    if (
        not isinstance(choice, str)
        or not choice
        or len(choice) > 500
        or choice != choice.strip()
        or any(category(char).startswith("C") for char in choice)
    ):
        raise ValueError("human decision choice is invalid")
    if freeform:
        digest = hashlib.sha256(choice.encode("utf-8")).hexdigest()
        return f"[freeform answer sha256:{digest}]"
    canonical, _ = redact_text(choice)
    if not isinstance(canonical, str) or not canonical:
        raise ValueError("redacted human decision choice is invalid")
    return canonical


def claim_verification_request_fingerprint(
    *,
    principal_id: str,
    tool: str,
    session_id: str,
    goal_id: str,
    project_id: str,
    claim: str,
) -> str:
    """Hash one principal- and goal-bound claim verification request."""

    if tool != MCP_VERIFY_CLAIM_TOOL:
        raise ValueError("unsupported MCP mutation tool")
    _validate_store_id(principal_id, label="MCP principal id")
    _validate_store_id(session_id, label="claim verification session id")
    _validate_store_id(goal_id, label="claim verification goal id")
    if (
        not isinstance(project_id, str)
        or not project_id.strip()
        or len(project_id) > MAX_PROJECT_ID_LENGTH
    ):
        raise ValueError("claim verification project id is invalid")
    if not isinstance(claim, str) or not claim.strip() or len(claim) > 4_000:
        raise ValueError("claim verification statement is invalid")
    payload = {
        "schema": MCP_CLAIM_VERIFY_FINGERPRINT_SCHEMA,
        "principal_id": principal_id,
        "tool": tool,
        "session_id": session_id,
        "goal_id": goal_id,
        "project": _project_key(project_id),
        "claim": claim,
    }
    return hashlib.sha256(_canonical_json(payload).encode("utf-8")).hexdigest()


async def _configure_connection(connection: aiosqlite.Connection) -> None:
    """Apply the durability and contention policy to every SQLite connection."""

    connection.row_factory = aiosqlite.Row
    await connection.execute("PRAGMA busy_timeout=5000")
    await connection.execute("PRAGMA synchronous=FULL")
    await connection.execute("PRAGMA foreign_keys=ON")


def _audit_projection_payload(value: dict[str, Any]) -> str:
    payload = dict(value)
    payload.pop("audit_id", None)
    return json.dumps(
        payload,
        ensure_ascii=False,
        sort_keys=True,
        separators=(",", ":"),
    )


def _validate_intervention_identity(
    intervention: Intervention,
    existing: Intervention | None = None,
) -> None:
    action = intervention.proposed_action
    if action.session_id != intervention.session_id:
        raise ValueError("intervention/action session identity mismatch")
    if action.goal_id != intervention.goal_id:
        raise ValueError("intervention/action goal identity mismatch")
    if existing is None:
        return
    if existing.session_id != intervention.session_id:
        raise ValueError("an intervention update cannot change session identity")
    if existing.goal_id != intervention.goal_id:
        raise ValueError("an intervention update cannot change goal identity")
    if _time_key(existing.created_at) != _time_key(intervention.created_at):
        raise ValueError("an intervention update cannot change its creation timestamp")
    if existing.proposed_action != intervention.proposed_action:
        raise ValueError("an intervention update cannot change its proposed action")


def _validate_event_delivery_update(
    reserved: Intervention,
    finalized: Intervention,
) -> None:
    """Allow delivery truth to change without rewriting the reserved proposal."""

    _validate_intervention_identity(finalized, reserved)
    immutable_fields = (
        "trigger",
        "evidence",
        "diagnosis",
        "proposed_action",
        "confidence",
        "risk",
        "reversible",
        "authority_required",
        "action_taken",
        "policy_verdict",
        "created_at",
    )
    for field in immutable_fields:
        if getattr(reserved, field) != getattr(finalized, field):
            raise ValueError(f"event delivery cannot change intervention {field}")
    mutable_metadata = {
        "delivery",
        "delivery_code",
        "effect_id",
        "effect_state",
        "remote_notify",
        "verification",
        "worker_delivery_receipt",
        "hook_preparation_receipt",
    }
    reserved_metadata = reserved.metadata or {}
    finalized_metadata = finalized.metadata or {}
    for key in set(reserved_metadata) | set(finalized_metadata):
        if key in mutable_metadata:
            continue
        if reserved_metadata.get(key) != finalized_metadata.get(key):
            raise ValueError(f"event delivery cannot change intervention metadata {key}")


def _validate_event_observation_update(
    existing: Intervention,
    observed: Intervention,
) -> None:
    """Freeze the proposal while attaching later worker outcome evidence."""

    _validate_intervention_identity(observed, existing)
    immutable_fields = (
        "trigger",
        "evidence",
        "diagnosis",
        "proposed_action",
        "confidence",
        "risk",
        "reversible",
        "authority_required",
        "action_taken",
        "policy_verdict",
        "created_at",
    )
    for field in immutable_fields:
        if getattr(existing, field) != getattr(observed, field):
            raise ValueError(f"event observation cannot change intervention {field}")
    mutable_metadata = {
        "evidence_collection_succeeded",
        "goal_satisfied",
        "outcome_event_ids",
        "outcome_final",
        "verification",
    }
    existing_metadata = existing.metadata or {}
    observed_metadata = observed.metadata or {}
    for key in set(existing_metadata) | set(observed_metadata):
        if key in mutable_metadata:
            continue
        if existing_metadata.get(key) != observed_metadata.get(key):
            raise ValueError(f"event observation cannot change intervention metadata {key}")


def _merge_event_session_projection(
    processing: dict[str, Any],
    current: HarnessSession | None,
    planned: HarnessSession,
) -> HarnessSession:
    """Apply event-owned state without rolling back newer adapter/control state."""

    if planned.id != processing["session_id"]:
        raise ValueError("event session projection binding mismatch")
    if planned.harness_type.value != processing["harness_type"]:
        raise ValueError("event session projection harness mismatch")
    if current is None:
        return planned.model_copy(deep=True)
    if current.harness_type != planned.harness_type:
        raise ValueError("event session projection cannot change harness identity")
    if current.vendor_session_id != planned.vendor_session_id:
        raise ValueError("event session projection cannot change vendor identity")
    if (
        current.project_id
        and planned.project_id
        and not _same_project(current.project_id, planned.project_id)
    ):
        raise ValueError("event session projection cannot change project identity")

    accepted = processing.get("accepted_session")
    current_newer = bool(
        current.last_activity
        and (
            accepted is None
            or accepted.last_activity is None
            or _time_key(current.last_activity) > _time_key(accepted.last_activity)
        )
    )
    status_changed = bool(accepted is not None and current.status != accepted.status)
    adapter_changed = bool(
        accepted is not None
        and (
            current.capabilities != accepted.capabilities
            or current.local_window_id != accepted.local_window_id
            or current.external_url != accepted.external_url
        )
    )
    merged = (
        current.model_copy(deep=True)
        if current_newer or status_changed
        else planned.model_copy(deep=True)
    )
    # Event-owned routing/health keys may still advance when the current value
    # has not changed since acceptance.  This applies the event delta without
    # allowing a stale plan to erase newer adapter/control metadata.
    merged.metadata = dict(current.metadata)
    accepted_metadata = accepted.metadata if accepted is not None else {}
    for key, value in planned.metadata.items():
        if key not in _EVENT_SESSION_METADATA_KEYS:
            if key not in merged.metadata:
                merged.metadata[key] = value
            continue
        if current.metadata.get(key) == accepted_metadata.get(key):
            merged.metadata[key] = value
    if accepted is not None and current.status == accepted.status:
        merged.status = planned.status
    if current.last_activity and (
        merged.last_activity is None
        or _time_key(current.last_activity) > _time_key(merged.last_activity)
    ):
        merged.last_activity = current.last_activity
    if adapter_changed:
        merged.capabilities = dict(current.capabilities)
        merged.external_url = current.external_url
        merged.local_window_id = current.local_window_id
        source = current.metadata.get("capabilities_adapter")
        if source is not None:
            merged.metadata["capabilities_adapter"] = source
    if current.project_id and not merged.project_id:
        merged.project_id = current.project_id
    # The adapter owns the live working target. Even with unchanged activity
    # timestamps, an older semantic plan cannot restore its previous directory.
    merged.cwd = current.cwd
    if current.repo and not merged.repo:
        merged.repo = current.repo
    # These are always control-plane owned, regardless of activity timestamps.
    merged.goal_id = current.goal_id
    merged.supervision_paused = current.supervision_paused
    attention = current.metadata.get("human_decision_attention")
    if attention is not None:
        merged.metadata["human_decision_attention"] = attention
    return merged


def _validate_lifecycle_resource_transition(
    current: dict[str, Any],
    updated: dict[str, Any],
) -> None:
    immutable = {
        "id",
        "session_id",
        "goal_id",
        "project_id",
        "project_binding",
        "vendor_session_id",
        "harness_type",
        "path",
        "scope_root",
        "kind",
        "owner",
        "created_by",
        "registered_at",
        "entity_identity",
        "entity_fingerprint",
    }
    if any(current.get(key) != updated.get(key) for key in immutable):
        raise ValueError("lifecycle resource identity is immutable")
    before = str(current.get("state") or "")
    after = str(updated.get("state") or "")
    allowed = {
        "active": {"cleanup_ready"},
        "cleanup_ready": {"quarantining"},
        "quarantining": {"quarantined", "cleanup_ready", "conflict"},
        "quarantined": {"restoring"},
        "restoring": {"active", "quarantined", "conflict"},
    }
    if after not in allowed.get(before, set()):
        raise ValueError(f"invalid lifecycle resource transition: {before} -> {after}")


def _lifecycle_entity_identity(path: Path) -> tuple[dict[str, int], str]:
    value = os.lstat(path)
    attributes = int(getattr(value, "st_file_attributes", 0))
    reparse_flag = int(getattr(stat, "FILE_ATTRIBUTE_REPARSE_POINT", 0x400))
    if stat.S_ISLNK(value.st_mode) or attributes & reparse_flag:
        raise ValueError("lifecycle resource cannot traverse a symlink or reparse point")
    identity = {
        "device": int(value.st_dev),
        "inode": int(value.st_ino),
        "file_type": int(stat.S_IFMT(value.st_mode)),
        "file_attributes": attributes,
    }
    fingerprint = hashlib.sha256(_canonical_json(identity).encode("utf-8")).hexdigest()
    return identity, fingerprint


def _canonical_lifecycle_path(path: Path, *, must_exist: bool) -> Path:
    candidate = Path(os.path.abspath(os.fspath(path)))
    anchor = Path(candidate.anchor)
    current = anchor
    parts = candidate.parts[1:] if candidate.anchor else candidate.parts
    for part in parts:
        current /= part
        try:
            _lifecycle_entity_identity(current)
        except FileNotFoundError:
            if must_exist:
                raise
            break
    if must_exist:
        return candidate.resolve(strict=True)
    return candidate.resolve(strict=False)


def _lifecycle_observed_fingerprint(path: Path) -> str | None:
    try:
        canonical = _canonical_lifecycle_path(path, must_exist=True)
        _, fingerprint = _lifecycle_entity_identity(canonical)
        return fingerprint
    except FileNotFoundError:
        return None
    except (OSError, ValueError):
        return "mismatch"


def _lifecycle_readiness_fingerprint(record: dict[str, Any]) -> str:
    payload = {
        "resource_id": record.get("id"),
        "resource_version": record.get("version"),
        "entity_fingerprint": record.get("entity_fingerprint"),
        "cleanup_ready_at": record.get("cleanup_ready_at"),
        "cleanup_ready_evidence": record.get("cleanup_ready_evidence"),
    }
    return hashlib.sha256(_canonical_json(payload).encode("utf-8")).hexdigest()


def _merge_session_control_state(
    current: HarnessSession,
    requested: HarnessSession,
) -> HarnessSession:
    if current.id != requested.id or current.harness_type != requested.harness_type:
        raise ValueError("session control update has a different identity")
    if current.vendor_session_id != requested.vendor_session_id:
        raise ValueError("session control update has a different vendor identity")
    if (
        current.project_id
        and requested.project_id
        and not _same_project(current.project_id, requested.project_id)
    ):
        raise ValueError("session control update has a different project identity")
    merged = current.model_copy(deep=True)
    merged.status = requested.status
    if requested.last_activity is not None and (
        merged.last_activity is None
        or _time_key(requested.last_activity) > _time_key(merged.last_activity)
    ):
        merged.last_activity = requested.last_activity
    if requested.capabilities:
        merged.capabilities = dict(requested.capabilities)
    return merged


async def _merge_resolution_session_state(
    transaction: aiosqlite.Connection,
    current: HarnessSession,
    requested: HarnessSession,
    resolution: dict[str, Any],
    *,
    allow_containment_stop: bool = False,
) -> HarnessSession:
    """Project a terminal receipt without reviving stale control authority."""

    if current.id != requested.id:
        raise ValueError("resolution session identity changed")
    merged = current.model_copy(deep=True)
    if requested.last_activity is not None and (
        merged.last_activity is None
        or _time_key(requested.last_activity) > _time_key(merged.last_activity)
    ):
        merged.last_activity = requested.last_activity

    # STOP is an authority-reducing fact.  It may be projected after an exact
    # granted containment dispatch even while project authority is quarantined.
    if allow_containment_stop and requested.status == SessionStatus.STOPPED:
        merged.status = SessionStatus.STOPPED
        return merged

    # Never revive a newer stop, overwrite current capabilities, or clear a
    # pause while merely recording how an external delivery ended.
    if (
        current.status == SessionStatus.STOPPED
        or current.supervision_paused
        or resolution.get("session_binding") != _decision_session_binding(current)
    ):
        return merged
    project_id = _session_project(current)
    try:
        await _reject_quarantined_project_binding(transaction, project_id)
        current_project_binding = (
            await _project_binding_containment_snapshot(transaction, project_id)
            if resolution.get("authority_reducing")
            else await _project_binding_snapshot(transaction, project_id)
        )
    except ProjectIdentityBlockedError:
        return merged
    expected_project_binding = (
        resolution.get("dispatch_project_binding")
        if resolution.get("authority_reducing")
        else resolution.get("project_binding")
    )
    if expected_project_binding != current_project_binding:
        return merged

    try:
        goal, goal_binding = await _load_bound_goal(
            transaction,
            str(current.goal_id or ""),
            require_live=not bool(resolution.get("authority_reducing")),
        )
    except (LookupError, ProjectIdentityBlockedError, RuntimeError, ValueError):
        return merged
    if goal.paused:
        return merged
    try:
        superseded = await _has_authoritative_goal_successor(
            transaction,
            goal,
            goal_binding,
        )
    except (RuntimeError, ValueError):
        return merged
    if superseded:
        return merged
    merged.status = requested.status
    return merged


def _session_project(session: HarnessSession) -> str:
    project_id = session.project_id or session.cwd
    if not project_id or len(project_id) > MAX_PROJECT_ID_LENGTH:
        raise ValueError("session has no project binding")
    return project_id


def _session_discovery_generation(session: HarnessSession) -> str | None:
    generation = session.metadata.get("discovery_generation")
    if generation is None:
        return None
    if not isinstance(generation, str) or not generation.strip() or len(generation) > 512:
        raise ValueError("session discovery generation is invalid")
    return generation


def _session_control_receipt(
    row: aiosqlite.Row,
    *,
    session: HarnessSession | None = None,
) -> dict[str, Any]:
    canonical = session or HarnessSession.model_validate_json(row["json"])
    return {
        "session": canonical,
        "revision": int(row["revision"]),
        "control_revision": int(row["control_revision"]),
        "project_binding": row["project_binding"],
        "discovery_generation": row["discovery_generation"],
    }


def _event_session_authority(row: aiosqlite.Row) -> str:
    """Freeze dispatch authority independently of mutable presentation snapshots."""

    session = HarnessSession.model_validate_json(row["json"])
    return _canonical_json(
        {
            "schema": "pex.event-session-authority.v1",
            "binding": _overlay_session_binding(session),
            "control_revision": row["control_revision"],
            "project_binding": row["project_binding"],
            # discovery_generation is a UI refresh token, not a transport epoch.
            # Connection/subscription continuity must be checked by the adapter.
        }
    )


async def _revoke_session_credentials(
    transaction: aiosqlite.Connection,
    *,
    table: str,
    session_id: str,
    revoked_at: datetime,
) -> int:
    if table not in {"mcp_principals", "hook_credentials"}:
        raise ValueError("session credential table is invalid")
    revoked_iso = _utc_iso(revoked_at)
    cursor = await transaction.execute(
        f"SELECT id, json FROM {table} WHERE session_id = ? AND revoked_at IS NULL",
        (session_id,),
    )
    rows = await cursor.fetchall()
    for row in rows:
        record = _strict_json_loads(str(row["json"]))
        if not isinstance(record, dict):
            raise RuntimeError("stored session credential is invalid")
        issued_at = datetime.fromisoformat(str(record["issued_at"]))
        if _time_key(revoked_at) < _time_key(issued_at):
            raise ValueError("session credential revocation predates issuance")
        record["revoked_at"] = revoked_iso
        await transaction.execute(
            f"UPDATE {table} SET revoked_at = ?, json = ? WHERE id = ?",
            (revoked_iso, _canonical_json(record), str(row["id"])),
        )
    return len(rows)


def _validate_principal_scope_values(scopes: list[str]) -> list[str]:
    if not isinstance(scopes, list) or not 1 <= len(scopes) <= MAX_MCP_SCOPES:
        raise ValueError(f"principal scopes must contain between 1 and {MAX_MCP_SCOPES} items")
    if any(
        not isinstance(scope, str)
        or (scope != "mcp:read" and _MCP_SCOPE_PATTERN.fullmatch(scope) is None)
        for scope in scopes
    ):
        raise ValueError("principal scope is invalid")
    normalized = sorted(set(scopes))
    if len(normalized) != len(scopes):
        raise ValueError("principal scopes must be unique")
    return normalized


def _validate_principal_record_binding(
    record: dict[str, Any],
    session: HarnessSession,
    goal: Goal,
    *,
    validate_project: bool = True,
) -> None:
    if session.status == SessionStatus.DETACHED:
        raise PermissionError("MCP principal session is detached")
    if session.id != record.get("session_id"):
        raise PermissionError("MCP principal session binding changed")
    if session.goal_id != record.get("goal_id") or goal.id != record.get("goal_id"):
        raise PermissionError("MCP principal goal binding changed")
    if validate_project and not _same_project(
        _session_project(session),
        str(record.get("project_id") or ""),
    ):
        raise PermissionError("MCP principal project binding changed")
    if validate_project and not _same_project(
        goal.project_id,
        str(record.get("project_id") or ""),
    ):
        raise PermissionError("MCP principal goal project binding changed")
    if session.vendor_session_id != record.get("vendor_session_id"):
        raise PermissionError("MCP principal vendor session binding changed")
    if session.harness_type.value != record.get("harness_type"):
        raise PermissionError("MCP principal harness binding changed")


def _validate_hook_route_values(
    harness_type: HarnessType,
    routes: list[str],
) -> list[str]:
    if not isinstance(routes, list) or not 1 <= len(routes) <= MAX_MCP_SCOPES:
        raise ValueError("hook credential routes are invalid")
    normalized = sorted(set(routes))
    if len(normalized) != len(routes):
        raise ValueError("hook credential routes must be unique")
    if not set(normalized).issubset(allowed_hook_routes(harness_type)):
        raise ValueError("hook credential routes exceed harness authority")
    return normalized


def _validate_hook_credential_binding(
    record: dict[str, Any],
    session: HarnessSession,
    *,
    validate_project: bool = True,
) -> None:
    if session.status == SessionStatus.DETACHED:
        raise PermissionError("hook credential session is detached")
    if session.id != record.get("session_id"):
        raise PermissionError("hook credential session binding changed")
    if session.vendor_session_id != record.get("vendor_session_id"):
        raise PermissionError("hook credential vendor session binding changed")
    if session.harness_type.value != record.get("harness_type"):
        raise PermissionError("hook credential harness binding changed")
    if validate_project and not _same_project(
        _session_project(session),
        str(record.get("project_id") or ""),
    ):
        raise PermissionError("hook credential project binding changed")
    try:
        harness_type = HarnessType(str(record.get("harness_type") or ""))
    except ValueError as exc:
        raise PermissionError("hook credential harness binding is invalid") from exc
    routes = record.get("allowed_routes")
    if not isinstance(routes, list):
        raise PermissionError("hook credential routes are invalid")
    try:
        _validate_hook_route_values(harness_type, routes)
    except ValueError as exc:
        raise PermissionError(str(exc)) from exc


def _principal_is_active(record: dict[str, Any], now: datetime) -> bool:
    if record.get("revoked_at") is not None:
        return False
    try:
        issued_at = datetime.fromisoformat(str(record["issued_at"]))
        expires_at = datetime.fromisoformat(str(record["expires_at"]))
    except (KeyError, TypeError, ValueError):
        return False
    moment = _time_key(now)
    return _time_key(issued_at) <= moment < _time_key(expires_at)


async def _reject_quarantined_project_binding(
    transaction: aiosqlite.Connection,
    project_id: str,
) -> None:
    cursor = await transaction.execute(
        "SELECT status FROM legacy_project_bindings WHERE legacy_project_id = ?",
        (project_id,),
    )
    row = await cursor.fetchone()
    if row is not None:
        if row["status"] == "quarantined":
            raise ProjectIdentityBlockedError(
                "project identity is quarantined",
                code="project_identity_quarantined",
            )
        return

    # Once any lexical lookalike has a typed binding, an unregistered alias
    # cannot safely inherit its authority. It may be a valid alias, or it may be
    # one of the false merges that v2 exists to prevent. Explicit registration
    # is the only operation allowed to decide which.
    aliases_cursor = await transaction.execute(
        "SELECT legacy_project_id FROM legacy_project_bindings "
        "ORDER BY legacy_project_id LIMIT 10001"
    )
    aliases = [str(item["legacy_project_id"]) for item in await aliases_cursor.fetchall()]
    if len(aliases) > 10_000:
        raise RuntimeError("project identity alias scan is bounded")
    if any(
        candidate != project_id and _same_project(candidate, project_id) for candidate in aliases
    ):
        raise ProjectIdentityBlockedError(
            "project identity alias requires explicit registration",
            code="project_identity_unresolved",
        )


async def _same_live_project_binding(
    transaction: aiosqlite.Connection,
    left: str,
    right: str,
) -> bool:
    """Compare project keys without letting partial v2 adoption create aliases.

    Exact legacy keys remain valid. Two explicitly registered keys match only
    when both active bindings select the same stable identity. The old lexical
    compatibility rule is retained solely while neither key has a v2 binding.
    """

    if left == right:
        await _reject_quarantined_project_binding(transaction, left)
        return True
    cursor = await transaction.execute(
        "SELECT legacy_project_id, project_identity_id, status "
        "FROM legacy_project_bindings WHERE legacy_project_id IN (?, ?)",
        (left, right),
    )
    rows = {str(row["legacy_project_id"]): row for row in await cursor.fetchall()}
    for value in (left, right):
        row = rows.get(value)
        if row is not None and row["status"] == "quarantined":
            raise ProjectIdentityBlockedError(
                "project identity is quarantined",
                code="project_identity_quarantined",
            )
    left_row = rows.get(left)
    right_row = rows.get(right)
    if left_row is not None or right_row is not None:
        return bool(
            left_row is not None
            and right_row is not None
            and left_row["status"] == "active"
            and right_row["status"] == "active"
            and left_row["project_identity_id"] is not None
            and left_row["project_identity_id"] == right_row["project_identity_id"]
        )
    return _same_project(left, right)


async def _validate_overlay_control_binding(
    transaction: aiosqlite.Connection,
    session: HarnessSession,
) -> None:
    """Revalidate the live session/goal/project boundary for direct overlay control."""

    if session.status == SessionStatus.DETACHED or bool(
        session.metadata.get("not_live_control") or session.metadata.get("observe_only")
    ):
        raise PermissionError("overlay session is not a live control surface")
    if session.project_id:
        await _reject_quarantined_project_binding(transaction, session.project_id)
    if not session.goal_id:
        return
    try:
        goal, goal_binding = await _load_bound_goal(transaction, session.goal_id)
    except LookupError as exc:
        raise PermissionError("overlay goal is missing") from exc
    except (ProjectIdentityBlockedError, RuntimeError, ValueError) as exc:
        raise PermissionError("overlay goal authority is unavailable") from exc
    if goal.paused:
        raise PermissionError("overlay goal is paused")
    if session.project_id and not await _same_live_project_binding(
        transaction,
        session.project_id,
        goal.project_id,
    ):
        raise PermissionError("overlay goal project binding changed")
    if await _has_authoritative_goal_successor(transaction, goal, goal_binding):
        raise PermissionError("overlay goal was superseded")


def _overlay_proposal_core(overlay: Overlay) -> dict[str, Any]:
    """Return the immutable operator/supervisor intent, excluding Store-owned rollback."""

    return {
        "id": overlay.id,
        "session_id": overlay.session_id,
        "reason": overlay.reason,
        "diff": overlay.diff.model_dump(mode="json"),
        "ttl_seconds": overlay.ttl_seconds,
        "scope": overlay.scope,
        "applied_at": overlay.applied_at,
        "expires_at": overlay.expires_at,
        "reverted_at": overlay.reverted_at,
        "revert_reason": overlay.revert_reason,
        "promoted": overlay.promoted,
    }


async def _validate_overlay_apply_owner(
    transaction: aiosqlite.Connection,
    *,
    owner_intervention_id: str,
    overlay: Overlay,
    session: HarnessSession,
    project_binding: str,
) -> None:
    """Require one genuine bound APPLY_OVERLAY intervention for every new apply."""

    try:
        intervention, binding, owner_session, _, _ = await _load_bound_intervention(
            transaction,
            owner_intervention_id,
            require_live=True,
        )
    except LookupError as exc:
        raise PermissionError("overlay apply owner intervention is missing") from exc
    raw_overlay = intervention.proposed_action.payload.get("overlay")
    try:
        proposed_overlay = Overlay.model_validate(raw_overlay)
    except ValueError as exc:
        raise PermissionError("overlay owner proposal is invalid") from exc
    if (
        intervention.proposed_action.type != InterventionType.APPLY_OVERLAY
        or intervention.action_taken != InterventionType.APPLY_OVERLAY.value
        or intervention.policy_verdict != PolicyVerdict.ALLOW
        or not intervention.reversible
        or intervention.session_id != session.id
        or intervention.goal_id != session.goal_id
        or owner_session.id != session.id
        or binding.project_binding != project_binding
        or _overlay_proposal_core(proposed_overlay) != _overlay_proposal_core(overlay)
    ):
        raise PermissionError("overlay apply differs from its owner intervention")


async def _bind_overlay_parent_effect(
    transaction: aiosqlite.Connection,
    *,
    parent_effect_id: str | None,
    operation_id: str,
    operation_kind: str,
    overlay_id: str,
    session_id: str,
    owner_intervention_id: str | None,
) -> None:
    if parent_effect_id is None:
        return
    cursor = await transaction.execute(
        "SELECT * FROM event_effects WHERE effect_id = ?",
        (parent_effect_id,),
    )
    row = await cursor.fetchone()
    if row is None:
        raise PermissionError("overlay parent effect is missing")
    effect = _event_effect_record(row)
    action = effect["payload"].get("action")
    action_payload = action.get("payload") if isinstance(action, dict) else None
    expected_type = {
        "apply": InterventionType.APPLY_OVERLAY.value,
        "revert": InterventionType.REVERT_OVERLAY.value,
    }.get(operation_kind)
    expected_overlay_id = None
    if isinstance(action_payload, dict):
        if operation_kind == "apply":
            action_overlay = action_payload.get("overlay")
            if isinstance(action_overlay, dict):
                expected_overlay_id = action_overlay.get("id")
        elif operation_kind == "revert":
            expected_overlay_id = action_payload.get("overlay_id")
    if (
        expected_type is None
        or not isinstance(action, dict)
        or action.get("type") != expected_type
        or expected_overlay_id != overlay_id
        or effect["kind"] != "worker_action"
        or effect["state"] != "dispatching"
        or effect["target_session_id"] != session_id
        or effect["payload"].get("intervention_id") != owner_intervention_id
        or effect.get("downstream_operation_id") not in {None, operation_id}
    ):
        raise PermissionError("overlay parent effect binding is invalid")
    updated = await transaction.execute(
        "UPDATE event_effects SET downstream_operation_id = ?, "
        "updated_at = ?, version = version + 1 WHERE effect_id = ? "
        "AND state = 'dispatching' AND version = ? "
        "AND downstream_operation_id IS NULL",
        (operation_id, utcnow().isoformat(), parent_effect_id, effect["version"]),
    )
    if effect.get("downstream_operation_id") is None and updated.rowcount != 1:
        raise RuntimeError("overlay parent effect link CAS was lost")


async def _project_binding_snapshot(
    transaction: aiosqlite.Connection,
    project_id: str,
) -> str:
    """Return a stable physical-identity snapshot for a legacy project key.

    An untyped key is deliberately distinct from the same key after it becomes
    typed. A reservation therefore cannot silently cross an identity
    registration or conflict resolution that happened before adapter I/O.
    """

    await _reject_quarantined_project_binding(transaction, project_id)
    cursor = await transaction.execute(
        "SELECT project_identity_id, status FROM legacy_project_bindings "
        "WHERE legacy_project_id = ?",
        (project_id,),
    )
    row = await cursor.fetchone()
    if row is None:
        digest = hashlib.sha256(project_id.encode("utf-8")).hexdigest()
        return f"legacy:{digest}"
    if row["status"] != "active" or row["project_identity_id"] is None:
        raise ProjectIdentityBlockedError(
            "project identity is quarantined",
            code="project_identity_quarantined",
        )
    return f"identity:{row['project_identity_id']}"


async def _project_binding_containment_snapshot(
    transaction: aiosqlite.Connection,
    project_id: str,
) -> str:
    """Freeze the raw project key for a strictly authority-reducing dispatch.

    Permission denial and STOP_AGENT target an already-bound vendor request or
    session.  They remain available through identity quarantine/rebinding, but
    only while the exact raw key plus the separately frozen vendor, harness,
    goal, request, and action bindings remain unchanged.
    """

    del transaction
    digest = hashlib.sha256(project_id.encode("utf-8")).hexdigest()
    return f"containment:{digest}"


def _stored_artifact_binding(
    row: aiosqlite.Row,
    *,
    label: str,
) -> ArtifactBinding:
    project_id = row["project_id"]
    project_binding = row["project_binding"]
    if not isinstance(project_id, str) or not isinstance(project_binding, str):
        raise ProjectIdentityBlockedError(
            f"{label} has no immutable project identity",
            code="artifact_project_identity_unbound",
        )
    return ArtifactBinding(project_id=project_id, project_binding=project_binding)


async def _require_live_artifact_binding(
    transaction: aiosqlite.Connection,
    binding: ArtifactBinding,
    *,
    label: str,
) -> None:
    current = await _project_binding_snapshot(transaction, binding.project_id)
    if current != binding.project_binding:
        raise ProjectIdentityBlockedError(
            f"{label} project identity changed after creation",
            code="artifact_project_identity_changed",
        )


async def _load_bound_goal(
    transaction: aiosqlite.Connection,
    goal_id: str,
    *,
    require_live: bool = True,
) -> tuple[Goal, ArtifactBinding]:
    cursor = await transaction.execute(
        "SELECT id, project_id, project_binding, intent_revision, intent_hash, json "
        "FROM goals WHERE id = ?",
        (goal_id,),
    )
    row = await cursor.fetchone()
    if row is None:
        raise LookupError("goal not found")
    goal = Goal.model_validate_json(row["json"])
    binding = _stored_artifact_binding(row, label="goal")
    if goal.id != row["id"] or goal.project_id != binding.project_id:
        raise RuntimeError("stored goal project binding is corrupt")
    _, stored_hash = _validate_goal_intent_scalar_pair(
        row["intent_revision"],
        row["intent_hash"],
    )
    calculated_hash = await _goal_intent_hash_in_transaction(
        transaction,
        goal,
        binding,
    )
    if calculated_hash != stored_hash:
        raise RuntimeError("stored goal intent hash is corrupt")
    if require_live:
        await _require_live_artifact_binding(transaction, binding, label="goal")
    return goal, binding


async def _load_bound_session(
    transaction: aiosqlite.Connection,
    session_id: str,
    *,
    require_goal_binding: bool = False,
    require_live: bool = True,
) -> tuple[HarnessSession, str | None]:
    cursor = await transaction.execute(
        "SELECT * FROM sessions WHERE id = ?",
        (session_id,),
    )
    row = await cursor.fetchone()
    if row is None:
        raise LookupError("session not found")
    session = HarnessSession.model_validate_json(row["json"])
    if (
        session.id != row["id"]
        or session.vendor_session_id != row["vendor_session_id"]
        or session.harness_type.value != row["harness_type"]
    ):
        raise RuntimeError("stored session authority binding is corrupt")
    project_id = session.project_id or session.cwd
    stored_binding = row["project_binding"]
    if project_id:
        if not isinstance(stored_binding, str):
            raise ProjectIdentityBlockedError(
                "session has no immutable project identity",
                code="artifact_project_identity_unbound",
            )
        if require_live:
            current_binding = await _project_binding_snapshot(transaction, project_id)
            if current_binding != stored_binding:
                raise ProjectIdentityBlockedError(
                    "session project identity changed after creation",
                    code="artifact_project_identity_changed",
                )
    elif stored_binding is not None:
        raise RuntimeError("project-less session has a corrupt project binding")
    if session.goal_id is not None:
        goal, goal_binding = await _load_bound_goal(
            transaction,
            session.goal_id,
            require_live=require_live,
        )
        if (
            project_id is None
            or stored_binding != goal_binding.project_binding
            or (
                require_live
                and not await _same_live_project_binding(
                    transaction,
                    project_id,
                    goal.project_id,
                )
            )
        ):
            raise ProjectIdentityBlockedError(
                "session and goal immutable project identities differ",
                code="artifact_project_identity_changed",
            )
    elif require_goal_binding:
        raise PermissionError("session has no attached persistent goal")
    return session, stored_binding


async def _load_bound_overlay(
    transaction: aiosqlite.Connection,
    overlay_id: str,
    *,
    require_live: bool,
) -> tuple[Overlay, dict[str, Any], HarnessSession]:
    """Load one scalar/JSON-bound overlay and its exact frozen session target."""

    cursor = await transaction.execute("SELECT * FROM overlays WHERE id = ?", (overlay_id,))
    row = await cursor.fetchone()
    if row is None:
        raise LookupError("overlay not found")
    if not isinstance(row["project_binding"], str):
        raise ProjectIdentityBlockedError(
            "overlay has no immutable project identity",
            code="overlay_project_identity_unbound",
        )
    validate_project_binding(row["project_binding"])
    envelope = _strict_json_loads(str(row["json"]))
    if not isinstance(envelope, dict) or envelope.get("schema") != "pex.overlay-bound.v1":
        raise RuntimeError("stored overlay binding envelope is corrupt")
    overlay = _stored_overlay(envelope)
    expected = {
        "id": row["id"],
        "session_id": row["session_id"],
        "goal_id": row["goal_id"],
        "project_id": row["project_id"],
        "project_binding": row["project_binding"],
        "vendor_session_id": row["vendor_session_id"],
        "harness_type": row["harness_type"],
        "overlay_hash": row["overlay_hash"],
        "version": row["version"],
    }
    if any(envelope.get(key) != value for key, value in expected.items()):
        raise RuntimeError("stored overlay scalar/JSON binding is corrupt")
    if (
        overlay.id != row["id"]
        or overlay.session_id != row["session_id"]
        or _overlay_hash(overlay) != row["overlay_hash"]
        or _overlay_time_value(overlay, "applied_at") != row["applied_at"]
        or _overlay_time_value(overlay, "expires_at") != row["expires_at"]
        or _overlay_time_value(overlay, "reverted_at") != row["reverted_at"]
    ):
        raise RuntimeError("stored overlay projection is corrupt")
    session, session_binding = await _load_bound_session(
        transaction,
        str(row["session_id"]),
        require_live=require_live,
    )
    if (
        session_binding != row["project_binding"]
        or _session_project(session) != row["project_id"]
        or session.goal_id != row["goal_id"]
        or session.vendor_session_id != row["vendor_session_id"]
        or session.harness_type.value != row["harness_type"]
    ):
        raise ProjectIdentityBlockedError(
            "overlay frozen session target changed",
            code="overlay_session_target_changed",
        )
    return overlay, dict(row), session


async def _load_bound_overlay_operation(
    transaction: aiosqlite.Connection,
    operation_id: str,
    *,
    require_live: bool,
) -> tuple[dict[str, Any], Overlay, HarnessSession]:
    cursor = await transaction.execute(
        "SELECT * FROM overlay_operations WHERE operation_id = ?", (operation_id,)
    )
    row = await cursor.fetchone()
    if row is None:
        raise LookupError("overlay operation is missing")
    if not isinstance(row["project_binding"], str):
        raise ProjectIdentityBlockedError(
            "overlay operation has no immutable project identity",
            code="overlay_project_identity_unbound",
        )
    operation = _overlay_operation_record(row)
    payload = operation["payload"]
    if not isinstance(payload, dict):
        raise RuntimeError("overlay operation payload is corrupt")
    overlay, overlay_row, session = await _load_bound_overlay(
        transaction, str(row["overlay_id"]), require_live=require_live
    )
    scalar_fields = (
        "operation_id",
        "overlay_id",
        "kind",
        "session_id",
        "goal_id",
        "project_id",
        "project_binding",
        "vendor_session_id",
        "harness_type",
        "overlay_hash",
        "action_hash",
        "apply_operation_id",
        "attempt_count",
        "owner_intervention_id",
        "parent_effect_id",
        "state",
        "version",
        "authorized_by",
        "idempotency_key",
    )
    if any(payload.get(key) != row[key] for key in scalar_fields):
        raise RuntimeError("overlay operation scalar/JSON binding is corrupt")
    if any(
        row[key] != overlay_row[key]
        for key in (
            "session_id",
            "goal_id",
            "project_id",
            "project_binding",
            "vendor_session_id",
            "harness_type",
            "overlay_hash",
        )
    ):
        raise RuntimeError("overlay operation target differs from overlay binding")
    expected_action_hash = _overlay_action_hash(
        kind=str(row["kind"]),
        overlay_hash=str(row["overlay_hash"]),
        session_id=str(row["session_id"]),
        vendor_session_id=str(row["vendor_session_id"]),
        harness_type=str(row["harness_type"]),
        goal_id=row["goal_id"],
        project_binding=str(row["project_binding"]),
        adapter=str(payload.get("adapter") or ""),
        apply_operation_id=row["apply_operation_id"],
    )
    if expected_action_hash != row["action_hash"]:
        raise RuntimeError("overlay operation action hash is corrupt")
    expected_operation_id = stable_overlay_operation_id(
        str(row["overlay_id"]),
        str(row["kind"]),
        attempt=int(row["attempt_count"]),
    )
    if expected_operation_id != row["operation_id"]:
        raise RuntimeError("overlay operation deterministic identity is corrupt")
    if _overlay_request_hash(payload) != row["request_hash"]:
        raise RuntimeError("overlay operation request hash is corrupt")
    return operation, overlay, session


def _intervention_action_hash(intervention: Intervention) -> str:
    payload = intervention.proposed_action.model_dump(mode="json")
    return hashlib.sha256(_canonical_json(payload).encode("utf-8")).hexdigest()


def _stored_intervention(raw: str | dict[str, Any]) -> Intervention:
    value = _strict_json_loads(raw) if isinstance(raw, str) else raw
    if not isinstance(value, dict):
        raise RuntimeError("stored intervention is not an object")
    payload = value.get("payload") if value.get("schema") == "pex.intervention-bound.v1" else value
    if not isinstance(payload, dict):
        raise RuntimeError("stored intervention payload is not an object")
    return Intervention.model_validate(payload)


def _bound_intervention_json(
    intervention: Intervention,
    *,
    project_id: str,
    project_binding: str,
    vendor_session_id: str,
    harness_type: str,
    action_hash: str,
    version: int,
) -> str:
    envelope = {
        "schema": "pex.intervention-bound.v1",
        "payload": intervention.model_dump(mode="json"),
        "project_id": project_id,
        "project_binding": project_binding,
        "vendor_session_id": vendor_session_id,
        "harness_type": harness_type,
        "action_hash": action_hash,
        "version": version,
    }
    return _canonical_json(envelope)


async def _load_bound_intervention(
    transaction: aiosqlite.Connection,
    intervention_id: str,
    *,
    require_live: bool = True,
) -> tuple[Intervention, ArtifactBinding, HarnessSession, Goal, int]:
    cursor = await transaction.execute(
        "SELECT * FROM interventions WHERE id = ?",
        (intervention_id,),
    )
    row = await cursor.fetchone()
    if row is None:
        raise LookupError("intervention not found")
    envelope = _strict_json_loads(str(row["json"]))
    if not isinstance(envelope, dict):
        raise RuntimeError("stored intervention is not an object")
    intervention = _stored_intervention(envelope)
    binding = _stored_artifact_binding(row, label="intervention")
    action_hash = _intervention_action_hash(intervention)
    version = row["version"]
    if (
        not isinstance(version, int)
        or isinstance(version, bool)
        or version < 0
        or intervention.id != row["id"]
        or intervention.session_id != row["session_id"]
        or intervention.goal_id != row["goal_id"]
        or envelope.get("project_id") != binding.project_id
        or envelope.get("project_binding") != binding.project_binding
        or envelope.get("vendor_session_id") != row["vendor_session_id"]
        or envelope.get("harness_type") != row["harness_type"]
        or envelope.get("action_hash") != row["action_hash"]
        or envelope.get("version") != version
        or action_hash != row["action_hash"]
        or _time_key(intervention.created_at) != _time_key(datetime.fromisoformat(row["ts"]))
    ):
        raise RuntimeError("stored intervention authority binding is corrupt")
    session, session_binding = await _load_bound_session(
        transaction,
        intervention.session_id,
        require_goal_binding=True,
        require_live=require_live,
    )
    if intervention.goal_id is None:
        raise ProjectIdentityBlockedError(
            "intervention has no immutable goal identity",
            code="artifact_project_identity_unbound",
        )
    goal, goal_binding = await _load_bound_goal(
        transaction,
        intervention.goal_id,
        require_live=require_live,
    )
    if (
        session.goal_id != goal.id
        or session_binding != binding.project_binding
        or goal_binding.project_binding != binding.project_binding
        or row["vendor_session_id"] != session.vendor_session_id
        or row["harness_type"] != session.harness_type.value
    ):
        raise ProjectIdentityBlockedError(
            "intervention immutable target binding changed",
            code="artifact_project_identity_changed",
        )
    if require_live:
        await _require_live_artifact_binding(transaction, binding, label="intervention")
    return intervention, binding, session, goal, version


async def _insert_bound_intervention(
    transaction: aiosqlite.Connection,
    intervention: Intervention,
) -> int:
    _validate_intervention_identity(intervention)
    if intervention.goal_id is None:
        raise ValueError("intervention requires a persistent goal binding")
    session, session_binding = await _load_bound_session(
        transaction,
        intervention.session_id,
        require_goal_binding=True,
    )
    goal, goal_binding = await _load_bound_goal(transaction, intervention.goal_id)
    if (
        session.goal_id != goal.id
        or session_binding is None
        or session_binding != goal_binding.project_binding
    ):
        raise ProjectIdentityBlockedError(
            "intervention session and goal identities differ",
            code="artifact_project_identity_changed",
        )
    project_id = _session_project(session)
    action_hash = _intervention_action_hash(intervention)
    version = 0
    cursor = await transaction.execute(
        "INSERT INTO interventions("
        "id, session_id, goal_id, project_id, project_binding, vendor_session_id, "
        "harness_type, action_hash, version, ts, json) "
        "VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)",
        (
            intervention.id,
            intervention.session_id,
            intervention.goal_id,
            project_id,
            goal_binding.project_binding,
            session.vendor_session_id,
            session.harness_type.value,
            action_hash,
            version,
            intervention.created_at.isoformat(),
            _bound_intervention_json(
                intervention,
                project_id=project_id,
                project_binding=goal_binding.project_binding,
                vendor_session_id=session.vendor_session_id,
                harness_type=session.harness_type.value,
                action_hash=action_hash,
                version=version,
            ),
        ),
    )
    if cursor.rowcount != 1:
        raise RuntimeError("intervention insert was lost")
    return version


async def _update_bound_intervention(
    transaction: aiosqlite.Connection,
    intervention: Intervention,
    *,
    require_live: bool = False,
) -> int:
    existing, binding, session, _, version = await _load_bound_intervention(
        transaction,
        intervention.id,
        require_live=require_live,
    )
    _validate_intervention_identity(intervention, existing)
    action_hash = _intervention_action_hash(existing)
    next_version = version + 1
    cursor = await transaction.execute(
        "UPDATE interventions SET version = ?, json = ? WHERE id = ? AND version = ?",
        (
            next_version,
            _bound_intervention_json(
                intervention,
                project_id=binding.project_id,
                project_binding=binding.project_binding,
                vendor_session_id=session.vendor_session_id,
                harness_type=session.harness_type.value,
                action_hash=action_hash,
                version=next_version,
            ),
            intervention.id,
            version,
        ),
    )
    if cursor.rowcount != 1:
        raise RuntimeError("intervention update CAS was lost")
    return next_version


async def _update_frozen_bound_intervention(
    transaction: aiosqlite.Connection,
    intervention: Intervention,
) -> int:
    """Update terminal projection without rebinding it to mutable session discovery."""

    cursor = await transaction.execute(
        "SELECT * FROM interventions WHERE id = ?",
        (intervention.id,),
    )
    row = await cursor.fetchone()
    if row is None:
        raise LookupError("intervention not found")
    envelope = _strict_json_loads(str(row["json"]))
    expected_keys = {
        "schema",
        "payload",
        "project_id",
        "project_binding",
        "vendor_session_id",
        "harness_type",
        "action_hash",
        "version",
    }
    if (
        not isinstance(envelope, dict)
        or set(envelope) != expected_keys
        or envelope.get("schema") != "pex.intervention-bound.v1"
    ):
        raise RuntimeError("stored intervention authority envelope is corrupt")
    existing = Intervention.model_validate(envelope.get("payload"))
    _validate_intervention_identity(intervention, existing)
    binding = _stored_artifact_binding(row, label="intervention")
    action_hash = _intervention_action_hash(existing)
    version = row["version"]
    if (
        not isinstance(version, int)
        or isinstance(version, bool)
        or version < 0
        or envelope.get("project_id") != binding.project_id
        or envelope.get("project_binding") != binding.project_binding
        or envelope.get("vendor_session_id") != row["vendor_session_id"]
        or envelope.get("harness_type") != row["harness_type"]
        or envelope.get("action_hash") != row["action_hash"]
        or envelope.get("version") != version
        or action_hash != row["action_hash"]
        or _time_key(existing.created_at) != _time_key(datetime.fromisoformat(row["ts"]))
    ):
        raise RuntimeError("stored intervention authority binding is corrupt")
    next_version = version + 1
    updated = await transaction.execute(
        "UPDATE interventions SET version = ?, json = ? WHERE id = ? AND version = ?",
        (
            next_version,
            _bound_intervention_json(
                intervention,
                project_id=binding.project_id,
                project_binding=binding.project_binding,
                vendor_session_id=str(row["vendor_session_id"]),
                harness_type=str(row["harness_type"]),
                action_hash=action_hash,
                version=next_version,
            ),
            intervention.id,
            version,
        ),
    )
    if updated.rowcount != 1:
        raise RuntimeError("intervention frozen update CAS was lost")
    return next_version


async def _load_bound_resolution(
    transaction: aiosqlite.Connection,
    table: str,
    intervention_id: str,
    *,
    require_live: bool,
    require_dispatch_snapshot: bool = True,
) -> tuple[
    dict[str, Any],
    aiosqlite.Row,
    Intervention,
    ArtifactBinding,
    HarnessSession,
    Goal,
    int,
]:
    if table not in {"permission_resolutions", "lifecycle_resolutions"}:
        raise ValueError("resolution table is invalid")
    cursor = await transaction.execute(
        f"SELECT * FROM {table} WHERE intervention_id = ?",
        (intervention_id,),
    )
    row = await cursor.fetchone()
    if row is None:
        raise LookupError("resolution was not reserved")
    record = _strict_json_loads(str(row["json"]))
    if not isinstance(record, dict):
        raise RuntimeError("stored resolution is not an object")
    binding = _stored_artifact_binding(row, label="resolution")
    version = row["version"]
    if (
        not isinstance(version, int)
        or isinstance(version, bool)
        or version < 0
        or record.get("intervention_id") != row["intervention_id"]
        or record.get("session_id") != row["session_id"]
        or record.get("goal_id") != row["goal_id"]
        or record.get("project_id") != binding.project_id
        or record.get("project_binding") != binding.project_binding
        or record.get("vendor_session_id") != row["vendor_session_id"]
        or record.get("harness_type") != row["harness_type"]
        or record.get("action_hash") != row["action_hash"]
        or record.get("version") != version
        or record.get("decision") != row["decision"]
        or record.get("status") != row["status"]
        or (table == "permission_resolutions" and record.get("request_id") != row["request_id"])
    ):
        raise RuntimeError("stored resolution authority binding is corrupt")
    intervention, intervention_binding, session, goal, _ = await _load_bound_intervention(
        transaction,
        intervention_id,
        require_live=require_live,
    )
    if (
        binding != intervention_binding
        or row["session_id"] != intervention.session_id
        or row["goal_id"] != intervention.goal_id
        or row["vendor_session_id"] != session.vendor_session_id
        or row["harness_type"] != session.harness_type.value
        or row["action_hash"] != _intervention_action_hash(intervention)
        or record.get("intervention_binding") != _decision_intervention_binding(intervention)
        or record.get("goal_binding") != {"goal_id": goal.id, "project_id": goal.project_id}
    ):
        raise ProjectIdentityBlockedError(
            "resolution immutable target identity changed",
            code="artifact_project_identity_changed",
        )
    if require_dispatch_snapshot and record.get("session_binding") != _decision_session_binding(
        session
    ):
        raise PermissionError("resolution vendor session binding changed")
    if table == "permission_resolutions":
        if (
            intervention.proposed_action.type != InterventionType.RESPOND_PERMISSION
            or record.get("request_id") != intervention.proposed_action.payload.get("request_id")
            or bool(record.get("authority_reducing")) != (record.get("decision") == "deny")
        ):
            raise PermissionError("permission resolution action binding changed")
    else:
        if record.get("action_type") != intervention.proposed_action.type.value or bool(
            record.get("authority_reducing")
        ) != (
            record.get("decision") == "deny"
            or intervention.proposed_action.type == InterventionType.STOP_AGENT
        ):
            raise PermissionError("lifecycle resolution action binding changed")
    return record, row, intervention, binding, session, goal, version


async def _load_bound_lifecycle_resource(
    transaction: aiosqlite.Connection,
    resource_id: str,
    *,
    require_live: bool = True,
    require_entity: bool = False,
) -> tuple[dict[str, Any], aiosqlite.Row, HarnessSession, Goal, ArtifactBinding]:
    cursor = await transaction.execute(
        "SELECT * FROM lifecycle_resources WHERE id = ?",
        (resource_id,),
    )
    row = await cursor.fetchone()
    if row is None:
        raise LookupError("lifecycle resource not found")
    record = _strict_json_loads(str(row["json"]))
    if not isinstance(record, dict):
        raise RuntimeError("stored lifecycle resource is not an object")
    binding = _stored_artifact_binding(row, label="lifecycle resource")
    version = row["version"]
    identity = record.get("entity_identity")
    if not isinstance(identity, dict):
        raise RuntimeError("stored lifecycle resource entity identity is invalid")
    identity_fingerprint = hashlib.sha256(_canonical_json(identity).encode("utf-8")).hexdigest()
    if (
        not isinstance(version, int)
        or isinstance(version, bool)
        or version < 0
        or record.get("id") != row["id"]
        or record.get("session_id") != row["session_id"]
        or record.get("goal_id") != row["goal_id"]
        or record.get("project_id") != binding.project_id
        or record.get("project_binding") != binding.project_binding
        or record.get("vendor_session_id") != row["vendor_session_id"]
        or record.get("harness_type") != row["harness_type"]
        or record.get("path") != row["path"]
        or record.get("scope_root") != row["scope_root"]
        or record.get("kind") != row["kind"]
        or record.get("state") != row["state"]
        or record.get("version") != version
        or record.get("current_operation_id") != row["current_operation_id"]
        or record.get("entity_fingerprint") != row["entity_fingerprint"]
        or record.get("readiness_fingerprint") != row["readiness_fingerprint"]
        or identity_fingerprint != row["entity_fingerprint"]
    ):
        raise RuntimeError("stored lifecycle resource authority binding is corrupt")
    session, session_binding = await _load_bound_session(
        transaction,
        str(row["session_id"]),
        require_goal_binding=True,
        require_live=require_live,
    )
    goal, goal_binding = await _load_bound_goal(
        transaction,
        str(row["goal_id"]),
        require_live=require_live,
    )
    if (
        session.goal_id != goal.id
        or session_binding != binding.project_binding
        or goal_binding.project_binding != binding.project_binding
        or session.vendor_session_id != row["vendor_session_id"]
        or session.harness_type.value != row["harness_type"]
    ):
        raise ProjectIdentityBlockedError(
            "lifecycle resource immutable target binding changed",
            code="artifact_project_identity_changed",
        )
    if require_entity:
        canonical = _canonical_lifecycle_path(Path(str(row["path"])), must_exist=True)
        if str(canonical) != row["path"]:
            raise PermissionError("lifecycle resource canonical path changed")
        _, current_fingerprint = _lifecycle_entity_identity(canonical)
        if current_fingerprint != row["entity_fingerprint"]:
            raise PermissionError("lifecycle resource entity was replaced")
    return record, row, session, goal, binding


async def _load_cleanup_operation(
    transaction: aiosqlite.Connection,
    operation_id: str,
    *,
    require_live: bool,
) -> tuple[dict[str, Any], aiosqlite.Row, list[dict[str, Any]]]:
    cursor = await transaction.execute(
        "SELECT * FROM lifecycle_operations WHERE id = ?",
        (operation_id,),
    )
    row = await cursor.fetchone()
    if row is None:
        raise LookupError("cleanup operation not found")
    record = _strict_json_loads(str(row["json"]))
    if not isinstance(record, dict) or not isinstance(record.get("manifest"), list):
        raise RuntimeError("stored cleanup operation is invalid")
    manifest = record["manifest"]
    manifest_hash = hashlib.sha256(_canonical_json(manifest).encode("utf-8")).hexdigest()
    version = row["version"]
    if (
        record.get("id") != row["id"]
        or record.get("lifecycle_resolution_id") != row["lifecycle_resolution_id"]
        or record.get("intervention_id") != row["intervention_id"]
        or record.get("session_id") != row["session_id"]
        or record.get("goal_id") != row["goal_id"]
        or record.get("project_id") != row["project_id"]
        or record.get("project_binding") != row["project_binding"]
        or record.get("vendor_session_id") != row["vendor_session_id"]
        or record.get("harness_type") != row["harness_type"]
        or record.get("action_hash") != row["action_hash"]
        or record.get("manifest_hash") != row["manifest_hash"]
        or manifest_hash != row["manifest_hash"]
        or record.get("state") != row["state"]
        or record.get("version") != version
        or record.get("dispatcher_boot_id") != row["dispatcher_boot_id"]
    ):
        raise RuntimeError("stored cleanup operation authority binding is corrupt")
    join_cursor = await transaction.execute(
        "SELECT * FROM lifecycle_operation_resources WHERE operation_id = ? "
        "ORDER BY ordinal LIMIT 257",
        (operation_id,),
    )
    join_rows = await join_cursor.fetchall()
    if len(join_rows) > 256 or len(join_rows) != len(manifest):
        raise RuntimeError("stored cleanup operation manifest is corrupt")
    joined_outcomes: list[dict[str, Any] | None] = []
    for entry, join_row in zip(manifest, join_rows, strict=True):
        join_record = _strict_json_loads(str(join_row["json"]))
        stored_outcome = (
            None if join_row["outcome"] is None else _strict_json_loads(str(join_row["outcome"]))
        )
        if (
            not isinstance(entry, dict)
            or not isinstance(join_record, dict)
            or entry.get("resource_id") != join_row["resource_id"]
            or entry.get("ordinal") != join_row["ordinal"]
            or entry.get("resource_version") != join_row["resource_version"]
            or entry.get("source_path") != join_row["source_path"]
            or entry.get("destination_path") != join_row["destination_path"]
            or entry.get("entity_fingerprint") != join_row["entity_fingerprint"]
            or entry.get("readiness_fingerprint") != join_row["readiness_fingerprint"]
            or join_record.get("operation_id") != operation_id
            or join_record.get("resource_id") != join_row["resource_id"]
            or join_record.get("ordinal") != join_row["ordinal"]
            or join_record.get("resource_version") != join_row["resource_version"]
            or join_record.get("source_path") != join_row["source_path"]
            or join_record.get("destination_path") != join_row["destination_path"]
            or join_record.get("entity_fingerprint") != join_row["entity_fingerprint"]
            or join_record.get("readiness_fingerprint") != join_row["readiness_fingerprint"]
            or join_record.get("outcome") != stored_outcome
            or join_record.get("version") != join_row["version"]
        ):
            raise RuntimeError("stored cleanup operation manifest is corrupt")
        joined_outcomes.append(stored_outcome)
    state = str(record.get("state") or "")
    raw_outcomes = record.get("outcomes")
    if state in {"reserved", "dispatching"}:
        if raw_outcomes is not None or any(outcome is not None for outcome in joined_outcomes):
            raise RuntimeError("stored cleanup operation outcomes are corrupt")
    else:
        if (
            not isinstance(raw_outcomes, list)
            or len(raw_outcomes) != len(joined_outcomes)
            or any(not isinstance(outcome, dict) for outcome in joined_outcomes)
        ):
            raise RuntimeError("stored cleanup operation outcomes are corrupt")
        raw_by_resource = {
            str(outcome.get("resource_id")): outcome
            for outcome in raw_outcomes
            if isinstance(outcome, dict)
        }
        joined_by_resource = {
            str(outcome.get("resource_id")): outcome
            for outcome in joined_outcomes
            if isinstance(outcome, dict)
        }
        if len(raw_by_resource) != len(raw_outcomes) or raw_by_resource != joined_by_resource:
            raise RuntimeError("stored cleanup operation outcomes are corrupt")
        classifications = {
            str(outcome.get("outcome")) for outcome in joined_outcomes if isinstance(outcome, dict)
        }
        expected_state = (
            "conflict"
            if "conflict" in classifications
            else "completed"
            if classifications == {"moved"}
            else "failed"
            if classifications == {"not_moved"}
            else "delivery_uncertain"
        )
        if state != expected_state:
            raise RuntimeError("stored cleanup operation terminal state is corrupt")
    session, session_binding = await _load_bound_session(
        transaction,
        str(row["session_id"]),
        require_goal_binding=True,
        require_live=require_live,
    )
    goal, goal_binding = await _load_bound_goal(
        transaction,
        str(row["goal_id"]),
        require_live=require_live,
    )
    if (
        session_binding != row["project_binding"]
        or goal_binding.project_binding != row["project_binding"]
        or session.goal_id != goal.id
        or session.vendor_session_id != row["vendor_session_id"]
        or session.harness_type.value != row["harness_type"]
    ):
        raise ProjectIdentityBlockedError(
            "cleanup operation immutable target binding changed",
            code="artifact_project_identity_changed",
        )
    for entry in manifest:
        (
            resource,
            _,
            resource_session,
            resource_goal,
            resource_binding,
        ) = await _load_bound_lifecycle_resource(
            transaction,
            str(entry["resource_id"]),
            require_live=require_live,
        )
        if (
            resource_session.id != session.id
            or resource_goal.id != goal.id
            or resource_binding.project_binding != row["project_binding"]
            or resource.get("path") != entry["source_path"]
            or resource.get("entity_fingerprint") != entry["entity_fingerprint"]
            or (
                record.get("state") in {"reserved", "dispatching"}
                and resource.get("readiness_fingerprint") != entry["readiness_fingerprint"]
            )
        ):
            raise RuntimeError("stored cleanup operation resource binding is corrupt")
    return record, row, manifest


async def _load_restore_operation(
    transaction: aiosqlite.Connection,
    operation_id: str,
    *,
    require_live: bool,
) -> tuple[
    dict[str, Any],
    aiosqlite.Row,
    list[dict[str, Any]],
    dict[str, Any],
]:
    cursor = await transaction.execute(
        "SELECT * FROM lifecycle_restore_operations WHERE id = ?",
        (operation_id,),
    )
    row = await cursor.fetchone()
    if row is None:
        raise LookupError("restore operation not found")
    binding = _stored_artifact_binding(row, label="restore operation")
    record = _strict_json_loads(str(row["json"]))
    if not isinstance(record, dict) or not isinstance(record.get("manifest"), list):
        raise RuntimeError("stored restore operation is invalid")
    manifest = record["manifest"]
    manifest_hash = hashlib.sha256(_canonical_json(manifest).encode("utf-8")).hexdigest()
    request_hash = hashlib.sha256(
        _canonical_json(
            {
                "cleanup_operation_id": row["cleanup_operation_id"],
                "authorized_by": row["authorized_by"],
                "idempotency_key": row["idempotency_key"],
            }
        ).encode("utf-8")
    ).hexdigest()
    version = row["version"]
    if (
        not isinstance(version, int)
        or isinstance(version, bool)
        or version < 0
        or not isinstance(row["authorized_by"], str)
        or not row["authorized_by"]
        or len(row["authorized_by"]) > 256
        or not isinstance(row["idempotency_key"], str)
        or not row["idempotency_key"]
        or len(row["idempotency_key"]) > 256
        or record.get("id") != row["id"]
        or record.get("cleanup_operation_id") != row["cleanup_operation_id"]
        or record.get("intervention_id") != row["intervention_id"]
        or record.get("session_id") != row["session_id"]
        or record.get("goal_id") != row["goal_id"]
        or record.get("project_id") != binding.project_id
        or record.get("project_binding") != binding.project_binding
        or record.get("vendor_session_id") != row["vendor_session_id"]
        or record.get("harness_type") != row["harness_type"]
        or record.get("cleanup_action_hash") != row["cleanup_action_hash"]
        or record.get("manifest_hash") != row["manifest_hash"]
        or manifest_hash != row["manifest_hash"]
        or record.get("authorized_by") != row["authorized_by"]
        or record.get("idempotency_key") != row["idempotency_key"]
        or record.get("request_hash") != row["request_hash"]
        or request_hash != row["request_hash"]
        or record.get("state") != row["state"]
        or record.get("version") != version
        or record.get("dispatcher_boot_id") != row["dispatcher_boot_id"]
    ):
        raise RuntimeError("stored restore operation authority binding is corrupt")
    join_cursor = await transaction.execute(
        "SELECT * FROM lifecycle_restore_operation_resources WHERE operation_id = ? "
        "ORDER BY ordinal LIMIT 257",
        (operation_id,),
    )
    join_rows = await join_cursor.fetchall()
    if len(join_rows) > 256 or not manifest or len(join_rows) != len(manifest):
        raise RuntimeError("stored restore operation manifest is corrupt")
    joined_outcomes: list[dict[str, Any] | None] = []
    for entry, join_row in zip(manifest, join_rows, strict=True):
        join_record = _strict_json_loads(str(join_row["json"]))
        stored_outcome = (
            None if join_row["outcome"] is None else _strict_json_loads(str(join_row["outcome"]))
        )
        if (
            not isinstance(entry, dict)
            or not isinstance(join_record, dict)
            or entry.get("resource_id") != join_row["resource_id"]
            or entry.get("ordinal") != join_row["ordinal"]
            or entry.get("resource_version") != join_row["resource_version"]
            or entry.get("cleanup_operation_id") != join_row["cleanup_operation_id"]
            or entry.get("cleanup_resource_version") != join_row["cleanup_resource_version"]
            or entry.get("cleanup_readiness_fingerprint")
            != join_row["cleanup_readiness_fingerprint"]
            or entry.get("source_path") != join_row["source_path"]
            or entry.get("destination_path") != join_row["destination_path"]
            or entry.get("entity_fingerprint") != join_row["entity_fingerprint"]
            or join_record.get("operation_id") != operation_id
            or join_record.get("resource_id") != join_row["resource_id"]
            or join_record.get("ordinal") != join_row["ordinal"]
            or join_record.get("resource_version") != join_row["resource_version"]
            or join_record.get("cleanup_operation_id") != join_row["cleanup_operation_id"]
            or join_record.get("cleanup_resource_version") != join_row["cleanup_resource_version"]
            or join_record.get("cleanup_readiness_fingerprint")
            != join_row["cleanup_readiness_fingerprint"]
            or join_record.get("source_path") != join_row["source_path"]
            or join_record.get("destination_path") != join_row["destination_path"]
            or join_record.get("entity_fingerprint") != join_row["entity_fingerprint"]
            or join_record.get("outcome") != stored_outcome
            or join_record.get("version") != join_row["version"]
        ):
            raise RuntimeError("stored restore operation manifest is corrupt")
        joined_outcomes.append(stored_outcome)
    state = str(record.get("state") or "")
    raw_outcomes = record.get("outcomes")
    if state in {"reserved", "dispatching"}:
        if raw_outcomes is not None or any(outcome is not None for outcome in joined_outcomes):
            raise RuntimeError("stored restore operation outcomes are corrupt")
    else:
        if (
            not isinstance(raw_outcomes, list)
            or len(raw_outcomes) != len(joined_outcomes)
            or any(not isinstance(outcome, dict) for outcome in joined_outcomes)
        ):
            raise RuntimeError("stored restore operation outcomes are corrupt")
        raw_by_resource = {
            str(outcome.get("resource_id")): outcome
            for outcome in raw_outcomes
            if isinstance(outcome, dict)
        }
        joined_by_resource = {
            str(outcome.get("resource_id")): outcome
            for outcome in joined_outcomes
            if isinstance(outcome, dict)
        }
        if len(raw_by_resource) != len(raw_outcomes) or raw_by_resource != joined_by_resource:
            raise RuntimeError("stored restore operation outcomes are corrupt")
        classifications = {
            str(outcome.get("outcome")) for outcome in joined_outcomes if isinstance(outcome, dict)
        }
        expected_state = (
            "conflict"
            if "conflict" in classifications
            else "completed"
            if classifications == {"restored"}
            else "failed"
            if classifications == {"not_restored"}
            else "delivery_uncertain"
        )
        if state != expected_state:
            raise RuntimeError("stored restore operation terminal state is corrupt")
    outcomes_by_resource = {
        str(outcome.get("resource_id")): outcome
        for outcome in joined_outcomes
        if isinstance(outcome, dict)
    }

    cleanup, _, cleanup_manifest = await _load_cleanup_operation(
        transaction,
        str(row["cleanup_operation_id"]),
        require_live=require_live,
    )
    session, session_binding = await _load_bound_session(
        transaction,
        str(row["session_id"]),
        require_goal_binding=True,
        require_live=require_live,
    )
    goal, goal_binding = await _load_bound_goal(
        transaction,
        str(row["goal_id"]),
        require_live=require_live,
    )
    if (
        cleanup.get("intervention_id") != row["intervention_id"]
        or cleanup.get("session_id") != session.id
        or cleanup.get("goal_id") != goal.id
        or cleanup.get("project_id") != binding.project_id
        or cleanup.get("project_binding") != binding.project_binding
        or cleanup.get("vendor_session_id") != row["vendor_session_id"]
        or cleanup.get("harness_type") != row["harness_type"]
        or cleanup.get("action_hash") != row["cleanup_action_hash"]
        or session_binding != binding.project_binding
        or goal_binding.project_binding != binding.project_binding
        or session.goal_id != goal.id
        or session.vendor_session_id != row["vendor_session_id"]
        or session.harness_type.value != row["harness_type"]
    ):
        raise ProjectIdentityBlockedError(
            "restore operation immutable target binding changed",
            code="artifact_project_identity_changed",
        )
    cleanup_by_resource = {str(entry["resource_id"]): entry for entry in cleanup_manifest}
    moved_ids = {
        str(outcome.get("resource_id"))
        for outcome in cleanup.get("outcomes") or []
        if isinstance(outcome, dict) and outcome.get("outcome") == "moved"
    }
    for entry in manifest:
        resource_id = str(entry["resource_id"])
        cleanup_entry = cleanup_by_resource.get(resource_id)
        (
            resource,
            _,
            resource_session,
            resource_goal,
            resource_binding,
        ) = await _load_bound_lifecycle_resource(
            transaction,
            resource_id,
            require_live=require_live,
        )
        if (
            cleanup_entry is None
            or resource_id not in moved_ids
            or entry.get("cleanup_operation_id") != cleanup.get("id")
            or entry.get("cleanup_resource_version") != cleanup_entry.get("resource_version")
            or entry.get("cleanup_readiness_fingerprint")
            != cleanup_entry.get("readiness_fingerprint")
            or entry.get("source_path") != cleanup_entry.get("destination_path")
            or entry.get("destination_path") != cleanup_entry.get("source_path")
            or entry.get("entity_fingerprint") != cleanup_entry.get("entity_fingerprint")
            or resource.get("path") != entry.get("destination_path")
            or resource.get("entity_fingerprint") != entry.get("entity_fingerprint")
            or resource_session.id != session.id
            or resource_goal.id != goal.id
            or resource_binding.project_binding != binding.project_binding
        ):
            raise RuntimeError("stored restore operation resource binding is corrupt")
        resource_version = int(resource["version"])
        frozen_version = int(entry["resource_version"])
        if state == "reserved":
            state_valid = (
                resource_version == frozen_version
                and resource.get("state") == "quarantined"
                and resource.get("current_operation_id") == cleanup.get("id")
            )
        elif state == "dispatching":
            state_valid = (
                resource_version == frozen_version + 1
                and resource.get("state") == "restoring"
                and resource.get("current_operation_id") == operation_id
            )
        else:
            outcome = outcomes_by_resource.get(resource_id)
            classification = outcome.get("outcome") if isinstance(outcome, dict) else None
            expected_resource = {
                "restored": ("active", None),
                "not_restored": ("quarantined", cleanup.get("id")),
                "conflict": ("conflict", operation_id),
            }.get(str(classification))
            state_valid = (
                resource_version == frozen_version + 2
                and expected_resource is not None
                and resource.get("state") == expected_resource[0]
                and resource.get("current_operation_id") == expected_resource[1]
                and (classification != "restored" or resource.get("readiness_fingerprint") is None)
            )
        if not state_valid:
            raise RuntimeError("stored restore operation resource state is corrupt")
    return record, row, manifest, cleanup


async def _has_authoritative_goal_successor(
    transaction: aiosqlite.Connection,
    goal: Goal,
    binding: ArtifactBinding,
) -> bool:
    parent_cursor = await transaction.execute(
        "SELECT intent_revision, intent_hash FROM goals WHERE id = ?",
        (goal.id,),
    )
    parent_row = await parent_cursor.fetchone()
    if parent_row is None:
        raise RuntimeError("goal successor parent authority disappeared")
    parent_revision, parent_hash = _validate_goal_intent_scalar_pair(
        parent_row["intent_revision"],
        parent_row["intent_hash"],
    )
    if await _goal_intent_hash_in_transaction(transaction, goal, binding) != parent_hash:
        raise RuntimeError("goal successor parent intent hash is corrupt")
    successor_cursor = await transaction.execute(
        "SELECT id, project_id, project_binding, intent_revision, intent_hash, json "
        "FROM goals WHERE json_valid(json) "
        "AND json_extract(json, '$.supersedes') = ? "
        "AND project_binding = ? ORDER BY id LIMIT 1001",
        (goal.id, binding.project_binding),
    )
    successor_rows = await successor_cursor.fetchall()
    if len(successor_rows) > 1000:
        raise RuntimeError("goal successor authority scan exceeds its safety bound")
    found = False
    for row in successor_rows:
        try:
            successor, successor_binding = await _load_bound_goal(
                transaction,
                str(row["id"]),
                require_live=False,
            )
            if (
                successor.id != row["id"]
                or successor.project_id != successor_binding.project_id
                or successor.supersedes != goal.id
                or successor_binding.project_binding != binding.project_binding
            ):
                raise RuntimeError("same-binding successor identity is corrupt")
            try:
                live_successor_binding = await _project_binding_snapshot(
                    transaction,
                    successor.project_id,
                )
            except ProjectIdentityBlockedError as exc:
                if exc.code != "project_identity_quarantined":
                    raise
                # A quarantined alias has no selected replacement yet. Its frozen
                # same-binding successor must continue to block predecessor writes.
            else:
                if live_successor_binding != successor_binding.project_binding:
                    # An explicitly resolved alias now names a different physical
                    # project, so this row is forensic rather than parent authority.
                    continue
            successor_revision, successor_hash = _validate_goal_intent_scalar_pair(
                row["intent_revision"],
                row["intent_hash"],
            )
            lineage_revision_matches = successor_revision == parent_revision + 1
            if parent_revision == successor_revision == 0:
                # Revision zero can only be installed while the immutable migration
                # boundary is created. Preserve legacy lineage without fabricating an
                # action count; prospective inserts are required to start at one.
                lineage_revision_matches = True
            if (
                not lineage_revision_matches
                or await _goal_intent_hash_in_transaction(
                    transaction,
                    successor,
                    successor_binding,
                )
                != successor_hash
            ):
                raise RuntimeError("same-binding successor intent lineage is corrupt")
        except (LookupError, TypeError, ValueError) as exc:
            raise RuntimeError("same-binding successor authority is corrupt") from exc
        if found:
            raise RuntimeError("goal has multiple authoritative successors")
        found = True
    return found


async def _reject_superseded_bound_goal(
    transaction: aiosqlite.Connection,
    goal: Goal,
    binding: ArtifactBinding,
) -> None:
    if await _has_authoritative_goal_successor(transaction, goal, binding):
        raise ValueError("goal has been superseded")


async def _load_active_mcp_principal_authority(
    transaction: aiosqlite.Connection,
    principal_id: str,
    *,
    checked_at: datetime,
    required_scope: str | None = None,
) -> tuple[dict[str, Any], HarnessSession, Goal, ArtifactBinding]:
    """Load one bearer and re-prove its immutable session/goal identity."""

    cursor = await transaction.execute(
        "SELECT * FROM mcp_principals WHERE id = ?",
        (principal_id,),
    )
    row = await cursor.fetchone()
    if row is None:
        raise PermissionError("MCP principal does not exist")
    try:
        principal = _strict_json_loads(str(row["json"]))
        if (
            not isinstance(principal, dict)
            or principal.get("principal_id") != row["id"]
            or principal.get("token_digest") != row["token_digest"]
            or principal.get("session_id") != row["session_id"]
            or principal.get("goal_id") != row["goal_id"]
            or principal.get("project_id") != row["project_id"]
            or principal.get("project_binding") != row["project_binding"]
            or principal.get("vendor_session_id") != row["vendor_session_id"]
            or principal.get("harness_type") != row["harness_type"]
            or principal.get("issued_at") != row["issued_at"]
            or principal.get("expires_at") != row["expires_at"]
            or principal.get("revoked_at") != row["revoked_at"]
        ):
            raise PermissionError("MCP principal durable identity is corrupt")
        frozen_binding = validate_project_binding(row["project_binding"])
        if not _principal_is_active(principal, checked_at):
            raise PermissionError("MCP principal is expired or revoked")
        if required_scope is not None and required_scope not in principal.get("scopes", []):
            raise PermissionError("MCP principal lacks the required tool scope")
        session, session_binding = await _load_bound_session(
            transaction,
            str(row["session_id"]),
            require_goal_binding=True,
        )
        goal, goal_binding = await _load_bound_goal(
            transaction,
            str(row["goal_id"]),
        )
        current_binding = await _project_binding_snapshot(
            transaction,
            str(row["project_id"]),
        )
        if (
            current_binding != frozen_binding
            or session_binding != frozen_binding
            or goal_binding.project_binding != frozen_binding
            or not await _same_live_project_binding(
                transaction,
                str(row["project_id"]),
                _session_project(session),
            )
            or not await _same_live_project_binding(
                transaction,
                str(row["project_id"]),
                goal.project_id,
            )
        ):
            raise PermissionError("MCP principal project binding changed")
        _validate_principal_record_binding(
            principal,
            session,
            goal,
            validate_project=False,
        )
        if await _has_authoritative_goal_successor(transaction, goal, goal_binding):
            raise PermissionError("MCP principal goal has been superseded")
    except PermissionError:
        raise
    except (LookupError, ProjectIdentityBlockedError, RuntimeError, TypeError, ValueError) as exc:
        raise PermissionError("MCP principal authority is no longer valid") from exc
    return principal, session, goal, goal_binding


async def _binding_for_context_item(
    transaction: aiosqlite.Connection,
    item: ContextItem,
) -> ArtifactBinding:
    if item.goal_id is None:
        return ArtifactBinding(
            item.project_id,
            await _project_binding_snapshot(transaction, item.project_id),
        )
    goal, goal_binding = await _load_bound_goal(transaction, item.goal_id)
    if not await _same_live_project_binding(
        transaction,
        item.project_id,
        goal.project_id,
    ):
        raise ValueError("context project binding does not match its goal")
    return ArtifactBinding(item.project_id, goal_binding.project_binding)


async def _binding_for_decision(
    transaction: aiosqlite.Connection,
    decision: Decision,
) -> ArtifactBinding:
    _, binding = await _load_bound_goal(transaction, decision.goal_id)
    return binding


async def _event_project_identity_failure_reason(
    transaction: aiosqlite.Connection,
    processing: dict[str, Any],
) -> str | None:
    """Revalidate both the raw event key and its immutable goal artifact."""

    project_id = processing.get("project_id")
    if not project_id:
        return None
    accepted_binding = processing.get("accepted_project_binding")
    if not isinstance(accepted_binding, str):
        return "event_project_identity_snapshot_missing"
    goal_id = processing.get("goal_id")
    if goal_id:
        try:
            goal, goal_binding = await _load_bound_goal(transaction, str(goal_id))
        except (LookupError, ProjectIdentityBlockedError, RuntimeError, ValueError):
            return "event_project_identity_changed"
        if goal_binding.project_binding != accepted_binding:
            return "event_project_identity_changed"
        try:
            same_project = await _same_live_project_binding(
                transaction,
                str(project_id),
                goal.project_id,
            )
        except ProjectIdentityBlockedError:
            return "event_project_identity_changed"
        if not same_project:
            return "event_project_identity_changed"
        return None
    try:
        current_binding = await _project_binding_snapshot(transaction, str(project_id))
    except ProjectIdentityBlockedError:
        return "event_project_identity_changed"
    if current_binding != accepted_binding:
        return "event_project_identity_changed"
    return None


class Store:
    def __init__(self, path: Path, *, process_boot_id: str | None = None) -> None:
        self.path = path
        self.process_boot_id = process_boot_id or _PROCESS_BOOT_ID
        _validate_store_id(self.process_boot_id, label="process boot id")
        self.audit_path = path.parent / "PEX_INTERVENTION_LOG.jsonl"
        self._db: aiosqlite.Connection | None = None
        self._write_lock = asyncio.Lock()
        self._audit_flush_lock = asyncio.Lock()

    async def connect(self) -> None:
        self.path.parent.mkdir(parents=True, exist_ok=True)
        self._db = await aiosqlite.connect(self.path, timeout=5.0)
        try:
            await self._db.execute("PRAGMA journal_mode=WAL")
            await _configure_connection(self._db)
            await self._db.executescript(SCHEMA)
            await self._migrate_artifact_project_bindings()
            await self._migrate_goal_intent_authority()
            await self._migrate_goal_control_operation_coverage()
            await self._migrate_goal_control_attention_coverage()
            await self._migrate_session_control()
            await self._migrate_intervention_project_bindings()
            await self._migrate_lifecycle_resource_operations()
            await self._migrate_lifecycle_restore_operations()
            await self._migrate_credential_project_bindings()
            await self._migrate_overlay_operations()
            await self._migrate_event_processing()
            await self._migrate_operator_delivery_contract()
            await self._migrate_human_decision_delivery_contract()
            await self._migrate_human_session_control_coverage()
            await self._migrate_human_operator_action_coverage()
            # Classify interrupted child cleanup effects before the parent lifecycle
            # resolution is generically sealed uncertain. This never replays a rename.
            await self.recover_interrupted_cleanup_operations()
            await self.recover_interrupted_restore_operations()
            await self.recover_interrupted_overlay_operations()
            await self._recover_interrupted_human_decision_deliveries()
            await self._try_sync_intervention_audit()
        except BaseException:
            connection = self._db
            self._db = None
            if connection is not None:
                await asyncio.shield(connection.close())
            raise

    async def _migrate_goal_control_operation_coverage(self) -> None:
        """Declare prospective authenticated REST coverage without inventing history."""

        await self.db.execute("BEGIN IMMEDIATE")
        try:
            cursor = await self.db.execute(
                "SELECT initialized_at, schema_version, json "
                "FROM goal_control_operation_migration_state WHERE singleton = 1"
            )
            rows = await cursor.fetchall()
            if not rows:
                initialized_at = utcnow().isoformat()
                record = {
                    "schema": "pex.goal-control-operation-migration.v1",
                    "initialized_at": initialized_at,
                    "schema_version": 1,
                    "covered_surface": "authenticated_rest",
                    "covered_actions": sorted(GOAL_CONTROL_ACTIONS),
                    "legacy_operation_cardinality": "unknown",
                }
                await self.db.execute(
                    "INSERT INTO goal_control_operation_migration_state("
                    "singleton, initialized_at, schema_version, json) VALUES (1, ?, 1, ?)",
                    (initialized_at, _canonical_json(record)),
                )
                rows = [
                    {
                        "initialized_at": initialized_at,
                        "schema_version": 1,
                        "json": _canonical_json(record),
                    }
                ]
            if len(rows) != 1:
                raise RuntimeError("goal control operation migration marker is ambiguous")
            row = rows[0]
            initialized_at = row["initialized_at"]
            if not isinstance(initialized_at, str):
                raise RuntimeError("goal control operation migration timestamp is invalid")
            try:
                parsed_at = datetime.fromisoformat(initialized_at)
            except ValueError as exc:
                raise RuntimeError(
                    "goal control operation migration timestamp is invalid"
                ) from exc
            if parsed_at.tzinfo is None or parsed_at.utcoffset() is None:
                raise RuntimeError("goal control operation migration timestamp is invalid")
            expected = {
                "schema": "pex.goal-control-operation-migration.v1",
                "initialized_at": initialized_at,
                "schema_version": 1,
                "covered_surface": "authenticated_rest",
                "covered_actions": sorted(GOAL_CONTROL_ACTIONS),
                "legacy_operation_cardinality": "unknown",
            }
            try:
                payload = _strict_json_loads(str(row["json"]))
            except (TypeError, ValueError, json.JSONDecodeError) as exc:
                raise RuntimeError(
                    "goal control operation migration marker is corrupt"
                ) from exc
            if (
                row["schema_version"] != 1
                or payload != expected
                or str(row["json"]) != _canonical_json(expected)
            ):
                raise RuntimeError("goal control operation migration marker is corrupt")
            await self.db.commit()
        except Exception:
            await self.db.rollback()
            raise

    async def _migrate_goal_control_attention_coverage(self) -> None:
        """Freeze exact legacy operation identities without inferring eligibility."""

        await self.db.execute("BEGIN IMMEDIATE")
        try:
            cursor = await self.db.execute(
                "SELECT * FROM goal_control_attention_migration_state WHERE singleton = 1"
            )
            rows = await cursor.fetchall()
            if not rows:
                initialized_at = utcnow().isoformat()
                operation_cursor = await self.db.execute(
                    "SELECT * FROM goal_control_operations ORDER BY operation_id"
                )
                legacy_operation_ids: list[str] = []
                for operation_row in await operation_cursor.fetchall():
                    operation = _goal_control_operation_record(operation_row)
                    if operation["action_kind"] not in GOAL_CONTROL_ATTENTION_ACTIONS:
                        continue
                    legacy_operation_ids.append(operation["operation_id"])
                    legacy = {
                        "schema": "pex.goal-control-attention-legacy-operation.v1",
                        "operation_id": operation["operation_id"],
                        "action_kind": operation["action_kind"],
                        "request_hash": operation["request_hash"],
                        "captured_at": initialized_at,
                        "schema_version": 1,
                    }
                    await self.db.execute(
                        "INSERT INTO goal_control_attention_legacy_operations("
                        "operation_id, action_kind, request_hash, captured_at, "
                        "schema_version, json) VALUES (?, ?, ?, ?, 1, ?)",
                        (
                            operation["operation_id"],
                            operation["action_kind"],
                            operation["request_hash"],
                            initialized_at,
                            _canonical_json(legacy),
                        ),
                    )
                legacy_operation_set_hash = hashlib.sha256(
                    _canonical_json(legacy_operation_ids).encode("utf-8")
                ).hexdigest()
                marker = {
                    "schema": GOAL_CONTROL_ATTENTION_MIGRATION_SCHEMA,
                    "initialized_at": initialized_at,
                    "legacy_operation_count": len(legacy_operation_ids),
                    "legacy_operation_set_hash": legacy_operation_set_hash,
                    "schema_version": 1,
                    "covered_surface": "authenticated_rest_goal_control",
                    "covered_actions": sorted(GOAL_CONTROL_ATTENTION_ACTIONS),
                    "legacy_eligibility": "not_inferred",
                }
                await self.db.execute(
                    "INSERT INTO goal_control_attention_migration_state("
                    "singleton, initialized_at, legacy_operation_count, "
                    "legacy_operation_set_hash, schema_version, json) "
                    "VALUES (1, ?, ?, ?, 1, ?)",
                    (
                        initialized_at,
                        len(legacy_operation_ids),
                        legacy_operation_set_hash,
                        _canonical_json(marker),
                    ),
                )
                rows = [
                    {
                        "singleton": 1,
                        "initialized_at": initialized_at,
                        "legacy_operation_count": len(legacy_operation_ids),
                        "legacy_operation_set_hash": legacy_operation_set_hash,
                        "schema_version": 1,
                        "json": _canonical_json(marker),
                    }
                ]
            if len(rows) != 1:
                raise RuntimeError("goal control attention migration marker is ambiguous")
            marker = _goal_control_attention_migration_record(rows[0])
            legacy_cursor = await self.db.execute(
                "SELECT l.*, o.action_kind AS operation_action_kind, "
                "o.request_hash AS operation_request_hash "
                "FROM goal_control_attention_legacy_operations AS l JOIN "
                "goal_control_operations AS o USING (operation_id) ORDER BY l.operation_id"
            )
            legacy_rows = await legacy_cursor.fetchall()
            legacy_operation_ids = [str(row["operation_id"]) for row in legacy_rows]
            if (
                len(legacy_rows) != marker["legacy_operation_count"]
                or hashlib.sha256(
                    _canonical_json(legacy_operation_ids).encode("utf-8")
                ).hexdigest()
                != marker["legacy_operation_set_hash"]
            ):
                raise RuntimeError("goal control attention legacy snapshot is corrupt")
            for row in legacy_rows:
                expected = {
                    "schema": "pex.goal-control-attention-legacy-operation.v1",
                    "operation_id": str(row["operation_id"]),
                    "action_kind": str(row["action_kind"]),
                    "request_hash": str(row["request_hash"]),
                    "captured_at": str(row["captured_at"]),
                    "schema_version": 1,
                }
                if (
                    row["action_kind"] not in GOAL_CONTROL_ATTENTION_ACTIONS
                    or row["operation_action_kind"] != row["action_kind"]
                    or row["operation_request_hash"] != row["request_hash"]
                    or row["captured_at"] != marker["initialized_at"]
                    or row["schema_version"] != 1
                    or str(row["json"]) != _canonical_json(expected)
                ):
                    raise RuntimeError("goal control attention legacy snapshot is corrupt")
            for action_kind in sorted(GOAL_CONTROL_ATTENTION_ACTIONS):
                coverage = {
                    "schema": "pex.human-action-coverage.v1",
                    "action_kind": action_kind,
                    "coverage_started_at": marker["initialized_at"],
                    "actor_assurance": OPERATOR_ACTOR_ASSURANCE,
                    "schema_version": 1,
                }
                await self.db.execute(
                    "INSERT OR IGNORE INTO goal_control_attention_coverage("
                    "action_kind, coverage_started_at, actor_assurance, schema_version, json) "
                    "VALUES (?, ?, ?, 1, ?)",
                    (
                        action_kind,
                        marker["initialized_at"],
                        OPERATOR_ACTOR_ASSURANCE,
                        _canonical_json(coverage),
                    ),
                )
            coverage_cursor = await self.db.execute(
                "SELECT * FROM goal_control_attention_coverage ORDER BY action_kind"
            )
            coverage_rows = await coverage_cursor.fetchall()
            if len(coverage_rows) != len(GOAL_CONTROL_ATTENTION_ACTIONS):
                raise RuntimeError("goal control attention coverage is incomplete")
            for row in coverage_rows:
                expected = {
                    "schema": "pex.human-action-coverage.v1",
                    "action_kind": str(row["action_kind"]),
                    "coverage_started_at": marker["initialized_at"],
                    "actor_assurance": OPERATOR_ACTOR_ASSURANCE,
                    "schema_version": 1,
                }
                if (
                    row["action_kind"] not in GOAL_CONTROL_ATTENTION_ACTIONS
                    or row["coverage_started_at"] != marker["initialized_at"]
                    or row["actor_assurance"] != OPERATOR_ACTOR_ASSURANCE
                    or row["schema_version"] != 1
                    or str(row["json"]) != _canonical_json(expected)
                ):
                    raise RuntimeError("goal control attention coverage is corrupt")
            await self.db.commit()
        except Exception:
            await self.db.rollback()
            raise

    async def _migrate_human_decision_delivery_contract(self) -> None:
        """Start exact-turn enforcement prospectively without inventing legacy identity."""

        await self.db.execute("BEGIN IMMEDIATE")
        try:
            columns_cursor = await self.db.execute(
                "PRAGMA table_info(human_decision_resolutions)"
            )
            columns = {str(row["name"]) for row in await columns_cursor.fetchall()}
            if "delivery_contract_version" not in columns:
                await self.db.execute(
                    "ALTER TABLE human_decision_resolutions ADD COLUMN "
                    "delivery_contract_version INTEGER NOT NULL DEFAULT 1 "
                    "CHECK(delivery_contract_version IN (1, 3))"
                )
            await self.db.execute(
                "CREATE TRIGGER IF NOT EXISTS "
                "trg_human_decision_delivery_contract_immutable "
                "BEFORE UPDATE OF delivery_contract_version ON human_decision_resolutions "
                "WHEN NEW.delivery_contract_version IS NOT OLD.delivery_contract_version "
                "BEGIN SELECT RAISE(ABORT, "
                "'human decision delivery contract is immutable'); END"
            )
            await self.db.execute(
                "CREATE TRIGGER IF NOT EXISTS "
                "trg_human_decision_delivery_contract_prospective "
                "BEFORE INSERT ON human_decision_resolutions "
                "WHEN NEW.delivery_contract_version != 3 "
                "BEGIN SELECT RAISE(ABORT, "
                "'new human decision delivery contract must be exact-turn'); END"
            )
            await self.db.commit()
        except Exception:
            await self.db.rollback()
            raise

    async def _migrate_operator_delivery_contract(self) -> None:
        """Preserve legacy effects while making every new receipt exact-turn."""

        await self.db.execute("BEGIN IMMEDIATE")
        try:
            columns_cursor = await self.db.execute("PRAGMA table_info(operator_effects)")
            columns = {str(row["name"]) for row in await columns_cursor.fetchall()}
            if "delivery_contract_version" not in columns:
                await self.db.execute(
                    "ALTER TABLE operator_effects ADD COLUMN "
                    "delivery_contract_version INTEGER NOT NULL DEFAULT 1 "
                    "CHECK(delivery_contract_version IN (1, 3))"
                )
            await self.db.execute(
                "CREATE TRIGGER IF NOT EXISTS trg_operator_delivery_contract_immutable "
                "BEFORE UPDATE OF delivery_contract_version ON operator_effects "
                "WHEN NEW.delivery_contract_version IS NOT OLD.delivery_contract_version "
                "BEGIN SELECT RAISE(ABORT, "
                "'operator delivery contract is immutable'); END"
            )
            await self.db.execute(
                "CREATE TRIGGER IF NOT EXISTS trg_operator_delivery_contract_prospective "
                "BEFORE INSERT ON operator_effects "
                "WHEN NEW.delivery_contract_version != 3 "
                "BEGIN SELECT RAISE(ABORT, "
                "'new operator delivery contract must be exact-turn'); END"
            )
            await self.db.execute(
                "CREATE TRIGGER IF NOT EXISTS trg_operator_effect_authority_immutable "
                "BEFORE UPDATE OF principal_id, action_kind, idempotency_key, request_hash, "
                "source_session_id, target_session_id, project_id, goal_id, reserved_at, "
                "payload_json ON operator_effects WHEN "
                "NEW.principal_id IS NOT OLD.principal_id OR "
                "NEW.action_kind IS NOT OLD.action_kind OR "
                "NEW.idempotency_key IS NOT OLD.idempotency_key OR "
                "NEW.request_hash IS NOT OLD.request_hash OR "
                "NEW.source_session_id IS NOT OLD.source_session_id OR "
                "NEW.target_session_id IS NOT OLD.target_session_id OR "
                "NEW.project_id IS NOT OLD.project_id OR "
                "NEW.goal_id IS NOT OLD.goal_id OR "
                "NEW.reserved_at IS NOT OLD.reserved_at OR "
                "NEW.payload_json IS NOT OLD.payload_json BEGIN SELECT RAISE(ABORT, "
                "'operator effect authority is immutable'); END"
            )
            await self.db.commit()
        except Exception:
            await self.db.rollback()
            raise

    async def _migrate_human_session_control_coverage(self) -> None:
        """Declare prospective actor-assured coverage without backfilling history."""

        await self.db.execute("BEGIN IMMEDIATE")
        try:
            started_at = utcnow().isoformat()
            for action_kind in ("pause_supervision", "resume_supervision"):
                record = {
                    "schema": "pex.human-action-coverage.v1",
                    "action_kind": action_kind,
                    "coverage_started_at": started_at,
                    "actor_assurance": "bridge_bearer",
                    "schema_version": 1,
                }
                await self.db.execute(
                    "INSERT OR IGNORE INTO human_session_control_coverage(action_kind, "
                    "coverage_started_at, actor_assurance, schema_version, json) "
                    "VALUES (?, ?, ?, 1, ?)",
                    (
                        action_kind,
                        started_at,
                        "bridge_bearer",
                        _canonical_json(record),
                    ),
                )
            await self.db.commit()
        except Exception:
            await self.db.rollback()
            raise

