    async def recent_events_for_binding(
        self,
        *,
        session_id: str,
        goal_id: str,
        project_id: str,
        harness_type: str,
        limit: int = 80,
    ) -> list[HarnessEvent]:
        """Return only events carrying one exact live verification binding."""

        _validate_store_id(session_id, label="event session id")
        _validate_store_id(goal_id, label="event goal id")
        if not project_id or len(project_id) > MAX_PROJECT_ID_LENGTH:
            raise ValueError("event project id is invalid")
        if not harness_type or len(harness_type) > 128:
            raise ValueError("event harness type is invalid")
        if not 1 <= limit <= MAX_EVENT_QUERY_LIMIT:
            raise ValueError(f"event limit must be between 1 and {MAX_EVENT_QUERY_LIMIT}")
        await _reject_quarantined_project_binding(self.db, project_id)
        cur = await self.db.execute(
            "SELECT e.json FROM event_processing AS p "
            "JOIN events AS e ON e.event_id = p.event_id "
            "WHERE p.session_id = ? AND p.goal_id = ? "
            "AND p.harness_type = ? ORDER BY p.accept_seq DESC LIMIT ?",
            (session_id, goal_id, harness_type, MAX_EVENT_QUERY_LIMIT),
        )
        newest: list[HarnessEvent] = []
        for row in await cur.fetchall():
            event = HarnessEvent.model_validate_json(row["json"])
            if event.project_id is None or not await _same_live_project_binding(
                self.db,
                event.project_id,
                project_id,
            ):
                continue
            newest.append(event)
            if len(newest) == limit:
                break
        newest.reverse()
        return newest

    async def latest_events(self, limit: int = 40) -> list[HarnessEvent]:
        if not 1 <= limit <= MAX_EVENT_QUERY_LIMIT:
            raise ValueError(f"event limit must be between 1 and {MAX_EVENT_QUERY_LIMIT}")
        cur = await self.db.execute(
            "SELECT e.json FROM event_processing AS p "
            "JOIN events AS e ON e.event_id = p.event_id "
            "ORDER BY p.accept_seq DESC LIMIT ?",
            (limit,),
        )
        return [HarnessEvent.model_validate_json(row["json"]) for row in await cur.fetchall()]

    async def event_publication_page(
        self,
        *,
        after: int = 0,
        through: int | None = None,
        limit: int = 100,
        session_id: str | None = None,
    ) -> dict[str, Any]:
        """Return one frozen acceptance-ordered event page.

        Cursors are integers internally and serialized as decimal strings by
        this boundary so JavaScript clients never lose SQLite integer precision.
        ``after`` is exclusive and ``through`` is inclusive.
        """

        if not isinstance(after, int) or isinstance(after, bool) or after < 0:
            raise ValueError("event cursor after is invalid")
        if through is not None and (
            not isinstance(through, int) or isinstance(through, bool) or through < 0
        ):
            raise ValueError("event cursor through is invalid")
        if not 1 <= limit <= MAX_EVENT_QUERY_LIMIT:
            raise ValueError(f"event limit must be between 1 and {MAX_EVENT_QUERY_LIMIT}")
        if session_id is not None:
            _validate_store_id(session_id, label="event session id")

        bounds_cursor = await self.db.execute(
            "SELECT MIN(pub.accept_seq) AS earliest, MAX(pub.accept_seq) AS latest "
            "FROM event_publications AS pub "
            "JOIN event_processing AS p ON p.accept_seq = pub.accept_seq",
        )
        bounds = await bounds_cursor.fetchone()
        earliest = int(bounds["earliest"]) if bounds and bounds["earliest"] is not None else 0
        watermark = int(bounds["latest"]) if bounds and bounds["latest"] is not None else 0
        frozen_through = watermark if through is None else through
        if frozen_through > watermark:
            raise ValueError("event cursor through exceeds the current watermark")
        if after > frozen_through:
            raise ValueError("event cursor after exceeds through")
        gap = earliest > 0 and after < earliest - 1
        items: list[dict[str, Any]] = []
        if not gap and after < frozen_through:
            clauses = ["pub.accept_seq > ?", "pub.accept_seq <= ?"]
            args: list[Any] = [after, frozen_through]
            if session_id is not None:
                clauses.append("p.session_id = ?")
                args.append(session_id)
            args.append(limit)
            cursor = await self.db.execute(
                "SELECT pub.accept_seq, e.json FROM event_publications AS pub "
                "JOIN event_processing AS p ON p.accept_seq = pub.accept_seq "
                "JOIN events AS e ON e.event_id = pub.event_id WHERE "
                + " AND ".join(clauses)
                + " ORDER BY pub.accept_seq LIMIT ?",
                tuple(args),
            )
            for row in await cursor.fetchall():
                items.append(
                    {
                        "cursor": str(int(row["accept_seq"])),
                        "event": HarnessEvent.model_validate_json(row["json"]).model_dump(
                            mode="json"
                        ),
                    }
                )
        next_cursor = items[-1]["cursor"] if items else str(after)
        return {
            "schema": "pex.event-page.v1",
            "scope": {"session_id": session_id},
            "after": str(after),
            "through": str(frozen_through),
            "next": next_cursor,
            "watermark": str(watermark),
            "retention": {
                "earliest": str(earliest),
                "latest": str(watermark),
            },
            "gap": (
                {
                    "detected": True,
                    "requested_after": str(after),
                    "earliest_available": str(earliest),
                }
                if gap
                else {"detected": False}
            ),
            "degraded": False,
            "items": items,
            "has_more": bool(items and int(next_cursor) < frozen_through),
        }

    async def claim_event_followup(
        self,
        *,
        event_id: str,
        kind: str,
        owner: str,
        lease_seconds: int = EVENT_PROCESSING_LEASE_SECONDS,
    ) -> dict[str, Any]:
        """Claim one idempotent post-commit follow-up for bounded execution."""

        _validate_store_id(event_id, label="event id")
        _validate_store_id(owner, label="event follow-up owner")
        if not owner.startswith(f"{self.process_boot_id}:"):
            raise ValueError("event follow-up owner is not bound to this process boot")
        if kind not in {"auto_handoff", "human_attention"}:
            raise ValueError("event follow-up kind is invalid")
        if not 1 <= lease_seconds <= 300:
            raise ValueError("event follow-up lease is invalid")
        async with aiosqlite.connect(self.path, timeout=5.0) as transaction:
            await _configure_connection(transaction)
            await transaction.execute("BEGIN IMMEDIATE")
            try:
                cursor = await transaction.execute(
                    "SELECT * FROM event_followups WHERE event_id = ? AND kind = ?",
                    (event_id, kind),
                )
                row = await cursor.fetchone()
                if row is None:
                    await transaction.commit()
                    return {"outcome": "absent"}
                followup = _event_followup_record(row)
                if followup["state"] == "complete":
                    await transaction.commit()
                    return {"outcome": "complete", "followup": followup}
                processing_cursor = await transaction.execute(
                    "SELECT project_id FROM event_processing WHERE event_id = ?",
                    (event_id,),
                )
                processing_row = await processing_cursor.fetchone()
                if processing_row is None:
                    raise RuntimeError("event follow-up processing binding is missing")
                if processing_row["project_id"]:
                    try:
                        await _reject_quarantined_project_binding(
                            transaction,
                            str(processing_row["project_id"]),
                        )
                    except ProjectIdentityBlockedError as exc:
                        now = utcnow().isoformat()
                        result = {
                            "status": "skipped",
                            "reason": exc.code,
                        }
                        updated = await transaction.execute(
                            "UPDATE event_followups SET state = 'complete', "
                            "result_json = ?, lease_owner = NULL, "
                            "lease_expires_at = NULL, updated_at = ?, "
                            "completed_at = ? WHERE event_id = ? AND kind = ? "
                            "AND state != 'complete'",
                            (
                                _canonical_json(result),
                                now,
                                now,
                                event_id,
                                kind,
                            ),
                        )
                        if updated.rowcount != 1:
                            raise RuntimeError(
                                "blocked event follow-up completion was lost"
                            ) from exc
                        cursor = await transaction.execute(
                            "SELECT * FROM event_followups WHERE event_id = ? AND kind = ?",
                            (event_id, kind),
                        )
                        completed_row = await cursor.fetchone()
                        if completed_row is None:
                            raise RuntimeError("blocked event follow-up disappeared") from exc
                        completed = _event_followup_record(completed_row)
                        await transaction.commit()
                        return {
                            "outcome": "complete",
                            "reason": exc.code,
                            "followup": completed,
                        }
                now = utcnow()
                lease_active = False
                try:
                    lease_active = bool(followup["lease_expires_at"]) and _time_key(
                        datetime.fromisoformat(str(followup["lease_expires_at"]))
                    ) > _time_key(now)
                except ValueError:
                    lease_active = False
                if (
                    followup["state"] == "claimed"
                    and lease_active
                    and followup["lease_owner"] != owner
                    and str(followup["lease_owner"] or "").startswith(f"{self.process_boot_id}:")
                ):
                    await transaction.commit()
                    return {"outcome": "busy", "followup": followup}
                expires = (now + timedelta(seconds=lease_seconds)).isoformat()
                updated = await transaction.execute(
                    "UPDATE event_followups SET state = 'claimed', attempt_count = "
                    "attempt_count + 1, lease_owner = ?, lease_expires_at = ?, "
                    "updated_at = ? WHERE event_id = ? AND kind = ?",
                    (owner, expires, now.isoformat(), event_id, kind),
                )
                if updated.rowcount != 1:
                    raise RuntimeError("event follow-up claim was lost")
                cursor = await transaction.execute(
                    "SELECT * FROM event_followups WHERE event_id = ? AND kind = ?",
                    (event_id, kind),
                )
                claimed_row = await cursor.fetchone()
                if claimed_row is None:  # pragma: no cover - transaction invariant
                    raise RuntimeError("claimed event follow-up disappeared")
                claimed = _event_followup_record(claimed_row)
                await transaction.commit()
                return {"outcome": "claimed", "followup": claimed}
            except Exception:
                await transaction.rollback()
                raise

    async def list_recoverable_event_followups(
        self,
        *,
        limit: int = 1000,
    ) -> list[dict[str, Any]]:
        if not 1 <= limit <= 1000:
            raise ValueError("event follow-up recovery limit is invalid")
        now = utcnow().isoformat()
        cursor = await self.db.execute(
            "SELECT * FROM event_followups WHERE state = 'pending' OR "
            "(state = 'claimed' AND (lease_expires_at IS NULL OR lease_expires_at <= ? "
            "OR substr(lease_owner, 1, length(?)) != ?)) "
            "ORDER BY created_at, event_id, kind LIMIT ?",
            (
                now,
                f"{self.process_boot_id}:",
                f"{self.process_boot_id}:",
                limit,
            ),
        )
        return [_event_followup_record(row) for row in await cursor.fetchall()]

    async def complete_event_followup(
        self,
        *,
        event_id: str,
        kind: str,
        owner: str,
        result: dict[str, Any],
    ) -> dict[str, Any]:
        """Seal one claimed follow-up with an immutable local result receipt."""

        _validate_store_id(event_id, label="event id")
        _validate_store_id(owner, label="event follow-up owner")
        if not owner.startswith(f"{self.process_boot_id}:"):
            raise ValueError("event follow-up owner is not bound to this process boot")
        if kind not in {"auto_handoff", "human_attention"}:
            raise ValueError("event follow-up kind is invalid")
        result_json = _canonical_json(result)
        async with aiosqlite.connect(self.path, timeout=5.0) as transaction:
            await _configure_connection(transaction)
            await transaction.execute("BEGIN IMMEDIATE")
            try:
                cursor = await transaction.execute(
                    "SELECT * FROM event_followups WHERE event_id = ? AND kind = ?",
                    (event_id, kind),
                )
                row = await cursor.fetchone()
                if row is None:
                    raise LookupError("event follow-up not found")
                followup = _event_followup_record(row)
                if followup["state"] == "complete":
                    if followup["result"] != result:
                        raise ValueError("terminal event follow-up result cannot change")
                    await transaction.commit()
                    return followup
                if followup["state"] != "claimed" or followup["lease_owner"] != owner:
                    raise PermissionError("event follow-up claim is not owned")
                now = utcnow().isoformat()
                updated = await transaction.execute(
                    "UPDATE event_followups SET state = 'complete', result_json = ?, "
                    "lease_owner = NULL, lease_expires_at = NULL, completed_at = ?, "
                    "updated_at = ? WHERE event_id = ? AND kind = ? AND state = "
                    "'claimed' AND lease_owner = ?",
                    (result_json, now, now, event_id, kind, owner),
                )
                if updated.rowcount != 1:
                    raise RuntimeError("event follow-up completion CAS was lost")
                cursor = await transaction.execute(
                    "SELECT * FROM event_followups WHERE event_id = ? AND kind = ?",
                    (event_id, kind),
                )
                completed_row = await cursor.fetchone()
                if completed_row is None:  # pragma: no cover - transaction invariant
                    raise RuntimeError("completed event follow-up disappeared")
                completed = _event_followup_record(completed_row)
                await transaction.commit()
                return completed
            except Exception:
                await transaction.rollback()
                raise

    async def add_intervention(self, intervention: Intervention) -> None:
        await self._write_intervention(intervention, "created", create=True)

    async def prepare_cursor_hook_delivery(
        self,
        intervention_id: str,
        preparation_receipt: dict[str, Any],
        *,
        expected_authority: dict[str, Any],
    ) -> dict[str, str]:
        """Mint the one-time hook packet for an already-prepared uncertain effect."""

        _validate_store_id(intervention_id, label="Cursor hook intervention id")
        authority = validate_cursor_hook_authority(expected_authority)
        packet: dict[str, str]
        async with aiosqlite.connect(self.path, timeout=5.0) as transaction:
            await _configure_connection(transaction)
            await transaction.execute("BEGIN IMMEDIATE")
            try:
                duplicate_cursor = await transaction.execute(
                    "SELECT 1 FROM cursor_hook_preparations WHERE intervention_id = ?",
                    (intervention_id,),
                )
                if await duplicate_cursor.fetchone() is not None:
                    # The raw nonce is deliberately not durable. Replaying prepare
                    # must never mint a second credential for the same action.
                    raise ValueError("Cursor hook preparation already exists")

                intervention, binding, session, goal, _ = await _load_bound_intervention(
                    transaction,
                    intervention_id,
                    require_live=True,
                )
                receipt = validate_cursor_hook_preparation_receipt(
                    preparation_receipt,
                    session=session,
                )
                duplicate_cursor = await transaction.execute(
                    "SELECT 1 FROM cursor_hook_preparations WHERE preparation_id = ?",
                    (receipt["preparation_id"],),
                )
                if await duplicate_cursor.fetchone() is not None:
                    raise ValueError("Cursor hook preparation already exists")
                session_cursor = await transaction.execute(
                    "SELECT * FROM sessions WHERE id = ?",
                    (intervention.session_id,),
                )
                session_row = await session_cursor.fetchone()
                if session_row is None:  # pragma: no cover - bound loader invariant
                    raise RuntimeError("Cursor hook session disappeared")
                goal_cursor = await transaction.execute(
                    "SELECT intent_revision, intent_hash FROM goals WHERE id = ?",
                    (intervention.goal_id,),
                )
                goal_row = await goal_cursor.fetchone()
                if goal_row is None:  # pragma: no cover - bound loader invariant
                    raise RuntimeError("Cursor hook goal disappeared")
                intent_revision, intent_hash = _validate_goal_intent_scalar_pair(
                    goal_row["intent_revision"],
                    goal_row["intent_hash"],
                )
                actual_authority = {
                    "control_revision": int(session_row["control_revision"]),
                    "project_binding": binding.project_binding,
                    "discovery_generation": session_row["discovery_generation"],
                    "goal_id": goal.id,
                    "intent_revision": intent_revision,
                    "intent_hash": intent_hash,
                }
                if authority != actual_authority:
                    raise PermissionError("Cursor hook delivery authority changed")
                if (
                    session.harness_type != HarnessType.CURSOR
                    or session.supervision_paused
                    or session.status == SessionStatus.DETACHED
                    or goal.paused
                    or receipt["trigger_event_id"]
                    != intervention.metadata.get("trigger_event_id")
                    or receipt["target_session_id"] != intervention.session_id
                    or receipt["vendor_session_id"] != session.vendor_session_id
                    or receipt["target_session_id"]
                    != f"cursor:{receipt['vendor_session_id']}"
                    or intervention.trigger != EventType.STOP.value
                    or intervention.policy_verdict != PolicyVerdict.ALLOW
                    or intervention.action_taken != intervention.proposed_action.type.value
                    or intervention.proposed_action.type
                    not in {
                        InterventionType.SEND_NUDGE,
                        InterventionType.INJECT_CONTEXT,
                        InterventionType.CONTINUE_SESSION,
                        InterventionType.REQUEST_VERIFICATION,
                    }
                    or intervention.result != CURSOR_HOOK_PREPARED_OUTCOME
                    or intervention.outcome != "worker_delivery_uncertain"
                    or intervention.helped is not None
                    or (intervention.metadata or {}).get("effect_state")
                    != "delivery_uncertain"
                    or (intervention.metadata or {}).get("worker_delivery_receipt")
                    is not None
                    or (intervention.metadata or {}).get("hook_preparation_receipt")
                    != receipt
                ):
                    raise PermissionError("Cursor hook preparation is not authoritative")
                action_text = intervention.proposed_action.payload.get("text")
                if (
                    not isinstance(action_text, str)
                    or cursor_message_sha256(action_text.strip())
                    != receipt["message_sha256"]
                ):
                    raise ValueError("Cursor hook preparation message does not match action")

                processing_cursor = await transaction.execute(
                    "SELECT * FROM event_processing WHERE event_id = ?",
                    (receipt["trigger_event_id"],),
                )
                processing_row = await processing_cursor.fetchone()
                effect_cursor = await transaction.execute(
                    "SELECT * FROM event_effects WHERE event_id = ? AND effect_key = 'main'",
                    (receipt["trigger_event_id"],),
                )
                effect_row = await effect_cursor.fetchone()
                event_cursor = await transaction.execute(
                    "SELECT json FROM events WHERE event_id = ? AND session_id = ?",
                    (receipt["trigger_event_id"], receipt["target_session_id"]),
                )
                event_row = await event_cursor.fetchone()
                if processing_row is None or effect_row is None or event_row is None:
                    raise RuntimeError("Cursor hook prepared effect binding is missing")
                processing = _event_processing_record(processing_row)
                effect = _event_effect_record(effect_row)
                trigger_event = HarnessEvent.model_validate_json(event_row["json"])
                expected_effect_result = {
                    "status": "delivery_uncertain",
                    "outcome": CURSOR_HOOK_PREPARED_OUTCOME,
                    "code": CURSOR_HOOK_PREPARED_OUTCOME,
                    "effect_id": effect["effect_id"],
                    "hook_preparation_receipt": receipt,
                }
                processing_receipt = processing.get("receipt")
                if (
                    processing["state"] != "complete"
                    or processing["session_id"] != receipt["target_session_id"]
                    or processing["goal_id"] != goal.id
                    or processing["accepted_project_binding"] != binding.project_binding
                    or processing["accepted_goal_intent_revision"] != intent_revision
                    or processing["accepted_goal_intent_hash"] != intent_hash
                    or effect["state"] != "delivery_uncertain"
                    or effect["target_session_id"] != receipt["target_session_id"]
                    or effect["result"] != expected_effect_result
                    or effect["payload"].get("intervention_id") != intervention.id
                    or effect["payload"].get("action")
                    != intervention.proposed_action.model_dump(mode="json")
                    or not isinstance(processing_receipt, dict)
                    or processing_receipt.get("effect_id") != effect["effect_id"]
                    or processing_receipt.get("effect_state") != "delivery_uncertain"
                    or processing_receipt.get("effect_result") != expected_effect_result
                    or trigger_event.event_type != EventType.STOP
                    or trigger_event.harness_type != HarnessType.CURSOR
                    or trigger_event.session_id != receipt["target_session_id"]
                    or trigger_event.goal_id != goal.id
                ):
                    raise PermissionError("Cursor hook prepared effect binding is invalid")
                trigger_generation_raw = (trigger_event.metadata or {}).get("generation_id")
                trigger_generation = (
                    str(trigger_generation_raw).strip()
                    if isinstance(trigger_generation_raw, str)
                    and trigger_generation_raw.strip()
                    and len(trigger_generation_raw.strip()) <= 512
                    else None
                )

                nonce = secrets.token_hex(32)
                now = utcnow().isoformat()
                record = {
                    "schema": "pex.cursor-hook-preparation-record.v1",
                    "preparation_id": receipt["preparation_id"],
                    "intervention_id": intervention.id,
                    "effect_id": effect["effect_id"],
                    "trigger_event_id": receipt["trigger_event_id"],
                    "trigger_accept_seq": int(processing["accept_seq"]),
                    "target_session_id": receipt["target_session_id"],
                    "vendor_session_id": receipt["vendor_session_id"],
                    "goal_id": goal.id,
                    "project_id": binding.project_id,
                    "project_binding": binding.project_binding,
                    "control_revision": authority["control_revision"],
                    "discovery_generation": authority["discovery_generation"],
                    "goal_intent_revision": authority["intent_revision"],
                    "goal_intent_hash": authority["intent_hash"],
                    "message_sha256": receipt["message_sha256"],
                    "nonce_sha256": cursor_nonce_sha256(nonce),
                    "process_boot_id": self.process_boot_id,
                    "trigger_generation": trigger_generation,
                    "prepared_at": now,
                }
                await transaction.execute(
                    "INSERT INTO cursor_hook_preparations("
                    "preparation_id, intervention_id, effect_id, trigger_event_id, "
                    "trigger_accept_seq, target_session_id, vendor_session_id, goal_id, "
                    "project_id, project_binding, control_revision, discovery_generation, "
                    "goal_intent_revision, goal_intent_hash, message_sha256, nonce_sha256, "
                    "process_boot_id, trigger_generation, prepared_at, json) VALUES "
                    "(?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)",
                    (
                        record["preparation_id"],
                        record["intervention_id"],
                        record["effect_id"],
                        record["trigger_event_id"],
                        record["trigger_accept_seq"],
                        record["target_session_id"],
                        record["vendor_session_id"],
                        record["goal_id"],
                        record["project_id"],
                        record["project_binding"],
                        record["control_revision"],
                        record["discovery_generation"],
                        record["goal_intent_revision"],
                        record["goal_intent_hash"],
                        record["message_sha256"],
                        record["nonce_sha256"],
                        record["process_boot_id"],
                        record["trigger_generation"],
                        record["prepared_at"],
                        _canonical_json(record),
                    ),
                )
                packet = {
                    "schema": "pex.cursor-hook-delivery.v1",
                    "preparation_id": receipt["preparation_id"],
                    "intervention_id": intervention.id,
                    "trigger_event_id": receipt["trigger_event_id"],
                    "target_session_id": receipt["target_session_id"],
                    "vendor_session_id": receipt["vendor_session_id"],
                    "goal_id": goal.id,
                    "message_sha256": receipt["message_sha256"],
                    "nonce": nonce,
                }
                validate_cursor_hook_delivery_packet(packet)
                await transaction.commit()
            except Exception:
                await transaction.rollback()
                raise
        return packet

    async def record_cursor_hook_flush(
        self,
        packet: dict[str, Any],
        *,
        project_id: str,
    ) -> dict[str, Any]:
        """Append an authenticated stdout-flush fact without upgrading delivery."""

        validated = validate_cursor_hook_delivery_packet(packet)
        if (
            not isinstance(project_id, str)
            or not project_id
            or len(project_id) > MAX_PROJECT_ID_LENGTH
            or "\x00" in project_id
        ):
            raise ValueError("Cursor hook project id is invalid")
        audit_written = False
        async with aiosqlite.connect(self.path, timeout=5.0) as transaction:
            await _configure_connection(transaction)
            await transaction.execute("BEGIN IMMEDIATE")
            try:
                preparation_cursor = await transaction.execute(
                    "SELECT * FROM cursor_hook_preparations WHERE preparation_id = ?",
                    (validated["preparation_id"],),
                )
                preparation_row = await preparation_cursor.fetchone()
                if preparation_row is None:
                    raise LookupError("Cursor hook preparation not found")
                preparation = _cursor_hook_preparation_record(preparation_row)
                packet_binding = {
                    "preparation_id": preparation["preparation_id"],
                    "intervention_id": preparation["intervention_id"],
                    "trigger_event_id": preparation["trigger_event_id"],
                    "target_session_id": preparation["target_session_id"],
                    "vendor_session_id": preparation["vendor_session_id"],
                    "goal_id": preparation["goal_id"],
                    "message_sha256": preparation["message_sha256"],
                }
                if any(validated[key] != value for key, value in packet_binding.items()):
                    raise ValueError("Cursor hook delivery packet binding mismatch")
                if not hmac.compare_digest(
                    cursor_nonce_sha256(validated["nonce"]),
                    preparation["nonce_sha256"],
                ):
                    raise PermissionError("Cursor hook delivery nonce mismatch")
                if not _same_project(project_id, preparation["project_id"]):
                    raise PermissionError("Cursor hook project binding changed")

                existing_cursor = await transaction.execute(
                    "SELECT * FROM cursor_hook_flush_receipts WHERE preparation_id = ?",
                    (validated["preparation_id"],),
                )
                existing_row = await existing_cursor.fetchone()
                if existing_row is not None:
                    existing = _cursor_hook_flush_record(existing_row)
                    await transaction.commit()
                    return existing

                now_moment = utcnow()
                try:
                    prepared_at = datetime.fromisoformat(preparation["prepared_at"])
                except (TypeError, ValueError) as exc:  # pragma: no cover - record validator
                    raise RuntimeError("Cursor hook preparation time is invalid") from exc
                elapsed = now_moment - prepared_at
                if (
                    preparation["process_boot_id"] != self.process_boot_id
                    or prepared_at.utcoffset() != timedelta(0)
                    or elapsed < timedelta(0)
                    or elapsed > timedelta(seconds=30)
                ):
                    raise PermissionError("Cursor hook flush acknowledgement expired")
                try:
                    same_project = await _same_live_project_binding(
                        transaction,
                        project_id,
                        preparation["project_id"],
                    )
                    caller_binding = await _project_binding_snapshot(transaction, project_id)
                except (ProjectIdentityBlockedError, RuntimeError, ValueError) as exc:
                    raise PermissionError("Cursor hook project binding changed") from exc
                if (
                    not same_project
                    or not hmac.compare_digest(
                        caller_binding,
                        preparation["project_binding"],
                    )
                ):
                    raise PermissionError("Cursor hook project binding changed")
                watermark_cursor = await transaction.execute(
                    "SELECT MAX(accept_seq) AS watermark FROM event_processing "
                    "WHERE session_id = ?",
                    (preparation["target_session_id"],),
                )
                watermark_row = await watermark_cursor.fetchone()
                watermark = int(watermark_row["watermark"] or 0)
                if watermark != preparation["trigger_accept_seq"]:
                    raise PermissionError("Cursor hook flush acknowledgement is stale")
                now = now_moment.isoformat()
                flush = {
                    "schema": CURSOR_HOOK_FLUSH_SCHEMA,
                    "preparation_id": preparation["preparation_id"],
                    "intervention_id": preparation["intervention_id"],
                    "target_session_id": preparation["target_session_id"],
                    "vendor_session_id": preparation["vendor_session_id"],
                    "message_sha256": preparation["message_sha256"],
                    "target_accept_seq_through": watermark,
                    "delivery_evidence": "hook_stdout_flushed",
                    "vendor_acceptance_proven": False,
                    "flushed_at": now,
                }
                await transaction.execute(
                    "INSERT INTO cursor_hook_flush_receipts("
                    "preparation_id, intervention_id, target_session_id, "
                    "vendor_session_id, message_sha256, target_accept_seq_through, "
                    "flushed_at, json) VALUES (?, ?, ?, ?, ?, ?, ?, ?)",
                    (
                        flush["preparation_id"],
                        flush["intervention_id"],
                        flush["target_session_id"],
                        flush["vendor_session_id"],
                        flush["message_sha256"],
                        flush["target_accept_seq_through"],
                        flush["flushed_at"],
                        _canonical_json(flush),
                    ),
                )
                intervention_cursor = await transaction.execute(
                    "SELECT json FROM interventions WHERE id = ?",
                    (preparation["intervention_id"],),
                )
                intervention_row = await intervention_cursor.fetchone()
                if intervention_row is None:
                    raise RuntimeError("Cursor hook preparation intervention is missing")
                intervention = _stored_intervention(intervention_row["json"])
                if (
                    intervention.result != CURSOR_HOOK_PREPARED_OUTCOME
                    or intervention.outcome != "worker_delivery_uncertain"
                    or intervention.helped is not None
                ):
                    raise RuntimeError("Cursor hook preparation intervention changed")
                metadata = dict(intervention.metadata or {})
                if metadata.get("cursor_hook_delivery") is not None:
                    raise RuntimeError("Cursor hook delivery projection already exists")
                metadata["cursor_hook_delivery"] = {
                    "schema": "pex.cursor-hook-delivery-state.v1",
                    "state": "hook_stdout_flushed",
                    "preparation_id": preparation["preparation_id"],
                    "trigger_event_id": preparation["trigger_event_id"],
                    "target_session_id": preparation["target_session_id"],
                    "vendor_session_id": preparation["vendor_session_id"],
                    "message_sha256": preparation["message_sha256"],
                    "target_accept_seq_through": watermark,
                    "flushed_at": now,
                    "vendor_acceptance_proven": False,
                    "prompt_coverage_complete": False,
                    "causal_continuation_proven": False,
                }
                intervention.metadata = metadata
                intervention.helped = None
                await _update_frozen_bound_intervention(transaction, intervention)
                audit = self._intervention_audit_record(
                    intervention,
                    "cursor_hook_stdout_flushed",
                )
                audit["cursor_hook_delivery"] = metadata["cursor_hook_delivery"]
                await transaction.execute(
                    "INSERT INTO intervention_audit(intervention_id, record_type, json) "
                    "VALUES (?, 'cursor_hook_stdout_flushed', ?)",
                    (intervention.id, _canonical_json(audit)),
                )
                audit_written = True
                await transaction.commit()
            except Exception:
                await transaction.rollback()
                raise
        if audit_written:
            await self._try_sync_intervention_audit()
        return flush

    async def observe_cursor_hook_continuation(
        self,
        event_id: str,
    ) -> dict[str, Any] | None:
        """Append one ordered same-session activity fact after a flushed hook."""

        _validate_store_id(event_id, label="Cursor continuation event id")
        audit_written = False
        result: dict[str, Any] | None = None
        async with aiosqlite.connect(self.path, timeout=5.0) as transaction:
            await _configure_connection(transaction)
            await transaction.execute("BEGIN IMMEDIATE")
            try:
                replay_cursor = await transaction.execute(
                    "SELECT * FROM cursor_hook_continuations WHERE event_id = ?",
                    (event_id,),
                )
                replay_row = await replay_cursor.fetchone()
                if replay_row is not None:
                    result = _cursor_hook_continuation_record(replay_row)
                    await transaction.commit()
                    return result

                event_cursor = await transaction.execute(
                    "SELECT e.json, p.* FROM events AS e JOIN event_processing AS p "
                    "ON p.event_id = e.event_id WHERE e.event_id = ?",
                    (event_id,),
                )
                event_row = await event_cursor.fetchone()
                if event_row is None:
                    await transaction.commit()
                    return None
                event = HarnessEvent.model_validate_json(event_row["json"])
                recognized = {
                    EventType.AGENT_RESPONSE,
                    EventType.FILE_EDIT,
                    EventType.TOOL_RESULT,
                    EventType.ERROR,
                    EventType.STOP,
                }
                observed_generation_raw = (event.metadata or {}).get("generation_id")
                if (
                    event.harness_type != HarnessType.CURSOR
                    or event.event_type not in recognized
                    or not isinstance(observed_generation_raw, str)
                    or not observed_generation_raw.strip()
                    or observed_generation_raw != observed_generation_raw.strip()
                    or len(observed_generation_raw) > 512
                ):
                    await transaction.commit()
                    return None
                observed_generation = observed_generation_raw
                accept_seq = int(event_row["accept_seq"])

                candidates_cursor = await transaction.execute(
                    "SELECT p.*, f.intervention_id AS flush_intervention_id, "
                    "f.target_session_id AS flush_target_session_id, "
                    "f.vendor_session_id AS flush_vendor_session_id, "
                    "f.message_sha256 AS flush_message_sha256, "
                    "f.target_accept_seq_through, f.flushed_at, f.json AS flush_json "
                    "FROM cursor_hook_preparations AS p "
                    "JOIN cursor_hook_flush_receipts AS f USING(preparation_id) "
                    "LEFT JOIN cursor_hook_continuations AS c USING(preparation_id) "
                    "WHERE p.target_session_id = ? AND c.preparation_id IS NULL "
                    "ORDER BY p.trigger_accept_seq DESC LIMIT 102",
                    (event.session_id,),
                )
                candidate_rows = await candidates_cursor.fetchall()
                if len(candidate_rows) > 100:
                    result = {
                        "status": "causality_ambiguous_candidate_bound",
                        "event_id": event_id,
                    }
                    await transaction.commit()
                    return result

                eligible: list[tuple[dict[str, Any], dict[str, Any]]] = []
                prompt_ambiguity = False
                for candidate_row in candidate_rows:
                    preparation = _cursor_hook_preparation_record(candidate_row)
                    flush_row = {
                        "preparation_id": candidate_row["preparation_id"],
                        "intervention_id": candidate_row["flush_intervention_id"],
                        "target_session_id": candidate_row["flush_target_session_id"],
                        "vendor_session_id": candidate_row["flush_vendor_session_id"],
                        "message_sha256": candidate_row["flush_message_sha256"],
                        "target_accept_seq_through": candidate_row[
                            "target_accept_seq_through"
                        ],
                        "flushed_at": candidate_row["flushed_at"],
                        "json": candidate_row["flush_json"],
                    }
                    flush = _cursor_hook_flush_record(flush_row)  # type: ignore[arg-type]
                    if (
                        flush["intervention_id"] != preparation["intervention_id"]
                        or flush["target_session_id"] != preparation["target_session_id"]
                        or flush["vendor_session_id"] != preparation["vendor_session_id"]
                        or flush["message_sha256"] != preparation["message_sha256"]
                        or accept_seq <= flush["target_accept_seq_through"]
                        or preparation["trigger_generation"] is None
                        or observed_generation == preparation["trigger_generation"]
                    ):
                        continue

                    prompt_cursor = await transaction.execute(
                        "SELECT e.json FROM event_processing AS p JOIN events AS e "
                        "ON e.event_id = p.event_id WHERE p.session_id = ? "
                        "AND p.accept_seq > ? AND p.accept_seq < ? "
                        "ORDER BY p.accept_seq LIMIT 1002",
                        (
                            preparation["target_session_id"],
                            preparation["trigger_accept_seq"],
                            accept_seq,
                        ),
                    )
                    intervening_rows = await prompt_cursor.fetchall()
                    if len(intervening_rows) > 1000:
                        prompt_ambiguity = True
                        continue
                    if any(
                        HarnessEvent.model_validate_json(row["json"]).event_type
                        == EventType.USER_PROMPT
                        for row in intervening_rows
                    ):
                        prompt_ambiguity = True
                        continue

                    session_cursor = await transaction.execute(
                        "SELECT * FROM sessions WHERE id = ?",
                        (preparation["target_session_id"],),
                    )
                    session_row = await session_cursor.fetchone()
                    goal_cursor = await transaction.execute(
                        "SELECT * FROM goals WHERE id = ?",
                        (preparation["goal_id"],),
                    )
                    goal_row = await goal_cursor.fetchone()
                    if session_row is None or goal_row is None:
                        continue
                    session = HarnessSession.model_validate_json(session_row["json"])
                    try:
                        goal, goal_binding = await _load_bound_goal(
                            transaction,
                            preparation["goal_id"],
                            require_live=True,
                        )
                        current_project_binding = await _project_binding_snapshot(
                            transaction,
                            preparation["project_id"],
                        )
                        intent_revision, intent_hash = _validate_goal_intent_scalar_pair(
                            goal_row["intent_revision"],
                            goal_row["intent_hash"],
                        )
                    except (LookupError, ProjectIdentityBlockedError, RuntimeError, ValueError):
                        continue
                    accepted_session_raw = event_row["accepted_session_json"]
                    if not isinstance(accepted_session_raw, str):
                        continue
                    accepted_session = HarnessSession.model_validate_json(
                        accepted_session_raw
                    )
                    if (
                        session.id != preparation["target_session_id"]
                        or session.vendor_session_id != preparation["vendor_session_id"]
                        or session.harness_type != HarnessType.CURSOR
                        or session.goal_id != preparation["goal_id"]
                        or session.supervision_paused
                        or session.status == SessionStatus.DETACHED
                        or int(session_row["control_revision"])
                        != preparation["control_revision"]
                        or session_row["project_binding"]
                        != preparation["project_binding"]
                        or session_row["discovery_generation"]
                        != preparation["discovery_generation"]
                        or goal.paused
                        or goal_binding.project_binding != preparation["project_binding"]
                        or current_project_binding != preparation["project_binding"]
                        or intent_revision != preparation["goal_intent_revision"]
                        or intent_hash != preparation["goal_intent_hash"]
                        or event.goal_id != preparation["goal_id"]
                        or event.session_id != preparation["target_session_id"]
                        or event_row["harness_type"] != HarnessType.CURSOR.value
                        or event_row["goal_id"] != preparation["goal_id"]
                        or event_row["accepted_project_binding"]
                        != preparation["project_binding"]
                        or event_row["accepted_goal_intent_revision"]
                        != preparation["goal_intent_revision"]
                        or event_row["accepted_goal_intent_hash"]
                        != preparation["goal_intent_hash"]
                        or accepted_session.id != preparation["target_session_id"]
                        or accepted_session.vendor_session_id
                        != preparation["vendor_session_id"]
                        or accepted_session.goal_id != preparation["goal_id"]
                    ):
                        continue
                    eligible.append((preparation, flush))

                if not eligible:
                    result = (
                        {
                            "status": "causality_ambiguous_intervening_user_prompt",
                            "event_id": event_id,
                        }
                        if prompt_ambiguity
                        else None
                    )
                    await transaction.commit()
                    return result
                if len(eligible) != 1:
                    result = {
                        "status": "causality_ambiguous_multiple_preparations",
                        "event_id": event_id,
                    }
                    await transaction.commit()
                    return result

                preparation, _ = eligible[0]
                now = utcnow().isoformat()
                continuation = {
                    "schema": CURSOR_HOOK_CONTINUATION_SCHEMA,
                    "preparation_id": preparation["preparation_id"],
                    "intervention_id": preparation["intervention_id"],
                    "event_id": event_id,
                    "target_session_id": preparation["target_session_id"],
                    "vendor_session_id": preparation["vendor_session_id"],
                    "accept_seq": accept_seq,
                    "observed_generation": observed_generation,
                    "observation": "same_session_activity_observed",
                    "vendor_acceptance_proven": False,
                    "observed_at": now,
                }
                await transaction.execute(
                    "INSERT INTO cursor_hook_continuations("
                    "preparation_id, intervention_id, event_id, target_session_id, "
                    "vendor_session_id, accept_seq, observed_generation, observed_at, json) "
                    "VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)",
                    (
                        continuation["preparation_id"],
                        continuation["intervention_id"],
                        continuation["event_id"],
                        continuation["target_session_id"],
                        continuation["vendor_session_id"],
                        continuation["accept_seq"],
                        continuation["observed_generation"],
                        continuation["observed_at"],
                        _canonical_json(continuation),
                    ),
                )
                intervention_cursor = await transaction.execute(
                    "SELECT json FROM interventions WHERE id = ?",
                    (preparation["intervention_id"],),
                )
                intervention_row = await intervention_cursor.fetchone()
                if intervention_row is None:
                    raise RuntimeError("Cursor continuation intervention is missing")
                intervention = _stored_intervention(intervention_row["json"])
                delivery = dict((intervention.metadata or {}).get("cursor_hook_delivery") or {})
                if (
                    intervention.result != CURSOR_HOOK_PREPARED_OUTCOME
                    or intervention.helped is not None
                    or delivery.get("state") != "hook_stdout_flushed"
                    or delivery.get("preparation_id") != preparation["preparation_id"]
                ):
                    raise RuntimeError("Cursor continuation projection is invalid")
                delivery.update(
                    {
                        "state": "same_session_activity_observed",
                        "continuation_event_id": event_id,
                        "continuation_accept_seq": accept_seq,
                        "observed_generation": observed_generation,
                        "vendor_acceptance_proven": False,
                        "prompt_coverage_complete": False,
                        "causal_continuation_proven": False,
                    }
                )
                intervention.metadata = {
                    **(intervention.metadata or {}),
                    "cursor_hook_delivery": delivery,
                }
                intervention.outcome = "same_session_activity_observed"
                intervention.helped = None
                await _update_frozen_bound_intervention(transaction, intervention)
                audit = self._intervention_audit_record(
                    intervention,
                    "cursor_same_session_activity_observed",
                )
                audit["cursor_hook_delivery"] = delivery
                await transaction.execute(
                    "INSERT INTO intervention_audit(intervention_id, record_type, json) "
                    "VALUES (?, 'cursor_same_session_activity_observed', ?)",
                    (intervention.id, _canonical_json(audit)),
                )
                audit_written = True
                result = continuation
                await transaction.commit()
            except Exception:
                await transaction.rollback()
                raise
        if audit_written:
            await self._try_sync_intervention_audit()
        return result

    async def update_intervention(
        self,
        intervention: Intervention,
        *,
        record_type: str = "outcome_observed",
    ) -> None:
        await self._write_intervention(intervention, record_type, create=False)

    async def _write_intervention(
        self,
        intervention: Intervention,
        record_type: str,
        *,
        create: bool,
    ) -> None:
        """Commit the current intervention and immutable audit revision together."""
        async with self._write_lock:
            try:
                await self.db.execute("BEGIN IMMEDIATE")
                cur = await self.db.execute(
                    "SELECT id FROM interventions WHERE id = ?",
                    (intervention.id,),
                )
                row = await cur.fetchone()
                if create:
                    if row is not None:
                        raise ValueError("intervention id already exists")
                    await _insert_bound_intervention(self.db, intervention)
                else:
                    if row is None:
                        raise LookupError("intervention not found")
                    await _update_bound_intervention(self.db, intervention)
                audit_json = json.dumps(
                    self._intervention_audit_record(intervention, record_type),
                    ensure_ascii=False,
                    separators=(",", ":"),
                )
                await self.db.execute(
                    "INSERT INTO intervention_audit(intervention_id, record_type, json) "
                    "VALUES (?, ?, ?)",
                    (intervention.id, record_type, audit_json),
                )
                await self.db.commit()
            except Exception:
                await self.db.rollback()
                raise
        await self._try_sync_intervention_audit()

    def _intervention_audit_record(
        self,
        intervention: Intervention,
        record_type: str,
    ) -> dict[str, Any]:
        metadata = intervention.metadata or {}
        action = intervention.proposed_action
        record = {
            "record_type": record_type,
            "intervention_id": intervention.id,
            "session_id": intervention.session_id,
            "goal_id": intervention.goal_id,
            "trigger_event": intervention.trigger,
            "claims": metadata.get("claims") or [],
            "evidence": action.evidence,
            "supervisor_model": metadata.get("model_name"),
            "inference_request_id": metadata.get("inference_request_id"),
            "local_invocation_id": metadata.get("local_invocation_id"),
            "inference_status": metadata.get("inference_status"),
            "model_call_count": metadata.get("model_call_count"),
            "diagnosis": intervention.diagnosis,
            "decision": action.type.value,
            "action": intervention.action_taken,
            "action_payload": intervention_audit_action_payload(intervention),
            "action_rationale": action.rationale,
            "confidence": action.confidence,
            "risk": action.risk.value,
            "reversible": action.reversible,
            "authority_required": action.authority_required.value,
            "expected_benefit": action.expected_benefit,
            "cooldown_seconds": action.cooldown_seconds,
            "policy_verdict": intervention.policy_verdict.value,
            "delivery_result": intervention.result,
            "worker_response": intervention.worker_response,
            "outcome": intervention.outcome,
            "helped": intervention.helped,
            "backend": metadata.get("backend"),
            "runtime": metadata.get("runtime"),
            "runtime_version": metadata.get("runtime_version"),
            "model_class": metadata.get("model_class"),
            "provider": metadata.get("provider"),
            "base_url": metadata.get("base_url"),
            "auth_mode": metadata.get("auth_mode"),
            "execution_mode": metadata.get("execution_mode"),
            "transport": metadata.get("transport"),
            "transport_invocation_id": metadata.get("transport_invocation_id"),
            "transport_request_id": metadata.get("transport_request_id"),
            "transport_status": metadata.get("transport_status"),
            "evidence_tools": metadata.get("evidence_tools") or [],
            "evidence_refs": metadata.get("evidence_refs") or [],
            "evidence_observations": metadata.get("evidence_observations") or [],
            "independent_verifier": metadata.get("independent_verifier"),
            "supervisor_context_reference": metadata.get("supervisor_context_reference"),
            "causal_continuation_proven": metadata.get("causal_continuation_proven"),
            "traces": metadata.get("traces") or [],
            "trigger_event_id": metadata.get("trigger_event_id"),
            "observed_event_refs": metadata.get("outcome_event_ids") or [],
            "worker_delivery_receipt": metadata.get("worker_delivery_receipt"),
            "hook_preparation_receipt": metadata.get("hook_preparation_receipt"),
            "cursor_hook_delivery": metadata.get("cursor_hook_delivery"),
            "permission_request_id": metadata.get("permission_request_id"),
            "permission_resolution": metadata.get("permission_resolution"),
            "lifecycle_resolution": metadata.get("lifecycle_resolution"),
            "human_decision_resolution": metadata.get("human_decision_resolution"),
            "mcp_principal_id": metadata.get("mcp_principal_id"),
            "mcp_mutation_id": metadata.get("mcp_mutation_id"),
            "created_at": intervention.created_at.isoformat(),
            "recorded_at": utcnow().isoformat(),
        }
        cleaned, _ = redact_mapping(record)
        if not isinstance(cleaned, dict):  # pragma: no cover - type invariant
            raise RuntimeError("intervention audit redaction returned a non-object")
        return cleaned

    async def _try_sync_intervention_audit(self) -> None:
        """Project durable audit rows without lying that a file error undid the action."""

        try:
            await self._sync_intervention_audit()
        except Exception as exc:  # pragma: no cover - platform/filesystem dependent
            logger.error(
                "Intervention audit projection is pending (%s)",
                type(exc).__name__,
            )

    async def _sync_intervention_audit(self) -> None:
        """Append every durable audit row missing from the human-readable JSONL.

        SQLite is the canonical, transactional ledger. The JSONL is an append-only
        projection with stable ``audit_id`` values. On restart, IDs already present
        in the projection are detected, so a crash after fsync but before returning
        cannot duplicate a revision and a failed projection cannot lose it.
        """

        async with self._audit_flush_lock:
            cur = await self.db.execute("SELECT id, json FROM intervention_audit ORDER BY id")
            rows = [(int(row["id"]), str(row["json"])) for row in await cur.fetchall()]
            await asyncio.to_thread(self._append_missing_audit_rows, rows)

    def _append_missing_audit_rows(self, rows: list[tuple[int, str]]) -> None:
        self.audit_path.parent.mkdir(parents=True, exist_ok=True)
        with _AUDIT_APPEND_LOCK:
            # Rescan while holding the process-wide file lock. Per-Store caches
            # become stale when two bridge objects share a database/path, and an
            # audit_id alone must not let a tampered JSONL row suppress the real
            # durable SQLite revision.
            projected: set[tuple[int, str]] = set()
            if self.audit_path.exists():
                with self.audit_path.open("r", encoding="utf-8", errors="replace") as existing:
                    for line in existing:
                        try:
                            value = _strict_json_loads(line)
                        except (TypeError, ValueError):
                            continue
                        audit_id = value.get("audit_id") if isinstance(value, dict) else None
                        if not isinstance(audit_id, int) or audit_id <= 0:
                            continue
                        projected.add((audit_id, _audit_projection_payload(value)))
            missing: list[tuple[int, str]] = []
            for audit_id, raw in rows:
                value = json.loads(raw)
                if not isinstance(value, dict):  # pragma: no cover - DB invariant
                    raise RuntimeError("stored intervention audit is not an object")
                if (audit_id, _audit_projection_payload(value)) not in projected:
                    missing.append((audit_id, raw))
            if not missing:
                return

            needs_separator = False
            if self.audit_path.exists() and self.audit_path.stat().st_size:
                with self.audit_path.open("rb") as existing_bytes:
                    existing_bytes.seek(-1, os.SEEK_END)
                    needs_separator = existing_bytes.read(1) != b"\n"

            with self.audit_path.open("ab") as handle:
                if needs_separator:
                    # Preserve a partial legacy tail rather than truncating an
                    # append-only artifact, then resume with valid JSONL records.
                    handle.write(b"\n")
                for audit_id, raw in missing:
                    value = json.loads(raw)
                    if not isinstance(value, dict):  # pragma: no cover - DB invariant
                        raise RuntimeError("stored intervention audit is not an object")
                    value["audit_id"] = audit_id
                    handle.write(
                        (
                            json.dumps(
                                value,
                                ensure_ascii=False,
                                separators=(",", ":"),
                            )
                            + "\n"
                        ).encode("utf-8")
                    )
                handle.flush()
                os.fsync(handle.fileno())

    async def list_interventions(
        self,
        session_id: str | None = None,
        *,
        limit: int = MAX_LIST_QUERY_LIMIT,
        offset: int = 0,
    ) -> list[Intervention]:
        if not 1 <= limit <= MAX_LIST_QUERY_LIMIT:
            raise ValueError(
                f"intervention limit must be positive and no greater than {MAX_LIST_QUERY_LIMIT}"
            )
        if offset < 0:
            raise ValueError("intervention offset cannot be negative")
        parameters: list[Any] = []
        if session_id:
            query = (
                "SELECT json FROM interventions WHERE session_id = ? ORDER BY ts DESC, rowid DESC"
            )
            parameters.append(session_id)
        else:
            query = "SELECT json FROM interventions ORDER BY ts DESC, rowid DESC"
        query += " LIMIT ? OFFSET ?"
        parameters.extend((limit, offset))
        cur = await self.db.execute(query, tuple(parameters))
        rows = await cur.fetchall()
        return [_stored_intervention(r["json"]) for r in rows]

    async def attention_metrics(self) -> dict[str, Any]:
        """Return one exact, unbounded snapshot of durable attention evidence.

        Product attention totals must not be derived from a paginated intervention
        feed.  This read transaction freezes every source ledger and its watermark at
        one point in time.  The existing ledgers cover several important human action
        classes, including authenticated pause/resume from the receipt migration
        boundary, but not all human actions. The canonical human-intervention total
        therefore stays null while the observed lower bound is exposed explicitly.
        """

        async with aiosqlite.connect(self.path, timeout=5.0) as transaction:
            await _configure_connection(transaction)
            await transaction.execute("BEGIN")
            try:
                captured_at = utcnow().isoformat()
                human_resolution_cursor = await transaction.execute(
                    "SELECT * FROM human_decision_resolutions ORDER BY intervention_id"
                )
                for human_resolution_row in await human_resolution_cursor.fetchall():
                    loaded = await _load_validated_human_decision_resolution(
                        transaction,
                        str(human_resolution_row["intervention_id"]),
                    )
                    if loaded is None:  # pragma: no cover - same transaction invariant
                        raise RuntimeError("human decision resolution disappeared")

                async def scalar(query: str, parameters: tuple[Any, ...] = ()) -> int:
                    cursor = await transaction.execute(query, parameters)
                    row = await cursor.fetchone()
                    if row is None:
                        return 0
                    value = row[0]
                    return int(value or 0)

                request_count = await scalar(
                    "SELECT COUNT(*) FROM interventions WHERE "
                    "COALESCE(json_extract(json, '$.payload.policy_verdict'), "
                    "json_extract(json, '$.policy_verdict')) = 'ask_human' AND "
                    "project_binding IS NOT NULL"
                )
                resolved_decisions = await scalar(
                    "SELECT COUNT(*) FROM ("
                    "SELECT intervention_id FROM permission_resolutions WHERE "
                    "project_binding IS NOT NULL UNION "
                    "SELECT intervention_id FROM lifecycle_resolutions WHERE "
                    "project_binding IS NOT NULL UNION "
                    "SELECT intervention_id FROM human_decision_resolutions WHERE "
                    "json_extract(json, '$.project_binding') IS NOT NULL)"
                )
                pending_decisions = await scalar(
                    "SELECT COUNT(*) FROM interventions AS i WHERE "
                    "COALESCE(json_extract(i.json, '$.payload.policy_verdict'), "
                    "json_extract(i.json, '$.policy_verdict')) = 'ask_human' AND "
                    "i.project_binding IS NOT NULL AND "
                    "NOT EXISTS (SELECT 1 FROM permission_resolutions AS p "
                    "WHERE p.intervention_id = i.id) AND "
                    "NOT EXISTS (SELECT 1 FROM lifecycle_resolutions AS l "
                    "WHERE l.intervention_id = i.id) AND "
                    "NOT EXISTS (SELECT 1 FROM human_decision_resolutions AS h "
                    "WHERE h.intervention_id = i.id)"
                )
                uncertain_decisions = await scalar(
                    "SELECT COUNT(*) FROM ("
                    "SELECT intervention_id FROM permission_resolutions "
                    "WHERE status = 'delivery_uncertain' AND "
                    "project_binding IS NOT NULL UNION "
                    "SELECT intervention_id FROM lifecycle_resolutions "
                    "WHERE status = 'delivery_uncertain' AND "
                    "project_binding IS NOT NULL UNION "
                    "SELECT intervention_id FROM human_decision_resolutions "
                    "WHERE json_extract(json, '$.status') = 'delivery_uncertain' AND "
                    "json_extract(json, '$.project_binding') IS NOT NULL)"
                )

                control_coverage_cursor = await transaction.execute(
                    "SELECT action_kind, actor_assurance FROM "
                    "human_session_control_coverage"
                )
                control_coverage = {
                    str(row["action_kind"]): str(row["actor_assurance"])
                    for row in await control_coverage_cursor.fetchall()
                }
                if control_coverage != {
                    "pause_supervision": "bridge_bearer",
                    "resume_supervision": "bridge_bearer",
                }:
                    raise RuntimeError("human action coverage boundary is incomplete")
                control_action_cursor = await transaction.execute(
                    "SELECT r.id, r.action_kind, r.principal_id, r.actor_assurance, "
                    "r.session_id, r.goal_id, r.project_id, r.project_binding, "
                    "r.before_control_revision, r.after_control_revision, "
                    "r.occurred_at, r.json, s.control_revision AS session_control_revision "
                    "FROM human_session_control_actions AS r "
                    "JOIN sessions AS s ON s.id = r.session_id ORDER BY r.rowid"
                )
                for row in await control_action_cursor.fetchall():
                    try:
                        record = json.loads(str(row["json"]))
                    except (TypeError, ValueError) as exc:
                        raise RuntimeError("human action receipt is corrupt") from exc
                    before_hash = record.get("before_session_sha256")
                    after_hash = record.get("after_session_sha256")
                    before_paused = record.get("before_supervision_paused")
                    after_paused = record.get("after_supervision_paused")
                    try:
                        occurred_at = datetime.fromisoformat(str(row["occurred_at"]))
                    except (TypeError, ValueError) as exc:
                        raise RuntimeError("human action receipt is corrupt") from exc
                    expected = {
                        "schema": "pex.human-action-receipt.v1",
                        "id": str(row["id"]),
                        "action_kind": str(row["action_kind"]),
                        "principal_id": str(row["principal_id"]),
                        "actor_assurance": str(row["actor_assurance"]),
                        "session_id": str(row["session_id"]),
                        "goal_id": row["goal_id"],
                        "project_id": row["project_id"],
                        "project_binding": row["project_binding"],
                        "before_control_revision": int(row["before_control_revision"]),
                        "after_control_revision": int(row["after_control_revision"]),
                        "before_supervision_paused": before_paused,
                        "after_supervision_paused": after_paused,
                        "before_session_sha256": before_hash,
                        "after_session_sha256": after_hash,
                        "occurred_at": str(row["occurred_at"]),
                    }
                    receipt_key = _canonical_json(
                        {
                            "action_kind": expected["action_kind"],
                            "after_control_revision": expected[
                                "after_control_revision"
                            ],
                            "principal_id": expected["principal_id"],
                            "session_id": expected["session_id"],
                        }
                    )
                    expected_id = (
                        "human_action_"
                        + hashlib.sha256(receipt_key.encode("utf-8")).hexdigest()[:40]
                    )
                    if (
                        record != expected
                        or expected["action_kind"] not in control_coverage
                        or expected["actor_assurance"]
                        != control_coverage[expected["action_kind"]]
                        or expected["principal_id"] != "local_bridge_operator"
                        or expected["after_control_revision"]
                        != expected["before_control_revision"] + 1
                        or expected["after_control_revision"]
                        > int(row["session_control_revision"])
                        or not isinstance(before_paused, bool)
                        or not isinstance(after_paused, bool)
                        or before_paused == after_paused
                        or (
                            expected["action_kind"] == "pause_supervision"
                            and (before_paused is not False or after_paused is not True)
                        )
                        or (
                            expected["action_kind"] == "resume_supervision"
                            and (before_paused is not True or after_paused is not False)
                        )
                        or expected["id"] != expected_id
                        or not isinstance(before_hash, str)
                        or _SHA256_PATTERN.fullmatch(before_hash) is None
                        or not isinstance(after_hash, str)
                        or _SHA256_PATTERN.fullmatch(after_hash) is None
                        or before_hash == after_hash
                        or occurred_at.tzinfo is None
                        or occurred_at.utcoffset() != timedelta(0)
                    ):
                        raise RuntimeError("human action receipt is corrupt")

                goal_marker_cursor = await transaction.execute(
                    "SELECT * FROM goal_control_attention_migration_state WHERE singleton = 1"
                )
                goal_marker_row = await goal_marker_cursor.fetchone()
                if goal_marker_row is None:
                    raise RuntimeError("goal control attention migration marker is missing")
                goal_marker = _goal_control_attention_migration_record(goal_marker_row)
                goal_legacy_cursor = await transaction.execute(
                    "SELECT l.*, o.action_kind AS operation_action_kind, "
                    "o.request_hash AS operation_request_hash "
                    "FROM goal_control_attention_legacy_operations AS l JOIN "
                    "goal_control_operations AS o USING (operation_id) ORDER BY l.operation_id"
                )
                goal_legacy_rows = await goal_legacy_cursor.fetchall()
                goal_legacy_ids = [str(row["operation_id"]) for row in goal_legacy_rows]
                if (
                    len(goal_legacy_rows) != goal_marker["legacy_operation_count"]
                    or hashlib.sha256(
                        _canonical_json(goal_legacy_ids).encode("utf-8")
                    ).hexdigest()
                    != goal_marker["legacy_operation_set_hash"]
                ):
                    raise RuntimeError("goal control attention legacy snapshot is corrupt")
                for row in goal_legacy_rows:
                    expected = {
                        "schema": "pex.goal-control-attention-legacy-operation.v1",
                        "operation_id": str(row["operation_id"]),
                        "action_kind": str(row["action_kind"]),
                        "request_hash": str(row["request_hash"]),
                        "captured_at": str(row["captured_at"]),
                        "schema_version": 1,
                    }
                    if (
                        row["operation_action_kind"] != row["action_kind"]
                        or row["operation_request_hash"] != row["request_hash"]
                        or row["captured_at"] != goal_marker["initialized_at"]
                        or row["schema_version"] != 1
                        or str(row["json"]) != _canonical_json(expected)
                    ):
                        raise RuntimeError("goal control attention legacy snapshot is corrupt")
                goal_legacy_id_set = set(goal_legacy_ids)
                goal_coverage_cursor = await transaction.execute(
                    "SELECT * FROM goal_control_attention_coverage ORDER BY action_kind"
                )
                goal_coverage_rows = await goal_coverage_cursor.fetchall()
                goal_coverage = {
                    str(row["action_kind"]): str(row["actor_assurance"])
                    for row in goal_coverage_rows
                }
                if goal_coverage != {
                    action_kind: OPERATOR_ACTOR_ASSURANCE
                    for action_kind in GOAL_CONTROL_ATTENTION_ACTIONS
                }:
                    raise RuntimeError("goal control attention coverage is incomplete")
                for row in goal_coverage_rows:
                    expected = {
                        "schema": "pex.human-action-coverage.v1",
                        "action_kind": str(row["action_kind"]),
                        "coverage_started_at": goal_marker["initialized_at"],
                        "actor_assurance": OPERATOR_ACTOR_ASSURANCE,
                        "schema_version": 1,
                    }
                    if (
                        row["coverage_started_at"] != goal_marker["initialized_at"]
                        or row["schema_version"] != 1
                        or str(row["json"]) != _canonical_json(expected)
                    ):
                        raise RuntimeError("goal control attention coverage is corrupt")

                goal_operation_cursor = await transaction.execute(
                    "SELECT * FROM goal_control_operations ORDER BY operation_id"
                )
                goal_attention_count = 0
                goal_attention_legacy_unverified = 0
                validated_goal_receipt_ids: set[str] = set()
                for operation_row in await goal_operation_cursor.fetchall():
                    operation = _goal_control_operation_record(operation_row)
                    if operation["action_kind"] not in GOAL_CONTROL_ATTENTION_ACTIONS:
                        continue
                    if operation["operation_id"] in goal_legacy_id_set:
                        if operation["changed"]:
                            goal_attention_legacy_unverified += 1
                        continue
                    receipt_cursor = await transaction.execute(
                        "SELECT * FROM goal_control_attention_receipts WHERE operation_id = ?",
                        (operation["operation_id"],),
                    )
                    receipt_row = await receipt_cursor.fetchone()
                    if receipt_row is None:
                        raise RuntimeError("goal control attention receipt is missing")
                    receipt = _goal_control_attention_receipt_record(
                        receipt_row,
                        operation,
                    )
                    validated_goal_receipt_ids.add(receipt["id"])
                    goal_attention_count += int(receipt["eligible"])
                all_goal_receipts_cursor = await transaction.execute(
                    "SELECT id FROM goal_control_attention_receipts ORDER BY rowid"
                )
                all_goal_receipt_ids = {
                    str(row["id"]) for row in await all_goal_receipts_cursor.fetchall()
                }
                if all_goal_receipt_ids != validated_goal_receipt_ids:
                    raise RuntimeError("goal control attention receipt boundary is corrupt")

                operator_actor_cursor = await transaction.execute(
                    "SELECT oe.* FROM operator_effects AS oe WHERE "
                    "json_extract(oe.payload_json, '$.schema') = ? OR EXISTS ("
                    "SELECT 1 FROM human_operator_action_reservations AS a "
                    "WHERE a.effect_id = oe.effect_id) OR EXISTS ("
                    "SELECT 1 FROM human_operator_terminal_actions AS r "
                    "WHERE r.effect_id = oe.effect_id) ORDER BY oe.rowid",
                    (OPERATOR_ACTOR_PAYLOAD_SCHEMA,),
                )
                for row in await operator_actor_cursor.fetchall():
                    effect = _operator_effect_record(row)
                    if effect["action_kind"] == OPERATOR_HANDOFF_ACTION:
                        payload = effect["payload"]
                        await self._validate_operator_handoff_effect(
                            transaction,
                            effect,
                            principal_id=str(effect["principal_id"]),
                            idempotency_key=str(effect["idempotency_key"]),
                            source_session_id=str(effect["source_session_id"]),
                            target_session_id=str(effect["target_session_id"]),
                            token_budget=int(payload.get("token_budget")),
                        )
                    await _validate_human_operator_action_receipt(transaction, effect)

                source_queries = {
                    "human_decision_delivery": (
                        "SELECT COUNT(*) FROM human_decision_resolutions WHERE "
                        "json_extract(json, '$.source') = 'human' AND "
                        "json_extract(json, '$.project_binding') IS NOT NULL AND "
                        "json_extract(json, '$.status') = 'delivered'"
                    ),
                    "permission_delivery": (
                        "SELECT COUNT(*) FROM permission_resolutions WHERE status = 'delivered' "
                        "AND project_binding IS NOT NULL "
                        "AND json_extract(json, '$.source') = 'human'"
                    ),
                    "lifecycle_delivery": (
                        "SELECT COUNT(*) FROM lifecycle_resolutions WHERE "
                        "status IN ('delivered', 'denied') "
                        "AND project_binding IS NOT NULL "
                        "AND json_extract(json, '$.source') = 'human'"
                    ),
                    "overlay_reversal": (
                        "SELECT COUNT(*) FROM overlay_operations WHERE kind = 'revert' AND "
                        "project_binding IS NOT NULL AND "
                        "authorized_by = 'local_bridge_operator' AND state = 'delivered'"
                    ),
                    "cleanup_restore": (
                        "SELECT COUNT(*) FROM lifecycle_restore_operations WHERE "
                        "project_binding IS NOT NULL AND "
                        "authorized_by = 'local_bridge_operator' AND state = 'completed'"
                    ),
                    "project_identity_resolution": (
                        "SELECT COUNT(*) FROM project_identity_resolutions WHERE "
                        "json_extract(json, '$.resolved_by') = 'local_bridge_operator'"
                    ),
                    "supervision_control": (
                        "SELECT COUNT(*) FROM human_session_control_actions AS r JOIN "
                        "human_session_control_coverage AS c USING (action_kind) WHERE "
                        "r.project_binding IS NOT NULL AND "
                        "r.principal_id = 'local_bridge_operator' AND "
                        "r.actor_assurance = 'bridge_bearer' AND "
                        "r.actor_assurance = c.actor_assurance AND "
                        "json_valid(r.json) AND json_extract(r.json, '$.id') = r.id AND "
                        "json_extract(r.json, '$.action_kind') = r.action_kind AND "
                        "json_extract(r.json, '$.principal_id') = r.principal_id AND "
                        "json_extract(r.json, '$.actor_assurance') = r.actor_assurance AND "
                        "json_extract(r.json, '$.session_id') = r.session_id AND "
                        "json_extract(r.json, '$.before_control_revision') = "
                        "r.before_control_revision AND "
                        "json_extract(r.json, '$.after_control_revision') = "
                        "r.after_control_revision AND "
                        "json_extract(r.json, '$.occurred_at') = r.occurred_at"
                    ),
                    "direct_operator_message": (
                        "SELECT COUNT(*) FROM human_operator_terminal_actions AS r "
                        "JOIN operator_effects AS oe ON oe.effect_id = r.effect_id "
                        "JOIN human_operator_action_coverage AS c "
                        "ON c.action_kind = r.action_kind WHERE "
                        "r.action_kind = 'session_message' AND oe.state = 'delivered' AND "
                        "r.actor_assurance = 'bridge_bearer' AND "
                        "r.actor_assurance = c.actor_assurance"
                    ),
                    "operator_context_handoff": (
                        "SELECT COUNT(*) FROM human_operator_terminal_actions AS r "
                        "JOIN operator_effects AS oe ON oe.effect_id = r.effect_id "
                        "JOIN human_operator_action_coverage AS c "
                        "ON c.action_kind = r.action_kind WHERE "
                        "r.action_kind = 'context_handoff' AND oe.state = 'delivered' AND "
                        "r.actor_assurance = 'bridge_bearer' AND "
                        "r.actor_assurance = c.actor_assurance"
                    ),
                }
                source_counts = {
                    name: await scalar(query) for name, query in source_queries.items()
                }
                source_counts["goal_control_attention"] = goal_attention_count
                observed_human_actions = sum(source_counts.values())
                unverified_operator_actions = {
                    "operator_message": await scalar(
                        "SELECT COUNT(*) FROM operator_effects WHERE "
                        "principal_id = 'local_bridge_operator' AND "
                        "action_kind = 'session_message' AND state = 'delivered' AND "
                        "NOT EXISTS (SELECT 1 FROM human_operator_terminal_actions AS r "
                        "WHERE r.effect_id = operator_effects.effect_id)"
                    ),
                    "operator_handoff": await scalar(
                        "SELECT COUNT(*) FROM operator_effects WHERE "
                        "principal_id = 'local_bridge_operator' AND "
                        "action_kind = 'context_handoff' AND state = 'delivered' AND "
                        "NOT EXISTS (SELECT 1 FROM human_operator_terminal_actions AS r "
                        "WHERE r.effect_id = operator_effects.effect_id)"
                    ),
                }
                actor_assured_operator_outcomes = {
                    state: await scalar(
                        "SELECT COUNT(*) FROM human_operator_action_reservations AS r "
                        "JOIN operator_effects AS oe ON oe.effect_id = r.effect_id WHERE "
                        "r.action_kind = 'session_message' AND oe.state = ?",
                        (state,),
                    )
                    for state in (
                        "delivered",
                        "failed",
                        "skipped",
                        "delivery_uncertain",
                    )
                }
                actor_assured_handoff_outcomes = {
                    state: await scalar(
                        "SELECT COUNT(*) FROM human_operator_action_reservations AS r "
                        "JOIN operator_effects AS oe ON oe.effect_id = r.effect_id WHERE "
                        "r.action_kind = 'context_handoff' AND oe.state = ?",
                        (state,),
                    )
                    for state in (
                        "delivered",
                        "failed",
                        "skipped",
                        "delivery_uncertain",
                    )
                }

                overlay_reversal_attempts = await scalar(
                    "SELECT COUNT(*) FROM overlay_operations WHERE kind = 'revert' AND "
                    "project_binding IS NOT NULL AND "
                    "authorized_by = 'local_bridge_operator'"
                )
                cleanup_restore_attempts = await scalar(
                    "SELECT COUNT(*) FROM lifecycle_restore_operations WHERE "
                    "project_binding IS NOT NULL AND "
                    "authorized_by = 'local_bridge_operator'"
                )
                reversal_completed = (
                    source_counts["overlay_reversal"] + source_counts["cleanup_restore"]
                )
                reversal_uncertain = await scalar(
                    "SELECT COUNT(*) FROM overlay_operations WHERE kind = 'revert' AND "
                    "project_binding IS NOT NULL AND "
                    "authorized_by = 'local_bridge_operator' AND "
                    "state = 'delivery_uncertain'"
                ) + await scalar(
                    "SELECT COUNT(*) FROM lifecycle_restore_operations WHERE "
                    "project_binding IS NOT NULL AND "
                    "authorized_by = 'local_bridge_operator' AND "
                    "state = 'delivery_uncertain'"
                )
                reversal_attempts = overlay_reversal_attempts + cleanup_restore_attempts
                reversal_failed = max(
                    0,
                    reversal_attempts - reversal_completed - reversal_uncertain,
                )

                coverage_cursor = await transaction.execute(
                    "SELECT MIN(value) FROM ("
                    "SELECT MIN(ts) AS value FROM interventions UNION ALL "
                    "SELECT MIN(resolved_at) FROM human_decision_resolutions UNION ALL "
                    "SELECT MIN(reserved_at) FROM operator_effects UNION ALL "
                    "SELECT MIN(reserved_at) FROM overlay_operations UNION ALL "
                    "SELECT MIN(resolved_at) FROM project_identity_resolutions UNION ALL "
                    "SELECT MIN(occurred_at) FROM human_session_control_actions UNION ALL "
                    "SELECT MIN(coverage_started_at) FROM human_session_control_coverage "
                    "UNION ALL SELECT MIN(reserved_at) FROM "
                    "human_operator_action_reservations "
                    "UNION ALL SELECT MIN(finished_at) FROM "
                    "human_operator_terminal_actions UNION ALL "
                    "SELECT MIN(coverage_started_at) FROM "
                    "human_operator_action_coverage UNION ALL "
                    "SELECT MIN(coverage_started_at) FROM "
                    "goal_control_attention_coverage)"
                )
                coverage_row = await coverage_cursor.fetchone()
                coverage_started_at = coverage_row[0] if coverage_row else None
                action_coverage_cursor = await transaction.execute(
                    "SELECT action_kind, coverage_started_at, actor_assurance, "
                    "schema_version, json FROM human_session_control_coverage UNION ALL "
                    "SELECT action_kind, coverage_started_at, actor_assurance, "
                    "schema_version, json FROM human_operator_action_coverage UNION ALL "
                    "SELECT action_kind, coverage_started_at, actor_assurance, "
                    "schema_version, json FROM goal_control_attention_coverage "
                    "ORDER BY action_kind"
                )
                action_coverage: list[dict[str, Any]] = []
                for row in await action_coverage_cursor.fetchall():
                    record = json.loads(str(row["json"]))
                    expected = {
                        "schema": "pex.human-action-coverage.v1",
                        "action_kind": str(row["action_kind"]),
                        "coverage_started_at": str(row["coverage_started_at"]),
                        "actor_assurance": str(row["actor_assurance"]),
                        "schema_version": int(row["schema_version"]),
                    }
                    if record != expected:
                        raise RuntimeError("human action coverage row is corrupt")
                    action_coverage.append(expected)

                watermark_tables = (
                    "interventions",
                    "intervention_audit",
                    "permission_resolutions",
                    "lifecycle_resolutions",
                    "human_decision_resolutions",
                    "operator_effects",
                    "overlay_operations",
                    "lifecycle_restore_operations",
                    "project_identity_resolutions",
                    "human_session_control_actions",
                    "human_session_control_coverage",
                    "human_operator_action_reservations",
                    "human_operator_terminal_actions",
                    "human_operator_action_coverage",
                    "goal_control_operations",
                    "goal_control_attention_migration_state",
                    "goal_control_attention_legacy_operations",
                    "goal_control_attention_coverage",
                    "goal_control_attention_receipts",
                )
                watermarks = {
                    table: await scalar(f"SELECT COALESCE(MAX(rowid), 0) FROM {table}")
                    for table in watermark_tables
                }
                intervention_count = await scalar("SELECT COUNT(*) FROM interventions")
                excluded_source_rows = await scalar(
                    "SELECT COUNT(*) FROM interventions WHERE project_binding IS NULL AND "
                    "COALESCE(json_extract(json, '$.payload.policy_verdict'), "
                    "json_extract(json, '$.policy_verdict')) = 'ask_human'"
                ) + await scalar(
                    "SELECT COUNT(*) FROM permission_resolutions WHERE project_binding IS NULL"
                ) + await scalar(
                    "SELECT COUNT(*) FROM lifecycle_resolutions WHERE project_binding IS NULL"
                ) + await scalar(
                    "SELECT COUNT(*) FROM human_decision_resolutions WHERE "
                    "json_extract(json, '$.project_binding') IS NULL"
                ) + await scalar(
                    "SELECT COUNT(*) FROM overlay_operations WHERE kind = 'revert' AND "
                    "project_binding IS NULL"
                ) + await scalar(
                    "SELECT COUNT(*) FROM lifecycle_restore_operations WHERE "
                    "project_binding IS NULL"
                ) + await scalar(
                    "SELECT COUNT(*) FROM human_session_control_actions WHERE "
                    "project_binding IS NULL"
                ) + goal_attention_legacy_unverified
                pending_cursor = await transaction.execute(
                    "SELECT id FROM interventions AS i WHERE "
                    "COALESCE(json_extract(i.json, '$.payload.policy_verdict'), "
                    "json_extract(i.json, '$.policy_verdict')) = 'ask_human' AND "
                    "i.project_binding IS NOT NULL AND "
                    "NOT EXISTS (SELECT 1 FROM permission_resolutions AS p "
                    "WHERE p.intervention_id = i.id) AND "
                    "NOT EXISTS (SELECT 1 FROM lifecycle_resolutions AS l "
                    "WHERE l.intervention_id = i.id) AND "
                    "NOT EXISTS (SELECT 1 FROM human_decision_resolutions AS h "
                    "WHERE h.intervention_id = i.id) "
                    "ORDER BY i.ts DESC, i.rowid DESC"
                )
                current_pending: list[Intervention] = []
                for row in await pending_cursor.fetchall():
                    try:
                        intervention, binding, session, goal, _ = (
                            await _load_bound_intervention(
                                transaction,
                                str(row["id"]),
                            )
                        )
                    except (LookupError, ProjectIdentityBlockedError):
                        continue
                    if session.status != SessionStatus.NEEDS_DECISION:
                        continue
                    if await _has_authoritative_goal_successor(
                        transaction,
                        goal,
                        binding,
                    ):
                        continue
                    is_typed_pending = intervention.result in {
                        "permission_awaiting_human",
                        "awaiting_human",
                    }
                    is_general_pending = (
                        intervention.action_taken == InterventionType.ASK_HUMAN.value
                        and not intervention.outcome
                        and intervention.helped is None
                    )
                    if is_typed_pending or is_general_pending:
                        current_pending.append(intervention)
                pending_detail_limit = 200
                current_pending_items = [
                    item.model_dump(mode="json")
                    for item in current_pending[:pending_detail_limit]
                ]
                pending_session_ids = {item.session_id for item in current_pending}
                unexplained_session_count = 0
                session_cursor = await transaction.execute(
                    "SELECT id FROM sessions WHERE json_extract(json, '$.status') = "
                    "'needs_decision' ORDER BY id"
                )
                for row in await session_cursor.fetchall():
                    try:
                        session, _ = await _load_bound_session(
                            transaction,
                            str(row["id"]),
                        )
                    except (LookupError, ProjectIdentityBlockedError):
                        continue
                    if session.id in pending_session_ids:
                        continue
                    if session.goal_id is not None:
                        goal, binding = await _load_bound_goal(
                            transaction,
                            session.goal_id,
                        )
                        if await _has_authoritative_goal_successor(
                            transaction,
                            goal,
                            binding,
                        ):
                            continue
                    unexplained_session_count += 1
                await transaction.commit()
            except Exception:
                await transaction.rollback()
                raise

        return {
            "schema": "pex.attention-metrics.v1",
            "definition_version": 1,
            "scope": {
                "kind": "all_local_durable_history",
                "project_id": None,
                "goal_id": None,
                "session_id": None,
                "includes_historical_authority": True,
            },
            "window": {
                "kind": "all_time",
                "started_at": coverage_started_at,
                "ended_at": captured_at,
                "as_of": captured_at,
                "records_considered": intervention_count,
                "aggregate_truncated": False,
                "detail_rows_truncated": None,
            },
            "authority": {
                "source": "canonical_sqlite_ledgers",
                "consistent_read_snapshot": True,
                "watermarks": watermarks,
            },
            "coverage": {
                "complete": False,
                "coverage_started_at": coverage_started_at,
                "excluded_legacy_or_unbound_source_rows": excluded_source_rows,
                "actor_assured_action_coverage": action_coverage,
                "unmeasured_action_kinds": [
                    "manual_context_copy_outside_pex",
                    "manual_verification_outside_pex",
                    "active_human_time",
                ],
            },
            "human_interventions": {
                "value": None,
                "measured": False,
                "observed_count": observed_human_actions,
                "coverage_complete": False,
                "source_counts": source_counts,
                "unverified_operator_action_counts": unverified_operator_actions,
                "unverified_goal_control_action_counts": {
                    "precoverage_changed_operations": goal_attention_legacy_unverified,
                },
                "actor_assured_operator_message_outcomes": actor_assured_operator_outcomes,
                "actor_assured_operator_handoff_outcomes": actor_assured_handoff_outcomes,
                "null_reason": "not_all_human_action_routes_have_durable_receipts",
                "unmeasured_action_kinds": [
                    "manual_context_copy_outside_pex",
                    "manual_verification_outside_pex",
                ],
            },
            "human_intervention_requests": {
                "value": request_count,
                "measured": True,
                "definition": "durable_policy_ask_human_records",
            },
            "decisions": {
                "requested": request_count,
                "resolved": resolved_decisions,
                "pending": pending_decisions,
                "delivery_uncertain": uncertain_decisions,
                "measured": True,
                "scope_note": "all_history_not_current_authority_inbox",
            },
            "current_pending": {
                "count": len(current_pending),
                "items": current_pending_items,
                "items_limit": pending_detail_limit,
                "items_truncated": len(current_pending) > pending_detail_limit,
                "unexplained_session_count": unexplained_session_count,
                "scope": "current_live_authority",
            },
            "human_active_seconds": {
                "value": None,
                "measured": False,
                "consent": "not_configured",
                "interval_count": 0,
                "null_reason": "consent_gated_focus_intervals_are_not_recorded",
            },
            "unnecessary_alert_rate": {
                "value": None,
                "measured": False,
                "numerator": 0,
                "denominator": 0,
                "alerts_shown": None,
                "alerts_adjudicated": 0,
                "alerts_unjudged": None,
                "null_reason": "alert_exposure_and_adjudication_are_not_recorded",
            },
            "average_auto_resolution_confidence": {
                "value": None,
                "measured": False,
                "sample_count": 0,
                "eligible_resolution_count": None,
                "null_reason": "terminal_auto_resolution_eligibility_is_not_yet_frozen",
            },
            "reversals": {
                "value": reversal_completed,
                "measured": True,
                "attempted": reversal_attempts,
                "completed": reversal_completed,
                "failed": reversal_failed,
                "delivery_uncertain": reversal_uncertain,
                "definition": "unique_completed_operator_reversal_receipts",
            },
            "benchmark_evidence": False,
        }

    async def list_interventions_for_goal(
        self,
        goal_id: str,
        *,
        limit: int = 20,
        offset: int = 0,
    ) -> list[Intervention]:
        """Return a bounded newest-first goal page without post-limit filtering."""

        _validate_store_id(goal_id, label="intervention goal id")
        _validate_query_page(label="intervention", limit=limit, offset=offset)
        cur = await self.db.execute(
            "SELECT json FROM interventions "
            "WHERE goal_id = ? OR (project_binding IS NULL "
            "AND json_extract(json, '$.goal_id') = ?) "
            "ORDER BY ts DESC, rowid DESC LIMIT ? OFFSET ?",
            (goal_id, goal_id, limit, offset),
        )
        return [_stored_intervention(row["json"]) for row in await cur.fetchall()]

    async def latest_intervention_for_action(
        self,
        session_id: str,
        action_type: str,
    ) -> Intervention | None:
        """Return the newest exact action for one session without a scan limit."""

        if not session_id or len(session_id) > 512:
            raise ValueError("intervention session id is invalid")
        if not action_type or len(action_type) > 128:
            raise ValueError("intervention action type is invalid")
        cur = await self.db.execute(
            "SELECT json FROM interventions WHERE session_id = ? "
            "AND COALESCE(json_extract(json, '$.payload.proposed_action.type'), "
            "json_extract(json, '$.proposed_action.type')) = ? "
            "ORDER BY ts DESC, rowid DESC LIMIT 1",
            (session_id, action_type),
        )
        row = await cur.fetchone()
        return _stored_intervention(row["json"]) if row else None

    async def get_intervention(self, intervention_id: str) -> Intervention | None:
        cur = await self.db.execute(
            "SELECT json FROM interventions WHERE id = ?",
            (intervention_id,),
        )
        row = await cur.fetchone()
        return _stored_intervention(row["json"]) if row else None

    async def get_intervention_for_resolution_classification(
        self,
        intervention_id: str,
    ) -> Intervention | None:
        """Prove one frozen target for routing, without granting execution authority.

        This read deliberately survives current project quarantine/rebinding so a
        caller can choose an authority-reducing resolution path.  Permission and
        lifecycle reserve/start remain the only Store boundaries that grant a
        dispatch, and independently re-check the applicable live or containment
        snapshot.
        """

        _validate_store_id(intervention_id, label="intervention id")
        async with aiosqlite.connect(self.path, timeout=5.0) as transaction:
            await _configure_connection(transaction)
            await transaction.execute("BEGIN")
            try:
                try:
                    intervention, _, _, _, _ = await _load_bound_intervention(
                        transaction,
                        intervention_id,
                        require_live=False,
                    )
                except LookupError:
                    await transaction.commit()
                    return None
                await transaction.commit()
                return intervention
            except Exception:
                await transaction.rollback()
                raise

    async def get_intervention_for_authority(
        self,
        intervention_id: str,
    ) -> Intervention | None:
        """Return one intervention only while its frozen target identity is live."""

        _validate_store_id(intervention_id, label="intervention id")
        async with aiosqlite.connect(self.path, timeout=5.0) as transaction:
            await _configure_connection(transaction)
            await transaction.execute("BEGIN")
            try:
                try:
                    intervention, _, _, _, _ = await _load_bound_intervention(
                        transaction,
                        intervention_id,
                    )
                except LookupError:
                    await transaction.commit()
                    return None
                await transaction.commit()
                return intervention
            except Exception:
                await transaction.rollback()
                raise

    async def list_interventions_for_authority(
        self,
        session_id: str,
        *,
        goal_id: str,
        project_id: str,
        harness_type: str | HarnessType,
        limit: int = MAX_LIST_QUERY_LIMIT,
        offset: int = 0,
    ) -> list[Intervention]:
        """Return an exact session page under one current immutable identity."""

        _validate_store_id(session_id, label="intervention session id")
        _validate_store_id(goal_id, label="intervention goal id")
        _validate_query_page(label="intervention", limit=limit, offset=offset)
        harness_value = (
            harness_type.value if isinstance(harness_type, HarnessType) else harness_type
        )
        if not isinstance(harness_value, str) or not harness_value or len(harness_value) > 128:
            raise ValueError("intervention harness type is invalid")
        if not project_id or len(project_id) > MAX_PROJECT_ID_LENGTH:
            raise ValueError("intervention project id is invalid")
        async with aiosqlite.connect(self.path, timeout=5.0) as transaction:
            await _configure_connection(transaction)
            await transaction.execute("BEGIN")
            try:
                session, session_binding = await _load_bound_session(
                    transaction,
                    session_id,
                    require_goal_binding=True,
                )
                if session.goal_id != goal_id or session.harness_type.value != harness_value:
                    raise ProjectIdentityBlockedError(
                        "intervention session authority changed",
                        code="artifact_project_identity_changed",
                    )
                requested_binding = await _project_binding_snapshot(transaction, project_id)
                if session_binding is None or requested_binding != session_binding:
                    raise ProjectIdentityBlockedError(
                        "intervention project authority changed",
                        code="artifact_project_identity_changed",
                    )
                cursor = await transaction.execute(
                    "SELECT id FROM interventions WHERE session_id = ? AND goal_id = ? "
                    "AND project_binding = ? AND harness_type = ? "
                    "ORDER BY ts DESC, rowid DESC LIMIT ? OFFSET ?",
                    (
                        session_id,
                        goal_id,
                        session_binding,
                        harness_value,
                        limit,
                        offset,
                    ),
                )
                result: list[Intervention] = []
                for row in await cursor.fetchall():
                    intervention, _, _, _, _ = await _load_bound_intervention(
                        transaction,
                        str(row["id"]),
                    )
                    result.append(intervention)
                await transaction.commit()
                return result
            except Exception:
                await transaction.rollback()
                raise

    async def list_interventions_for_goal_for_authority(
        self,
        goal_id: str,
        *,
        project_id: str,
        limit: int = 20,
        offset: int = 0,
    ) -> list[Intervention]:
        """Return one goal page carrying its current creation-time binding."""

        _validate_store_id(goal_id, label="intervention goal id")
        _validate_query_page(label="intervention", limit=limit, offset=offset)
        if not project_id or len(project_id) > MAX_PROJECT_ID_LENGTH:
            raise ValueError("intervention project id is invalid")
        async with aiosqlite.connect(self.path, timeout=5.0) as transaction:
            await _configure_connection(transaction)
            await transaction.execute("BEGIN")
            try:
                goal, binding = await _load_bound_goal(transaction, goal_id)
                requested_binding = await _project_binding_snapshot(transaction, project_id)
                if requested_binding != binding.project_binding:
                    raise ProjectIdentityBlockedError(
                        "intervention goal project authority changed",
                        code="artifact_project_identity_changed",
                    )
                cursor = await transaction.execute(
                    "SELECT id FROM interventions WHERE goal_id = ? AND project_binding = ? "
                    "ORDER BY ts DESC, rowid DESC LIMIT ? OFFSET ?",
                    (goal.id, binding.project_binding, limit, offset),
                )
                result: list[Intervention] = []
                for row in await cursor.fetchall():
                    intervention, _, _, _, _ = await _load_bound_intervention(
                        transaction,
                        str(row["id"]),
                    )
                    result.append(intervention)
                await transaction.commit()
                return result
            except Exception:
                await transaction.rollback()
                raise

    async def has_pending_human_intervention(
        self,
        session_id: str,
        *,
        excluding_id: str | None = None,
    ) -> bool:
        parameters: list[Any] = [session_id]
        query = (
            "SELECT 1 FROM interventions WHERE session_id = ? "
            "AND COALESCE(json_extract(json, '$.payload.policy_verdict'), "
            "json_extract(json, '$.policy_verdict')) = 'ask_human' "
        )
        if excluding_id is not None:
            query += "AND id != ? "
            parameters.append(excluding_id)
        query += (
            "AND (COALESCE(json_extract(json, '$.payload.result'), "
            "json_extract(json, '$.result')) IN "
            "('permission_awaiting_human', 'awaiting_human', 'escalated') "
            "OR COALESCE(json_extract(json, '$.payload.result'), "
            "json_extract(json, '$.result')) LIKE '%!_failed' ESCAPE '!' "
            "OR COALESCE(json_extract(json, '$.payload.result'), "
            "json_extract(json, '$.result')) LIKE "
            "'%!_delivery!_uncertain' ESCAPE '!') "
            "LIMIT 1"
        )
        cur = await self.db.execute(query, tuple(parameters))
        return await cur.fetchone() is not None

    async def get_human_decision_resolution(
        self,
        intervention_id: str,
    ) -> dict[str, Any] | None:
        _validate_store_id(intervention_id, label="human decision intervention id")
        async with aiosqlite.connect(self.path, timeout=5.0) as transaction:
            await _configure_connection(transaction)
            await transaction.execute("BEGIN")
            try:
                loaded = await _load_validated_human_decision_resolution(
                    transaction,
                    intervention_id,
                )
                await transaction.commit()
                return loaded[0] if loaded is not None else None
            except Exception:
                await transaction.rollback()
                raise

    async def get_current_human_decision_resolution(
        self,
        intervention_id: str,
    ) -> dict[str, Any] | None:
        """Return a resolution projected from current canonical rows, never a stale receipt."""

        _validate_store_id(intervention_id, label="human decision intervention id")
        async with aiosqlite.connect(self.path, timeout=5.0) as transaction:
            await _configure_connection(transaction)
            await transaction.execute("BEGIN")
            try:
                loaded = await _load_validated_human_decision_resolution(
                    transaction,
                    intervention_id,
                )
                if loaded is None:
                    await transaction.commit()
                    return None
                record, intervention = loaded
                if intervention is None:
                    raise RuntimeError("legacy human decision projection is incomplete")
                session_cursor = await transaction.execute(
                    "SELECT json FROM sessions WHERE id = ?",
                    (str(record.get("session_id") or ""),),
                )
                session_row = await session_cursor.fetchone()
                if session_row is None:
                    raise RuntimeError("human decision session is missing")
                session = HarnessSession.model_validate_json(session_row["json"])
                decision_cursor = await transaction.execute(
                    "SELECT json FROM decisions WHERE id = ?",
                    (str(record.get("decision_id") or ""),),
                )
                decision_row = await decision_cursor.fetchone()
                context_cursor = await transaction.execute(
                    "SELECT json FROM context_items WHERE id = ?",
                    (str(record.get("context_id") or ""),),
                )
                context_row = await context_cursor.fetchone()
                if decision_row is None or context_row is None:
                    raise RuntimeError("human decision canonical artifacts are missing")
                decision = Decision.model_validate_json(decision_row["json"])
                context = ContextItem.model_validate_json(context_row["json"])
                current = dict(record)
                current["response"] = _human_decision_response(
                    intervention=intervention,
                    session=session,
                    decision=decision,
                    context=context,
                    resolution=current,
                )
                await transaction.commit()
                return current
            except Exception:
                await transaction.rollback()
                raise

    async def reserve_human_decision_delivery(
        self,
        *,
        intervention_id: str,
        choice: str,
        resolved_at: datetime,
    ) -> dict[str, Any]:
        """Atomically record redacted intent and reserve exactly one external effect."""

        _validate_store_id(intervention_id, label="human decision intervention id")
        if (
            not isinstance(choice, str)
            or not choice
            or len(choice) > 500
            or choice != choice.strip()
            or any(category(char).startswith("C") for char in choice)
        ):
            raise ValueError("human decision choice is invalid")
        if not isinstance(resolved_at, datetime) or resolved_at.tzinfo is None:
            raise ValueError("human decision resolution time must be timezone-aware")

        async with aiosqlite.connect(self.path, timeout=5.0) as transaction:
            await _configure_connection(transaction)
            await transaction.execute("BEGIN IMMEDIATE")
            try:
                intervention_cursor = await transaction.execute(
                    "SELECT json FROM interventions WHERE id = ?",
                    (intervention_id,),
                )
                intervention_row = await intervention_cursor.fetchone()
                if intervention_row is None:
                    raise LookupError("human decision intervention not found")
                intervention = _stored_intervention(intervention_row["json"])
                action = intervention.proposed_action
                options = action.payload.get("options")
                if not isinstance(options, list) or any(
                    not isinstance(option, str) for option in options
                ):
                    raise ValueError("human decision options are invalid")
                if options and choice not in options:
                    raise ValueError("human decision choice is not one of the offered options")
                choice_mode = "option" if options else "freeform"
                canonical_choice = human_decision_choice_receipt(
                    choice,
                    freeform=not options,
                )
                existing_cursor = await transaction.execute(
                    "SELECT * FROM human_decision_resolutions WHERE intervention_id = ?",
                    (intervention_id,),
                )
                existing_row = await existing_cursor.fetchone()
                if existing_row is not None:
                    loaded = await _load_validated_human_decision_resolution(
                        transaction,
                        intervention_id,
                    )
                    if loaded is None:  # pragma: no cover - same transaction invariant
                        raise RuntimeError("human decision resolution disappeared")
                    existing, _ = loaded
                    if existing.get("choice") != canonical_choice:
                        raise ValueError(
                            "human decision was already resolved with a different choice"
                        )
                    await transaction.commit()
                    return {"created": False, "record": existing}

                if (
                    action.type != InterventionType.ASK_HUMAN
                    or intervention.action_taken != InterventionType.ASK_HUMAN.value
                    or intervention.policy_verdict != PolicyVerdict.ASK_HUMAN
                    or intervention.result != "awaiting_human"
                    or intervention.metadata.get("decision_kind") != "mcp_human_request"
                ):
                    raise ValueError("intervention is not an unresolved MCP human decision")
                if action.session_id != intervention.session_id:
                    raise ValueError("human decision session identity mismatch")
                if action.goal_id != intervention.goal_id or intervention.goal_id is None:
                    raise ValueError("human decision goal identity mismatch")
                question = action.payload.get("question")
                if not isinstance(question, str) or not question:
                    raise ValueError("human decision question is missing")
                pending_context_id = str(action.payload.get("pending_context_id") or "")
                if (
                    not pending_context_id
                    or intervention.metadata.get("pending_context_id") != pending_context_id
                ):
                    raise ValueError("human decision pending context identity mismatch")

                try:
                    session, _ = await _load_bound_session(
                        transaction,
                        intervention.session_id,
                        require_goal_binding=True,
                    )
                except LookupError as exc:
                    raise ValueError("human decision session no longer exists") from exc
                if session.status in {
                    SessionStatus.STOPPED,
                    SessionStatus.ERROR,
                    SessionStatus.DETACHED,
                }:
                    raise ValueError("human decision session is terminal")
                try:
                    goal, goal_binding = await _load_bound_goal(
                        transaction,
                        intervention.goal_id,
                    )
                except LookupError as exc:
                    raise ValueError("human decision goal no longer exists") from exc
                project_id = _session_project(session)
                if session.supervision_paused or goal.paused:
                    raise ValueError("human decision delivery is paused")
                if session.goal_id != goal.id or not await _same_live_project_binding(
                    transaction,
                    project_id,
                    goal.project_id,
                ):
                    raise ValueError("human decision active binding changed")
                if (
                    action.payload.get("source_vendor_session_id") != session.vendor_session_id
                    or action.payload.get("source_harness_type") != session.harness_type.value
                    or not isinstance(action.payload.get("source_project_id"), str)
                    or not await _same_live_project_binding(
                        transaction,
                        str(action.payload.get("source_project_id")),
                        project_id,
                    )
                ):
                    raise ValueError("human decision worker binding changed")
                if await _has_authoritative_goal_successor(
                    transaction,
                    goal,
                    goal_binding,
                ):
                    raise ValueError("human decision goal has been superseded")
                project_binding = await _project_binding_snapshot(
                    transaction,
                    project_id,
                )

                pending_cursor = await transaction.execute(
                    "SELECT json FROM context_items WHERE id = ?",
                    (pending_context_id,),
                )
                pending_row = await pending_cursor.fetchone()
                if pending_row is None:
                    raise ValueError("human decision pending context no longer exists")
                pending = ContextItem.model_validate_json(pending_row["json"])
                if (
                    pending.goal_id != goal.id
                    or not _same_project(pending.project_id, project_id)
                    or pending.kind != ContextKind.WARNING
                    or pending.metadata.get("status") != "pending"
                    or pending.metadata.get("source_session_id") != session.id
                    or pending.stale_after is not None
                ):
                    raise ValueError("human decision pending context binding changed")

                artifact_key = hashlib.sha256(
                    f"pex.human-decision.v2\0{intervention.id}".encode()
                ).hexdigest()[:40]
                effect_id = f"effect_human_decision_{artifact_key}"
                decision = Decision(
                    id=f"dec_mcp_{artifact_key}",
                    goal_id=goal.id,
                    statement=canonical_choice,
                    rationale=f"Resolved worker question: {question}",
                    alternatives_rejected=[
                        option for option in options if option != canonical_choice
                    ],
                    scope=f"session:{session.id}",
                    confidence=1.0,
                    source=DecisionSource.HUMAN,
                    status=DecisionStatus.ACTIVE,
                    created_at=resolved_at,
                    metadata={
                        "intervention_id": intervention.id,
                        "source_session_id": session.id,
                        "question": question,
                        "delivery_effect_id": effect_id,
                        "delivery_status": "delivery_reserved",
                    },
                    sensitivity=Sensitivity.INTERNAL,
                )
                resolved_context = ContextItem(
                    id=f"decision_resolved_{artifact_key}",
                    project_id=project_id,
                    goal_id=goal.id,
                    kind=ContextKind.DECISION,
                    content=f"{question}\nDecision: {canonical_choice}",
                    source_refs=[pending.id, intervention.id],
                    provenance=SourceKind.HUMAN,
                    confidence=1.0,
                    relevance_tags=["decision", "human_selected"],
                    valid_from=resolved_at,
                    supersedes=pending.id,
                    sensitivity=Sensitivity.INTERNAL,
                    metadata={
                        "decision_id": decision.id,
                        "source_session_id": session.id,
                        "status": DecisionStatus.ACTIVE.value,
                        "intervention_id": intervention.id,
                        "delivery_effect_id": effect_id,
                        "delivery_status": "delivery_reserved",
                    },
                )
                pending.metadata.update(
                    {
                        "status": "decision_selected",
                        "selected_at": _utc_iso(resolved_at),
                        "resolved_choice": canonical_choice,
                        "resolved_by_context_id": resolved_context.id,
                        "delivery_effect_id": effect_id,
                    }
                )
                resolution = {
                    "schema": "pex.human-decision-resolution.v3",
                    "intervention_id": intervention.id,
                    "session_id": session.id,
                    "goal_id": goal.id,
                    "choice": canonical_choice,
                    "choice_mode": choice_mode,
                    "status": "delivery_reserved",
                    "delivery_code": "effect_reserved",
                    "effect_id": effect_id,
                    "delivery_attempts": 0,
                    "decision_id": decision.id,
                    "context_id": resolved_context.id,
                    "pending_context_id": pending.id,
                    "resolved_at": _utc_iso(resolved_at),
                    "source": "human",
                    "channel": "authenticated_local_control_api",
                    "intervention_binding": _decision_intervention_binding(intervention),
                    "session_binding": _decision_session_binding(session),
                    "goal_binding": {"goal_id": goal.id, "project_id": goal.project_id},
                    "project_binding": project_binding,
                }
                intervention.result = "human_decision_delivery_reserved"
                intervention.outcome = "human_decision_delivery_reserved"
                intervention.metadata["human_decision_resolution"] = resolution
                response = _human_decision_response(
                    intervention=intervention,
                    session=session,
                    decision=decision,
                    context=resolved_context,
                    resolution=resolution,
                )
                record = {**resolution, "response": response}
                audit_json = _canonical_json(
                    self._intervention_audit_record(
                        intervention,
                        "human_decision_delivery_reserved",
                    )
                )
                await transaction.execute(
                    "INSERT INTO human_decision_resolutions("
                    "intervention_id, session_id, goal_id, choice, decision_id, "
                    "context_id, resolved_at, delivery_contract_version, json) "
                    "VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)",
                    (
                        intervention.id,
                        session.id,
                        goal.id,
                        canonical_choice,
                        decision.id,
                        resolved_context.id,
                        _utc_iso(resolved_at),
                        HUMAN_DECISION_DELIVERY_CONTRACT_EXACT_TURN,
                        _canonical_json(record),
                    ),
                )
                decision_binding = await _binding_for_decision(transaction, decision)
                context_binding = await _binding_for_context_item(transaction, resolved_context)
                await transaction.execute(
                    "INSERT INTO decisions(id, goal_id, project_id, project_binding, json) "
                    "VALUES (?, ?, ?, ?, ?)",
                    (
                        decision.id,
                        decision.goal_id,
                        decision_binding.project_id,
                        decision_binding.project_binding,
                        _dump(decision),
                    ),
                )
                await transaction.execute(
                    "INSERT INTO context_items(id, project_id, project_binding, goal_id, json) "
                    "VALUES (?, ?, ?, ?, ?)",
                    (
                        resolved_context.id,
                        resolved_context.project_id,
                        context_binding.project_binding,
                        resolved_context.goal_id,
                        _dump(resolved_context),
                    ),
                )
                await transaction.execute(
                    "UPDATE context_items SET json = ? WHERE id = ? AND goal_id = ?",
                    (_dump(pending), pending.id, pending.goal_id),
                )
                await _update_bound_intervention(transaction, intervention)
                await transaction.execute(
                    "INSERT INTO intervention_audit(intervention_id, record_type, json) "
                    "VALUES (?, ?, ?)",
                    (intervention.id, "human_decision_delivery_reserved", audit_json),
                )
                await _update_human_decision_mutation_response(
                    transaction,
                    intervention_id=intervention.id,
                    response=response,
                )
                await transaction.commit()
            except aiosqlite.IntegrityError as exc:
                await transaction.rollback()
                raise ValueError("human decision resolution artifact id collision") from exc
            except Exception:
                await transaction.rollback()
                raise
        await self._try_sync_intervention_audit()
        return {"created": True, "record": record}

    async def start_human_decision_delivery(
        self,
        *,
        intervention_id: str,
        effect_id: str,
        started_at: datetime,
    ) -> dict[str, Any]:
        """Revalidate the exact live binding and CAS one reserved effect to dispatching."""

        _validate_store_id(intervention_id, label="human decision intervention id")
        _validate_store_id(effect_id, label="human decision delivery effect id")
        if not isinstance(started_at, datetime) or started_at.tzinfo is None:
            raise ValueError("human decision delivery start time must be timezone-aware")
        async with aiosqlite.connect(self.path, timeout=5.0) as transaction:
            await _configure_connection(transaction)
            await transaction.execute("BEGIN IMMEDIATE")
            try:
                resolution_cursor = await transaction.execute(
                    "SELECT * FROM human_decision_resolutions WHERE intervention_id = ?",
                    (intervention_id,),
                )
                resolution_row = await resolution_cursor.fetchone()
                if resolution_row is None:
                    raise LookupError("human decision delivery reservation not found")
                loaded = await _load_validated_human_decision_resolution(
                    transaction,
                    intervention_id,
                )
                if loaded is None:  # pragma: no cover - same transaction invariant
                    raise RuntimeError("human decision resolution disappeared")
                resolution, intervention = loaded
                if intervention is None:
                    raise RuntimeError("legacy human decision cannot start delivery")
                if resolution.get("effect_id") != effect_id:
                    raise ValueError("human decision delivery effect identity mismatch")
                if resolution.get("status") != "delivery_reserved":
                    await transaction.commit()
                    return {"started": False, "record": resolution}
                if resolution.get("intervention_binding") != _decision_intervention_binding(
                    intervention
                ):
                    raise ValueError("human decision intervention binding changed")
                try:
                    session, _ = await _load_bound_session(
                        transaction,
                        intervention.session_id,
                        require_goal_binding=True,
                    )
                except LookupError as exc:
                    raise ValueError("human decision session no longer exists") from exc
                if resolution.get("session_binding") != _decision_session_binding(session):
                    raise ValueError("human decision vendor session binding changed")
                action = intervention.proposed_action
                if (
                    action.session_id != session.id
                    or action.goal_id != session.goal_id
                    or action.payload.get("source_vendor_session_id") != session.vendor_session_id
                    or action.payload.get("source_harness_type") != session.harness_type.value
                ):
                    raise ValueError("human decision worker binding changed before delivery")
                project_id = _session_project(session)
                source_project = action.payload.get("source_project_id")
                if not isinstance(source_project, str) or not _same_project(
                    source_project,
                    project_id,
                ):
                    raise ValueError("human decision project binding changed before delivery")
                if session.status in {
                    SessionStatus.STOPPED,
                    SessionStatus.ERROR,
                    SessionStatus.DETACHED,
                }:
                    raise ValueError("human decision session became terminal before delivery")
                if session.supervision_paused:
                    raise ValueError("human decision session was paused before delivery")
                try:
                    goal, goal_binding = await _load_bound_goal(
                        transaction,
                        str(session.goal_id or ""),
                    )
                except LookupError as exc:
                    raise ValueError("human decision goal no longer exists") from exc
                if goal.paused:
                    raise ValueError("human decision goal was paused before delivery")
                if resolution.get("goal_binding") != {
                    "goal_id": goal.id,
                    "project_id": goal.project_id,
                }:
                    raise ValueError("human decision goal binding changed before delivery")
                if not await _same_live_project_binding(
                    transaction,
                    goal.project_id,
                    project_id,
                ):
                    raise ValueError("human decision goal project changed before delivery")
                if await _has_authoritative_goal_successor(
                    transaction,
                    goal,
                    goal_binding,
                ):
                    raise ValueError("human decision goal was superseded before delivery")
                project_binding = await _project_binding_snapshot(
                    transaction,
                    project_id,
                )
                if resolution.get("project_binding") != project_binding:
                    raise ValueError("human decision project identity changed before delivery")

                resolution.update(
                    {
                        "status": "dispatching",
                        "delivery_code": "dispatch_started",
                        "delivery_attempts": 1,
                        "dispatcher_boot_id": self.process_boot_id,
                        "started_at": _utc_iso(started_at),
                    }
                )
                intervention.result = "human_decision_dispatching"
                intervention.outcome = "human_decision_dispatching"
                intervention.metadata["human_decision_resolution"] = {
                    key: value for key, value in resolution.items() if key != "response"
                }
                decision_cursor = await transaction.execute(
                    "SELECT json FROM decisions WHERE id = ?",
                    (str(resolution.get("decision_id") or ""),),
                )
                decision_row = await decision_cursor.fetchone()
                context_cursor = await transaction.execute(
                    "SELECT json FROM context_items WHERE id = ?",
                    (str(resolution.get("context_id") or ""),),
                )
                context_row = await context_cursor.fetchone()
                if decision_row is None or context_row is None:
                    raise RuntimeError("human decision canonical artifacts are missing")
                decision = Decision.model_validate_json(decision_row["json"])
                context = ContextItem.model_validate_json(context_row["json"])
                response = _human_decision_response(
                    intervention=intervention,
                    session=session,
                    decision=decision,
                    context=context,
                    resolution=resolution,
                )
                record = {**resolution, "response": response}
                await transaction.execute(
                    "UPDATE human_decision_resolutions SET json = ? WHERE intervention_id = ?",
                    (_canonical_json(record), intervention_id),
                )
                await _update_bound_intervention(transaction, intervention)
                await transaction.execute(
                    "INSERT INTO intervention_audit(intervention_id, record_type, json) "
                    "VALUES (?, ?, ?)",
                    (
                        intervention_id,
                        "human_decision_dispatch_started",
                        _canonical_json(
                            self._intervention_audit_record(
                                intervention,
                                "human_decision_dispatch_started",
                            )
                        ),
                    ),
                )
                await _update_human_decision_mutation_response(
                    transaction,
                    intervention_id=intervention_id,
                    response=response,
                )
                await transaction.commit()
            except Exception:
                await transaction.rollback()
                raise
        await self._try_sync_intervention_audit()
        return {
            "started": True,
            "record": record,
            "session": session.model_dump(mode="json"),
            "intervention": intervention.model_dump(mode="json"),
        }

    async def finalize_human_decision_delivery(
        self,
        *,
        intervention_id: str,
        effect_id: str,
        status: str,
        delivery_code: str,
        finished_at: datetime,
        exception_type: str | None = None,
        worker_delivery_receipt: dict[str, str] | None = None,
    ) -> dict[str, Any]:
        """Finalize one reserved effect and conditionally release its attention overlay."""

        allowed = {"delivered", "unsupported", "rejected", "failed", "delivery_uncertain"}
        if status not in allowed:
            raise ValueError("human decision delivery status is invalid")
        _validate_store_id(intervention_id, label="human decision intervention id")
        _validate_store_id(effect_id, label="human decision delivery effect id")
        if not isinstance(delivery_code, str) or not delivery_code or len(delivery_code) > 128:
            raise ValueError("human decision delivery code is invalid")
        if exception_type is not None and (
            not isinstance(exception_type, str) or not exception_type or len(exception_type) > 128
        ):
            raise ValueError("human decision exception type is invalid")
        if status == "delivered" and (
            delivery_code != "send_confirmed" or exception_type is not None
        ):
            raise ValueError(
                "delivered human decision requires send_confirmed without an exception"
            )
        if not isinstance(finished_at, datetime) or finished_at.tzinfo is None:
            raise ValueError("human decision delivery finish time must be timezone-aware")

        async with aiosqlite.connect(self.path, timeout=5.0) as transaction:
            await _configure_connection(transaction)
            await transaction.execute("BEGIN IMMEDIATE")
            try:
                resolution_cursor = await transaction.execute(
                    "SELECT * FROM human_decision_resolutions WHERE intervention_id = ?",
                    (intervention_id,),
                )
                resolution_row = await resolution_cursor.fetchone()
                if resolution_row is None:
                    raise LookupError("human decision delivery reservation not found")
                loaded = await _load_validated_human_decision_resolution(
                    transaction,
                    intervention_id,
                )
                if loaded is None:  # pragma: no cover - same transaction invariant
                    raise RuntimeError("human decision resolution disappeared")
                resolution, intervention = loaded
                if intervention is None:
                    raise RuntimeError("legacy human decision cannot finalize delivery")
                if resolution.get("effect_id") != effect_id:
                    raise ValueError("human decision delivery effect identity mismatch")
                existing_status = str(resolution.get("status") or "")
                permitted_from = (
                    {"delivery_reserved"}
                    if status in {"unsupported", "failed"}
                    else {"dispatching"}
                )
                if existing_status not in allowed and existing_status not in permitted_from:
                    raise ValueError("human decision delivery transition is invalid")

                normalized_delivery_receipt = _normalize_human_decision_delivery_receipt(
                    worker_delivery_receipt,
                    status=status,
                    resolution=resolution,
                )
                if existing_status in allowed:
                    if (
                        existing_status != status
                        or resolution.get("delivery_code") != delivery_code
                        or resolution.get("exception_type") != exception_type
                        or resolution.get("worker_delivery_receipt")
                        != normalized_delivery_receipt
                    ):
                        raise ValueError("terminal human decision delivery receipt cannot change")
                    await transaction.commit()
                    return {"created": False, "record": resolution}

                session_cursor = await transaction.execute(
                    "SELECT json FROM sessions WHERE id = ?",
                    (intervention.session_id,),
                )
                session_row = await session_cursor.fetchone()
                if session_row is None:
                    raise RuntimeError("human decision session is missing")
                session = HarnessSession.model_validate_json(session_row["json"])
                if (
                    status == "delivered"
                    and session.harness_type
                    in {HarnessType.CODEX, HarnessType.QWEN, HarnessType.SYNTHETIC}
                    and resolution_row["delivery_contract_version"]
                    == HUMAN_DECISION_DELIVERY_CONTRACT_EXACT_TURN
                    and normalized_delivery_receipt is None
                ):
                    raise ValueError(
                        "delivered human decision requires an exact turn receipt"
                    )
                decision_cursor = await transaction.execute(
                    "SELECT json FROM decisions WHERE id = ?",
                    (str(resolution.get("decision_id") or ""),),
                )
                decision_row = await decision_cursor.fetchone()
                context_cursor = await transaction.execute(
                    "SELECT json FROM context_items WHERE id = ?",
                    (str(resolution.get("context_id") or ""),),
                )
                context_row = await context_cursor.fetchone()
                pending_cursor = await transaction.execute(
                    "SELECT json FROM context_items WHERE id = ?",
                    (str(resolution.get("pending_context_id") or ""),),
                )
                pending_row = await pending_cursor.fetchone()
                if decision_row is None or context_row is None or pending_row is None:
                    raise RuntimeError("human decision canonical artifacts are missing")
                decision = Decision.model_validate_json(decision_row["json"])
                context = ContextItem.model_validate_json(context_row["json"])
                pending = ContextItem.model_validate_json(pending_row["json"])

                resolution.update(
                    {
                        "status": status,
                        "delivery_code": delivery_code,
                        "finished_at": _utc_iso(finished_at),
                    }
                )
                if exception_type is not None:
                    resolution["exception_type"] = exception_type
                if normalized_delivery_receipt is not None:
                    resolution["worker_delivery_receipt"] = normalized_delivery_receipt
                decision.metadata["delivery_status"] = status
                decision.metadata["delivery_code"] = delivery_code
                context.metadata["delivery_status"] = status
                context.metadata["delivery_code"] = delivery_code
                if status == "delivered":
                    pending.stale_after = finished_at
                    pending.metadata["status"] = "resolved"
                    pending.metadata["resolved_at"] = _utc_iso(finished_at)
                    context.relevance_tags = ["decision", "human_resolved"]
                else:
                    pending.metadata["status"] = f"delivery_{status}"

                result_by_status = {
                    "delivered": "human_decision_delivered",
                    "unsupported": "human_decision_delivery_unsupported",
                    "rejected": "human_decision_delivery_rejected",
                    "failed": "human_decision_delivery_failed",
                    "delivery_uncertain": "human_decision_delivery_uncertain",
                }
                intervention.result = result_by_status[status]
                intervention.outcome = result_by_status[status]
                intervention.metadata["human_decision_resolution"] = {
                    key: value for key, value in resolution.items() if key != "response"
                }
                if normalized_delivery_receipt is not None:
                    intervention.metadata["worker_delivery_receipt"] = dict(
                        normalized_delivery_receipt
                    )

                if status == "delivered":
                    can_restore_control = False
                    if not session.supervision_paused and resolution.get(
                        "session_binding"
                    ) == _decision_session_binding(session):
                        try:
                            project_id = _session_project(session)
                            live_project_binding = await _project_binding_snapshot(
                                transaction,
                                project_id,
                            )
                            goal, goal_binding = await _load_bound_goal(
                                transaction,
                                str(session.goal_id or ""),
                            )
                            can_restore_control = bool(
                                resolution.get("project_binding") == live_project_binding
                                and not goal.paused
                                and not await _has_authoritative_goal_successor(
                                    transaction,
                                    goal,
                                    goal_binding,
                                )
                            )
                        except (
                            LookupError,
                            ProjectIdentityBlockedError,
                            RuntimeError,
                            ValueError,
                        ):
                            can_restore_control = False
                    metadata = dict(session.metadata or {})
                    attention = metadata.get("human_decision_attention")
                    tracked_ids = (
                        [
                            str(value)
                            for value in attention.get("pending_intervention_ids", [])
                            if isinstance(value, str) and value
                        ]
                        if isinstance(attention, dict)
                        else []
                    )
                    tracked_by_attention = intervention.id in tracked_ids
                    owns_attention = (
                        session.status == SessionStatus.NEEDS_DECISION and tracked_by_attention
                    )
                    base_status = (
                        str(attention.get("base_status") or "working")
                        if isinstance(attention, dict)
                        else "working"
                    )
                    remaining_tracked_ids = tracked_ids
                    if isinstance(attention, dict) and tracked_by_attention:
                        remaining_tracked_ids = [
                            value for value in tracked_ids if value != intervention.id
                        ]
                        if remaining_tracked_ids:
                            updated_attention = dict(attention)
                            updated_attention["pending_intervention_ids"] = remaining_tracked_ids
                            updated_attention["pending_count"] = len(remaining_tracked_ids)
                            metadata["human_decision_attention"] = updated_attention
                        else:
                            metadata.pop("human_decision_attention", None)
                        session.metadata = metadata
                    other_pending_cursor = await transaction.execute(
                        "SELECT 1 FROM interventions WHERE session_id = ? AND id != ? "
                        "AND json_extract(json, '$.payload.policy_verdict') = 'ask_human' "
                        "AND (json_extract(json, '$.payload.result') IN "
                        "('permission_awaiting_human', 'awaiting_human', 'escalated', "
                        "'human_decision_delivery_reserved', 'human_decision_dispatching') "
                        "OR json_extract(json, '$.payload.result') "
                        "LIKE '%!_failed' ESCAPE '!' "
                        "OR json_extract(json, '$.payload.result') "
                        "LIKE '%!_unsupported' ESCAPE '!' "
                        "OR json_extract(json, '$.payload.result') "
                        "LIKE '%!_rejected' ESCAPE '!' "
                        "OR json_extract(json, '$.payload.result') "
                        "LIKE '%!_delivery!_uncertain' ESCAPE '!') LIMIT 1",
                        (session.id, intervention.id),
                    )
                    other_pending = await other_pending_cursor.fetchone() is not None
                    if (
                        can_restore_control
                        and owns_attention
                        and not other_pending
                        and not remaining_tracked_ids
                    ):
                        try:
                            restored = SessionStatus(base_status)
                        except ValueError:
                            restored = SessionStatus.WORKING
                        if restored == SessionStatus.NEEDS_DECISION:
                            restored = SessionStatus.WORKING
                        session.status = restored
                        session.last_activity = finished_at

                response = _human_decision_response(
                    intervention=intervention,
                    session=session,
                    decision=decision,
                    context=context,
                    resolution=resolution,
                )
                record = {**resolution, "response": response}
                record_type = result_by_status[status]
                await transaction.execute(
                    "UPDATE human_decision_resolutions SET json = ? WHERE intervention_id = ?",
                    (_canonical_json(record), intervention_id),
                )
                await transaction.execute(
                    "UPDATE decisions SET json = ? WHERE id = ?",
                    (_dump(decision), decision.id),
                )
                await transaction.execute(
                    "UPDATE context_items SET json = ? WHERE id = ? AND goal_id = ?",
                    (_dump(context), context.id, context.goal_id),
                )
                await transaction.execute(
                    "UPDATE context_items SET json = ? WHERE id = ? AND goal_id = ?",
                    (_dump(pending), pending.id, pending.goal_id),
                )
                await _update_frozen_bound_intervention(transaction, intervention)
                await transaction.execute(
                    "UPDATE sessions SET json = ?, revision = revision + 1 WHERE id = ?",
                    (_dump(session), session.id),
                )
                await transaction.execute(
                    "INSERT INTO intervention_audit(intervention_id, record_type, json) "
                    "VALUES (?, ?, ?)",
                    (
                        intervention.id,
                        record_type,
                        _canonical_json(self._intervention_audit_record(intervention, record_type)),
                    ),
                )
                await _update_human_decision_mutation_response(
                    transaction,
                    intervention_id=intervention.id,
                    response=response,
                )
                await transaction.commit()
            except Exception:
                await transaction.rollback()
                raise
        await self._try_sync_intervention_audit()
        return {"created": True, "record": record}

    async def get_permission_resolution(self, intervention_id: str) -> dict[str, Any] | None:
        cur = await self.db.execute(
            "SELECT json FROM permission_resolutions WHERE intervention_id = ?",
            (intervention_id,),
        )
        row = await cur.fetchone()
        return json.loads(row["json"]) if row else None

    async def reserve_permission_resolution(
        self,
        *,
        intervention_id: str,
        session_id: str,
        request_id: str,
        decision: str,
        started_at: datetime,
    ) -> tuple[bool, dict[str, Any]]:
        """Atomically reserve one delivery attempt for a permission request.

        The unique session/request key prevents a duplicated normalized event
        from delivering a second response through a different intervention.
        A reserved attempt is never silently retried because a process failure
        after adapter I/O leaves delivery outcome uncertain.
        """
        if not intervention_id or len(intervention_id) > 512:
            raise ValueError("permission intervention id is invalid")
        if not session_id or len(session_id) > 512:
            raise ValueError("permission session id is invalid")
        if not request_id or len(request_id) > 1024:
            raise ValueError("permission request id is invalid")
        if decision not in {"allow", "deny"}:
            raise ValueError("permission decision is invalid")
        if started_at.tzinfo is None:
            raise ValueError("permission resolution time must be timezone-aware")
        async with aiosqlite.connect(self.path, timeout=5.0) as transaction:
            await _configure_connection(transaction)
            await transaction.execute("BEGIN IMMEDIATE")
            try:
                existing_cursor = await transaction.execute(
                    "SELECT * FROM permission_resolutions WHERE intervention_id = ? "
                    "OR (session_id = ? AND request_id = ?) ORDER BY intervention_id LIMIT 1",
                    (intervention_id, session_id, request_id),
                )
                existing_row = await existing_cursor.fetchone()
                if existing_row is not None:
                    existing, _, _, _, _, _, _ = await _load_bound_resolution(
                        transaction,
                        "permission_resolutions",
                        str(existing_row["intervention_id"]),
                        require_live=False,
                    )
                    await transaction.commit()
                    return False, existing

                intervention, binding, session, goal, _ = await _load_bound_intervention(
                    transaction,
                    intervention_id,
                    require_live=False,
                )
                action = intervention.proposed_action
                if (
                    intervention.session_id != session_id
                    or action.session_id != session_id
                    or action.goal_id != intervention.goal_id
                    or action.type != InterventionType.RESPOND_PERMISSION
                    or intervention.action_taken != InterventionType.RESPOND_PERMISSION.value
                    or intervention.policy_verdict != PolicyVerdict.ASK_HUMAN
                    or intervention.result != "permission_awaiting_human"
                    or str(action.payload.get("request_id") or "").strip() != request_id
                ):
                    raise ValueError("permission reservation target is not the pending action")

                if session.status in {
                    SessionStatus.STOPPED,
                    SessionStatus.ERROR,
                    SessionStatus.DETACHED,
                }:
                    raise PermissionError("permission session is not live")
                project_id = _session_project(session)
                containment = decision == "deny"
                if containment:
                    dispatch_project_binding = await _project_binding_containment_snapshot(
                        transaction,
                        project_id,
                    )
                else:
                    intervention, binding, session, goal, _ = await _load_bound_intervention(
                        transaction,
                        intervention_id,
                    )
                    if session.supervision_paused or goal.paused:
                        raise PermissionError("permission allow is paused")
                    if await _has_authoritative_goal_successor(
                        transaction,
                        goal,
                        binding,
                    ):
                        raise PermissionError("permission goal was superseded")
                    dispatch_project_binding = binding.project_binding

                record: dict[str, Any] = {
                    "schema": "pex.permission-resolution.v3",
                    "intervention_id": intervention.id,
                    "session_id": session.id,
                    "goal_id": goal.id,
                    "project_id": binding.project_id,
                    "project_binding": binding.project_binding,
                    "dispatch_project_binding": dispatch_project_binding,
                    "vendor_session_id": session.vendor_session_id,
                    "harness_type": session.harness_type.value,
                    "action_hash": _intervention_action_hash(intervention),
                    "version": 0,
                    "request_id": request_id,
                    "decision": decision,
                    "status": "reserved",
                    "reserved_at": started_at.isoformat(),
                    "dispatch_started_at": None,
                    "dispatcher_boot_id": None,
                    "finished_at": None,
                    "delivery_result": None,
                    "source": "human",
                    "channel": "authenticated_local_control_api",
                    "authority_reducing": containment,
                    "intervention_binding": _decision_intervention_binding(intervention),
                    "session_binding": _decision_session_binding(session),
                    "goal_binding": {"goal_id": goal.id, "project_id": goal.project_id},
                }
                await transaction.execute(
                    "INSERT INTO permission_resolutions"
                    "(intervention_id, session_id, goal_id, project_id, project_binding, "
                    "vendor_session_id, harness_type, action_hash, version, request_id, "
                    "decision, status, json) VALUES (?, ?, ?, ?, ?, ?, ?, ?, 0, ?, ?, "
                    "'reserved', ?)",
                    (
                        intervention.id,
                        session.id,
                        goal.id,
                        binding.project_id,
                        binding.project_binding,
                        session.vendor_session_id,
                        session.harness_type.value,
                        _intervention_action_hash(intervention),
                        request_id,
                        decision,
                        _canonical_json(record),
                    ),
                )
                await transaction.commit()
                return True, record
            except Exception:
                await transaction.rollback()
                raise

    async def start_permission_resolution_dispatch(
        self,
        intervention_id: str,
        *,
        started_at: datetime | None = None,
    ) -> dict[str, Any]:
        """Final CAS that grants one exact asynchronous permission response."""

        _validate_store_id(intervention_id, label="permission intervention id")
        dispatch_time = started_at or utcnow()
        if dispatch_time.tzinfo is None:
            raise ValueError("permission dispatch time must be timezone-aware")
        async with aiosqlite.connect(self.path, timeout=5.0) as transaction:
            await _configure_connection(transaction)
            await transaction.execute("BEGIN IMMEDIATE")
            try:
                (
                    resolution,
                    _,
                    intervention,
                    binding,
                    session,
                    goal,
                    version,
                ) = await _load_bound_resolution(
                    transaction,
                    "permission_resolutions",
                    intervention_id,
                    require_live=False,
                    require_dispatch_snapshot=False,
                )
                if resolution.get("status") != "reserved":
                    await transaction.commit()
                    return {"granted": False, "resolution": resolution}
                if resolution.get("session_binding") != _decision_session_binding(session):
                    raise PermissionError("permission vendor session binding changed")
                if session.status in {
                    SessionStatus.STOPPED,
                    SessionStatus.ERROR,
                    SessionStatus.DETACHED,
                }:
                    raise PermissionError("permission session is not live")
                project_id = _session_project(session)
                containment = bool(resolution.get("authority_reducing"))
                if containment:
                    dispatch_project_binding = await _project_binding_containment_snapshot(
                        transaction,
                        project_id,
                    )
                else:
                    (
                        resolution,
                        _,
                        intervention,
                        binding,
                        session,
                        goal,
                        version,
                    ) = await _load_bound_resolution(
                        transaction,
                        "permission_resolutions",
                        intervention_id,
                        require_live=True,
                    )
                    if session.supervision_paused or goal.paused:
                        raise PermissionError("permission allow is paused")
                    if await _has_authoritative_goal_successor(
                        transaction,
                        goal,
                        binding,
                    ):
                        raise PermissionError("permission goal was superseded")
                    dispatch_project_binding = binding.project_binding
                if resolution.get("dispatch_project_binding") != dispatch_project_binding:
                    raise PermissionError("permission project identity changed before dispatch")

                next_version = version + 1
                resolution.update(
                    {
                        "status": "dispatching",
                        "dispatcher_boot_id": self.process_boot_id,
                        "dispatch_started_at": dispatch_time.isoformat(),
                        "version": next_version,
                    }
                )
                updated = await transaction.execute(
                    "UPDATE permission_resolutions SET status = 'dispatching', version = ?, "
                    "json = ? WHERE intervention_id = ? AND status = 'reserved' "
                    "AND version = ?",
                    (next_version, _canonical_json(resolution), intervention_id, version),
                )
                if updated.rowcount != 1:
                    raise RuntimeError("permission dispatch CAS was lost")
                await transaction.commit()
                return {
                    "granted": True,
                    "resolution": resolution,
                    "session": session.model_dump(mode="json"),
                    "intervention": intervention.model_dump(mode="json"),
                }
            except ProjectIdentityBlockedError as exc:
                await transaction.rollback()
                raise PermissionError(str(exc)) from exc
            except Exception:
                await transaction.rollback()
                raise

    async def finalize_permission_resolution(
        self,
        intervention: Intervention,
        session: HarnessSession,
        *,
        status: str,
        delivery_result: str,
        finished_at: datetime,
        record_type: str,
    ) -> dict[str, Any]:
        """Atomically finalize the replay guard, intervention, and session."""
        if session.id != intervention.session_id:
            raise ValueError("permission session identity mismatch")
        if not isinstance(finished_at, datetime) or finished_at.tzinfo is None:
            raise ValueError("permission resolution finish time must be timezone-aware")
        audit_json = json.dumps(
            self._intervention_audit_record(intervention, record_type),
            ensure_ascii=False,
            separators=(",", ":"),
        )
        async with aiosqlite.connect(self.path, timeout=5.0) as transaction:
            await _configure_connection(transaction)
            await transaction.execute("BEGIN IMMEDIATE")
            try:
                current, _, stored, _, _, _, version = await _load_bound_resolution(
                    transaction,
                    "permission_resolutions",
                    intervention.id,
                    require_live=False,
                    require_dispatch_snapshot=False,
                )
                _validate_intervention_identity(intervention, stored)
                if current.get("status") != "dispatching":
                    await transaction.commit()
                    return current
                if not _resolution_session_target_matches(
                    current.get("session_binding"),
                    session,
                ):
                    raise PermissionError("permission finalization target changed")

                next_version = version + 1
                finalized = dict(current)
                finalized.update(
                    {
                        "status": status,
                        "delivery_result": delivery_result,
                        "finished_at": finished_at.isoformat(),
                        "version": next_version,
                    }
                )
                cursor = await transaction.execute(
                    "UPDATE permission_resolutions SET status = ?, version = ?, json = ? "
                    "WHERE intervention_id = ? AND status = 'dispatching' AND version = ?",
                    (
                        status,
                        next_version,
                        _canonical_json(finalized),
                        intervention.id,
                        version,
                    ),
                )
                if cursor.rowcount != 1:
                    raise RuntimeError("permission finalization CAS was lost")
                session_cursor = await transaction.execute(
                    "SELECT json FROM sessions WHERE id = ?",
                    (session.id,),
                )
                session_row = await session_cursor.fetchone()
                if session_row is None:
                    raise RuntimeError("permission session disappeared")
                merged_session = await _merge_resolution_session_state(
                    transaction,
                    HarnessSession.model_validate_json(session_row["json"]),
                    session,
                    finalized,
                )
                await _update_bound_intervention(transaction, intervention)
                session_update = await transaction.execute(
                    "UPDATE sessions SET json = ?, revision = revision + 1 WHERE id = ?",
                    (_dump(merged_session), session.id),
                )
                if session_update.rowcount != 1:
                    raise RuntimeError("permission session update was lost")
                await transaction.execute(
                    "INSERT INTO intervention_audit(intervention_id, record_type, json) "
                    "VALUES (?, ?, ?)",
                    (intervention.id, record_type, audit_json),
                )
                await transaction.commit()
            except Exception:
                await transaction.rollback()
                raise
        await self._try_sync_intervention_audit()
        return finalized

    async def get_lifecycle_resolution(self, intervention_id: str) -> dict[str, Any] | None:
        cur = await self.db.execute(
            "SELECT json FROM lifecycle_resolutions WHERE intervention_id = ?",
            (intervention_id,),
        )
        row = await cur.fetchone()
        return json.loads(row["json"]) if row else None

    async def reserve_lifecycle_resolution(
        self,
        *,
        intervention_id: str,
        session_id: str,
        decision: str,
        started_at: datetime,
    ) -> tuple[bool, dict[str, Any]]:
        """Reserve one human lifecycle decision before any external side effect."""
        if not intervention_id or len(intervention_id) > 512:
            raise ValueError("lifecycle intervention id is invalid")
        if not session_id or len(session_id) > 512:
            raise ValueError("lifecycle session id is invalid")
        if decision not in {"allow", "deny"}:
            raise ValueError("lifecycle decision is invalid")
        if started_at.tzinfo is None:
            raise ValueError("lifecycle resolution time must be timezone-aware")
        async with aiosqlite.connect(self.path, timeout=5.0) as transaction:
            await _configure_connection(transaction)
            await transaction.execute("BEGIN IMMEDIATE")
            try:
                existing_cursor = await transaction.execute(
                    "SELECT * FROM lifecycle_resolutions WHERE intervention_id = ?",
                    (intervention_id,),
                )
                existing_row = await existing_cursor.fetchone()
                if existing_row is not None:
                    existing, _, _, _, _, _, _ = await _load_bound_resolution(
                        transaction,
                        "lifecycle_resolutions",
                        intervention_id,
                        require_live=False,
                    )
                    await transaction.commit()
                    return False, existing

                intervention, binding, session, goal, _ = await _load_bound_intervention(
                    transaction,
                    intervention_id,
                    require_live=False,
                )
                action = intervention.proposed_action
                if (
                    intervention.session_id != session_id
                    or action.session_id != session_id
                    or action.goal_id != intervention.goal_id
                    or action.type
                    not in {
                        InterventionType.START_AGENT,
                        InterventionType.STOP_AGENT,
                        InterventionType.FORK_PROBE,
                        InterventionType.CLEANUP,
                    }
                    or intervention.action_taken != action.type.value
                    or intervention.policy_verdict != PolicyVerdict.ASK_HUMAN
                    or intervention.result != "awaiting_human"
                ):
                    raise ValueError("lifecycle reservation target is not the pending action")

                if session.status in {SessionStatus.ERROR, SessionStatus.DETACHED}:
                    raise PermissionError("lifecycle session is not controllable")
                if action.type == InterventionType.CLEANUP:
                    if session.status != SessionStatus.STOPPED:
                        raise PermissionError("cleanup source session is not stopped")
                elif session.status == SessionStatus.STOPPED:
                    raise PermissionError("lifecycle source session is already stopped")
                project_id = _session_project(session)
                containment = decision == "deny" or action.type == InterventionType.STOP_AGENT
                if containment:
                    dispatch_project_binding = await _project_binding_containment_snapshot(
                        transaction,
                        project_id,
                    )
                else:
                    intervention, binding, session, goal, _ = await _load_bound_intervention(
                        transaction,
                        intervention_id,
                    )
                    if session.supervision_paused or goal.paused:
                        raise PermissionError("lifecycle action is paused")
                    if await _has_authoritative_goal_successor(
                        transaction,
                        goal,
                        binding,
                    ):
                        raise PermissionError("lifecycle goal was superseded")
                    dispatch_project_binding = binding.project_binding

                record: dict[str, Any] = {
                    "schema": "pex.lifecycle-resolution.v3",
                    "intervention_id": intervention.id,
                    "session_id": session.id,
                    "goal_id": goal.id,
                    "project_id": binding.project_id,
                    "project_binding": binding.project_binding,
                    "dispatch_project_binding": dispatch_project_binding,
                    "vendor_session_id": session.vendor_session_id,
                    "harness_type": session.harness_type.value,
                    "action_hash": _intervention_action_hash(intervention),
                    "version": 0,
                    "decision": decision,
                    "action_type": action.type.value,
                    "status": "reserved",
                    "reserved_at": started_at.isoformat(),
                    "dispatch_started_at": None,
                    "dispatcher_boot_id": None,
                    "finished_at": None,
                    "delivery_result": None,
                    "source": "human",
                    "channel": "authenticated_local_control_api",
                    "authority_reducing": containment,
                    "intervention_binding": _decision_intervention_binding(intervention),
                    "session_binding": _decision_session_binding(session),
                    "goal_binding": {"goal_id": goal.id, "project_id": goal.project_id},
                }
                await transaction.execute(
                    "INSERT INTO lifecycle_resolutions"
                    "(intervention_id, session_id, goal_id, project_id, project_binding, "
                    "vendor_session_id, harness_type, action_hash, version, decision, "
                    "status, json) VALUES (?, ?, ?, ?, ?, ?, ?, ?, 0, ?, 'reserved', ?)",
                    (
                        intervention.id,
                        session.id,
                        goal.id,
                        binding.project_id,
                        binding.project_binding,
                        session.vendor_session_id,
                        session.harness_type.value,
                        _intervention_action_hash(intervention),
                        decision,
                        _canonical_json(record),
                    ),
                )
                await transaction.commit()
                return True, record
            except Exception:
                await transaction.rollback()
                raise

    async def start_lifecycle_resolution_dispatch(
        self,
        intervention_id: str,
        *,
        started_at: datetime | None = None,
    ) -> dict[str, Any]:
        """Final CAS that grants one exact lifecycle side effect."""

        _validate_store_id(intervention_id, label="lifecycle intervention id")
        dispatch_time = started_at or utcnow()
        if dispatch_time.tzinfo is None:
            raise ValueError("lifecycle dispatch time must be timezone-aware")
