    async def validate_lifecycle_dispatch_grant(
        self,
        intervention_id: str,
        action: ProposedAction,
    ) -> dict[str, Any]:
        """Re-read and prove the exact durable lifecycle grant before adapter I/O."""

        _validate_store_id(intervention_id, label="lifecycle intervention id")
        if not isinstance(action, ProposedAction):
            raise TypeError("lifecycle dispatch action is invalid")
        containment = action.type == InterventionType.STOP_AGENT
        async with aiosqlite.connect(self.path, timeout=5.0) as transaction:
            await _configure_connection(transaction)
            await transaction.execute("BEGIN")
            try:
                (
                    resolution,
                    _,
                    intervention,
                    binding,
                    session,
                    goal,
                    _,
                ) = await _load_bound_resolution(
                    transaction,
                    "lifecycle_resolutions",
                    intervention_id,
                    require_live=not containment,
                )
                if resolution.get("decision") != "allow":
                    await transaction.commit()
                    return {
                        "granted": False,
                        "reason": "lifecycle_resolution_denied",
                        "resolution": resolution,
                    }
                if resolution.get("status") != "dispatching":
                    await transaction.commit()
                    return {
                        "granted": False,
                        "reason": "lifecycle_resolution_not_dispatching",
                        "resolution": resolution,
                    }
                if resolution.get("dispatcher_boot_id") != self.process_boot_id:
                    await transaction.commit()
                    return {
                        "granted": False,
                        "reason": "lifecycle_dispatch_owner_changed",
                        "resolution": resolution,
                    }
                if intervention.proposed_action != action:
                    await transaction.commit()
                    return {
                        "granted": False,
                        "reason": "lifecycle_dispatch_action_changed",
                        "resolution": resolution,
                    }
                if resolution.get("session_binding") != _decision_session_binding(session):
                    raise PermissionError("lifecycle vendor session binding changed")
                if session.status in {SessionStatus.ERROR, SessionStatus.DETACHED}:
                    raise PermissionError("lifecycle session is not controllable")
                if action.type == InterventionType.CLEANUP:
                    if session.status != SessionStatus.STOPPED:
                        raise PermissionError("cleanup source session is not stopped")
                elif session.status == SessionStatus.STOPPED:
                    raise PermissionError("lifecycle source session is already stopped")
                if containment:
                    dispatch_project_binding = await _project_binding_containment_snapshot(
                        transaction,
                        _session_project(session),
                    )
                else:
                    if session.supervision_paused or goal.paused:
                        raise PermissionError("lifecycle action is paused")
                    if await _has_authoritative_goal_successor(
                        transaction,
                        goal,
                        binding,
                    ):
                        raise PermissionError("lifecycle goal was superseded")
                    dispatch_project_binding = binding.project_binding
                if resolution.get("dispatch_project_binding") != dispatch_project_binding:
                    raise PermissionError("lifecycle project identity changed before dispatch")
                await transaction.commit()
                return {
                    "granted": True,
                    "reason": "lifecycle_dispatch_granted",
                    "resolution": resolution,
                    "session": session.model_dump(mode="json"),
                    "intervention": intervention.model_dump(mode="json"),
                }
            except Exception:
                await transaction.rollback()
                raise

    async def finalize_lifecycle_resolution(
        self,
        intervention: Intervention,
        session: HarnessSession,
        resolution: dict[str, Any],
        *,
        record_type: str,
    ) -> dict[str, Any]:
        """Commit the resolution, updated intervention, and source session together."""
        if session.id != intervention.session_id:
            raise ValueError("lifecycle session identity mismatch")
        audit_json = json.dumps(
            self._intervention_audit_record(intervention, record_type),
            ensure_ascii=False,
            separators=(",", ":"),
        )
        async with aiosqlite.connect(self.path, timeout=5.0) as transaction:
            await _configure_connection(transaction)
            await transaction.execute("BEGIN IMMEDIATE")
            try:
                current, _, stored, _, _, _, version = await _load_bound_resolution(
                    transaction,
                    "lifecycle_resolutions",
                    intervention.id,
                    require_live=False,
                    require_dispatch_snapshot=False,
                )
                _validate_intervention_identity(intervention, stored)
                if not _resolution_session_target_matches(
                    current.get("session_binding"),
                    session,
                ):
                    raise PermissionError("lifecycle finalization target changed")
                expected = "dispatching" if current.get("decision") == "allow" else "reserved"
                if current.get("status") != expected:
                    await transaction.commit()
                    return current
                immutable_keys = (
                    "intervention_id",
                    "session_id",
                    "goal_id",
                    "project_id",
                    "project_binding",
                    "dispatch_project_binding",
                    "vendor_session_id",
                    "harness_type",
                    "action_hash",
                    "decision",
                    "action_type",
                    "intervention_binding",
                    "session_binding",
                    "goal_binding",
                )
                if any(
                    key in resolution and resolution.get(key) != current.get(key)
                    for key in immutable_keys
                ):
                    raise PermissionError("lifecycle finalization target changed")
                terminal_status = str(resolution.get("status") or "")
                if not terminal_status or terminal_status in {"reserved", "dispatching"}:
                    raise ValueError("lifecycle terminal status is invalid")
                next_version = version + 1
                finalized = dict(current)
                finalized.update(
                    {
                        "status": terminal_status,
                        "delivery_result": resolution.get("delivery_result"),
                        "finished_at": resolution.get("finished_at"),
                        "version": next_version,
                    }
                )
                cursor = await transaction.execute(
                    "UPDATE lifecycle_resolutions SET status = ?, version = ?, json = ? "
                    "WHERE intervention_id = ? AND status = ? AND version = ?",
                    (
                        terminal_status,
                        next_version,
                        _canonical_json(finalized),
                        intervention.id,
                        expected,
                        version,
                    ),
                )
                if cursor.rowcount != 1:
                    raise RuntimeError("lifecycle finalization CAS was lost")
                session_cursor = await transaction.execute(
                    "SELECT json FROM sessions WHERE id = ?",
                    (session.id,),
                )
                session_row = await session_cursor.fetchone()
                if session_row is None:
                    raise RuntimeError("lifecycle session disappeared")
                merged_session = await _merge_resolution_session_state(
                    transaction,
                    HarnessSession.model_validate_json(session_row["json"]),
                    session,
                    finalized,
                    allow_containment_stop=(
                        intervention.proposed_action.type == InterventionType.STOP_AGENT
                        and terminal_status == "delivered"
                    ),
                )
                await _update_bound_intervention(transaction, intervention)
                session_update = await transaction.execute(
                    "UPDATE sessions SET json = ?, revision = revision + 1 WHERE id = ?",
                    (_dump(merged_session), session.id),
                )
                if session_update.rowcount != 1:
                    raise RuntimeError("lifecycle session update was lost")
                await transaction.execute(
                    "INSERT INTO intervention_audit(intervention_id, record_type, json) "
                    "VALUES (?, ?, ?)",
                    (intervention.id, record_type, audit_json),
                )
                await transaction.commit()
            except Exception:
                await transaction.rollback()
                raise
        await self._try_sync_intervention_audit()
        return finalized

    async def add_context(self, item: ContextItem) -> None:
        _validate_store_id(item.id, label="context id")
        _reject_managed_goal_ledger_artifact(item, label="ContextItem")
        async with aiosqlite.connect(self.path, timeout=5.0) as transaction:
            await _configure_connection(transaction)
            await transaction.execute("BEGIN IMMEDIATE")
            try:
                binding = await _binding_for_context_item(transaction, item)
                cursor = await transaction.execute(
                    "INSERT OR IGNORE INTO context_items("
                    "id, project_id, project_binding, goal_id, json) VALUES (?, ?, ?, ?, ?)",
                    (
                        item.id,
                        item.project_id,
                        binding.project_binding,
                        item.goal_id,
                        _dump(item),
                    ),
                )
                if cursor.rowcount != 1:
                    existing_cursor = await transaction.execute(
                        "SELECT project_id, project_binding, goal_id, json "
                        "FROM context_items WHERE id = ?",
                        (item.id,),
                    )
                    row = await existing_cursor.fetchone()
                    if (
                        row is None
                        or ContextItem.model_validate_json(row["json"]) != item
                        or row["project_id"] != binding.project_id
                        or row["project_binding"] != binding.project_binding
                        or row["goal_id"] != item.goal_id
                    ):
                        raise ValueError("context item id collision contains different content")
                await transaction.commit()
            except Exception:
                await transaction.rollback()
                raise

    async def add_decision_context_pair(
        self,
        decision: Decision,
        context: ContextItem,
    ) -> None:
        """Atomically persist one ordinary Decision and its Context projection.

        Goal-ledger edits have their stricter create/patch/supersede transaction.
        This boundary covers event-derived human decisions such as explicit
        overrides, where a crash between two legacy inserts must never leave a
        Decision without the Context row consumed by handoff and the desktop.
        """

        _validate_store_id(decision.id, label="decision/context decision id")
        _validate_store_id(context.id, label="decision/context context id")
        _validate_store_id(decision.goal_id, label="decision/context goal id")
        _reject_managed_goal_ledger_artifact(decision, label="Decision")
        _reject_managed_goal_ledger_artifact(context, label="ContextItem")
        if context.goal_id != decision.goal_id:
            raise ValueError("decision/context goal binding mismatch")
        if (
            context.kind != ContextKind.DECISION
            or context.provenance != decision.source
            or context.content != decision.statement
            or context.metadata.get("decision_id") != decision.id
        ):
            raise ValueError("decision/context projection is inconsistent")

        async with aiosqlite.connect(self.path, timeout=5.0) as transaction:
            await _configure_connection(transaction)
            await transaction.execute("BEGIN IMMEDIATE")
            try:
                _, goal_binding = await _load_bound_goal(transaction, decision.goal_id)
                context_binding = await _binding_for_context_item(transaction, context)
                if context_binding.project_binding != goal_binding.project_binding:
                    raise ValueError("decision/context project binding mismatch")

                decision_cursor = await transaction.execute(
                    "INSERT OR IGNORE INTO decisions("
                    "id, goal_id, project_id, project_binding, json) "
                    "VALUES (?, ?, ?, ?, ?)",
                    (
                        decision.id,
                        decision.goal_id,
                        goal_binding.project_id,
                        goal_binding.project_binding,
                        _dump(decision),
                    ),
                )
                if decision_cursor.rowcount != 1:
                    existing_cursor = await transaction.execute(
                        "SELECT project_id, project_binding, json FROM decisions WHERE id = ?",
                        (decision.id,),
                    )
                    existing_row = await existing_cursor.fetchone()
                    if (
                        existing_row is None
                        or Decision.model_validate_json(existing_row["json"]) != decision
                        or existing_row["project_id"] != goal_binding.project_id
                        or existing_row["project_binding"] != goal_binding.project_binding
                    ):
                        raise ValueError("decision id collision contains different content")

                context_cursor = await transaction.execute(
                    "INSERT OR IGNORE INTO context_items("
                    "id, project_id, project_binding, goal_id, json) "
                    "VALUES (?, ?, ?, ?, ?)",
                    (
                        context.id,
                        context.project_id,
                        context_binding.project_binding,
                        context.goal_id,
                        _dump(context),
                    ),
                )
                if context_cursor.rowcount != 1:
                    existing_cursor = await transaction.execute(
                        "SELECT project_id, project_binding, goal_id, json "
                        "FROM context_items WHERE id = ?",
                        (context.id,),
                    )
                    existing_row = await existing_cursor.fetchone()
                    if (
                        existing_row is None
                        or ContextItem.model_validate_json(existing_row["json"]) != context
                        or existing_row["project_id"] != context_binding.project_id
                        or existing_row["project_binding"] != context_binding.project_binding
                        or existing_row["goal_id"] != context.goal_id
                    ):
                        raise ValueError("context item id collision contains different content")
                await transaction.commit()
            except Exception:
                await transaction.rollback()
                raise

