    async def context_kind_counts_for_goal(
        self,
        project_id: str,
        goal_id: str,
    ) -> dict[str, int]:
        """Count every shareable context item for one exact project and goal."""

        if (
            not isinstance(project_id, str)
            or not project_id.strip()
            or len(project_id) > MAX_PROJECT_ID_LENGTH
        ):
            raise ValueError("context project id is invalid")
        _validate_store_id(goal_id, label="context goal id")
        cur = await self.db.execute(
            "SELECT json_extract(json, '$.kind') AS kind, COUNT(*) AS item_count "
            "FROM context_items WHERE project_id = ? AND goal_id = ? "
            "AND json_extract(json, '$.sensitivity') NOT IN (?, ?) "
            "GROUP BY json_extract(json, '$.kind') ORDER BY kind",
            (
                project_id,
                goal_id,
                Sensitivity.SECRET.value,
                Sensitivity.LOCAL_ONLY.value,
            ),
        )
        return {str(row["kind"]): int(row["item_count"]) for row in await cur.fetchall()}

    async def context_kind_counts_for_authority(
        self,
        project_id: str,
        goal_id: str,
    ) -> dict[str, int]:
        """Count shareable context proven to belong to the live goal identity."""

        if (
            not isinstance(project_id, str)
            or not project_id.strip()
            or len(project_id) > MAX_PROJECT_ID_LENGTH
        ):
            raise ValueError("context project id is invalid")
        _validate_store_id(goal_id, label="context goal id")
        async with aiosqlite.connect(self.path, timeout=5.0) as transaction:
            await _configure_connection(transaction)
            await transaction.execute("BEGIN")
            try:
                goal, binding = await _load_bound_goal(transaction, goal_id)
                if not await _same_live_project_binding(
                    transaction,
                    project_id,
                    goal.project_id,
                ):
                    raise ProjectIdentityBlockedError(
                        "context project identity does not match its goal",
                        code="artifact_project_identity_changed",
                    )
                cursor = await transaction.execute(
                    "SELECT json_extract(json, '$.kind') AS kind, "
                    "COUNT(*) AS item_count FROM context_items "
                    "WHERE project_binding = ? AND goal_id = ? "
                    "AND json_extract(json, '$.sensitivity') NOT IN (?, ?) "
                    "GROUP BY json_extract(json, '$.kind') ORDER BY kind",
                    (
                        binding.project_binding,
                        goal_id,
                        Sensitivity.SECRET.value,
                        Sensitivity.LOCAL_ONLY.value,
                    ),
                )
                result = {
                    str(row["kind"]): int(row["item_count"]) for row in await cursor.fetchall()
                }
                await transaction.commit()
                return result
            except Exception:
                await transaction.rollback()
                raise

    async def list_context(
        self,
        project_id: str,
        *,
        limit: int = MAX_LIST_QUERY_LIMIT,
        offset: int = 0,
    ) -> list[ContextItem]:
        if not 1 <= limit <= MAX_LIST_QUERY_LIMIT:
            raise ValueError(f"context limit must be between 1 and {MAX_LIST_QUERY_LIMIT}")
        if offset < 0:
            raise ValueError("context offset cannot be negative")
        cur = await self.db.execute(
            "SELECT json FROM context_items WHERE project_id = ? "
            "ORDER BY json_extract(json, '$.valid_from') DESC, id DESC LIMIT ? OFFSET ?",
            (project_id, limit, offset),
        )
        rows = await cur.fetchall()
        return [ContextItem.model_validate_json(r["json"]) for r in rows]

    async def list_context_for_authority(
        self,
        project_id: str,
        *,
        goal_id: str | None = None,
        limit: int = MAX_LIST_QUERY_LIMIT,
        offset: int = 0,
    ) -> list[ContextItem]:
        """Return only context bound to the project's current immutable identity."""

        if not project_id or len(project_id) > MAX_PROJECT_ID_LENGTH:
            raise ValueError("context project id is invalid")
        _validate_query_page(label="context", limit=limit, offset=offset)
        if goal_id is not None:
            _validate_store_id(goal_id, label="context goal id")
        async with aiosqlite.connect(self.path, timeout=5.0) as transaction:
            await _configure_connection(transaction)
            await transaction.execute("BEGIN")
            try:
                parameters: list[Any]
                if goal_id is not None:
                    goal, goal_binding = await _load_bound_goal(transaction, goal_id)
                    if not await _same_live_project_binding(
                        transaction,
                        project_id,
                        goal.project_id,
                    ):
                        raise ProjectIdentityBlockedError(
                            "context project identity does not match its goal",
                            code="artifact_project_identity_changed",
                        )
                    query = (
                        "SELECT json FROM context_items WHERE project_binding = ? "
                        "AND goal_id = ?"
                    )
                    parameters = [goal_binding.project_binding, goal_id]
                else:
                    live_binding = await _project_binding_snapshot(transaction, project_id)
                    query = "SELECT json FROM context_items WHERE project_binding = ?"
                    parameters = [live_binding]
                query += (
                    " ORDER BY json_extract(json, '$.valid_from') DESC, id DESC LIMIT ? OFFSET ?"
                )
                parameters.extend((limit, offset))
                cursor = await transaction.execute(query, tuple(parameters))
                rows = await cursor.fetchall()
                await transaction.commit()
                return [ContextItem.model_validate_json(row["json"]) for row in rows]
            except Exception:
                await transaction.rollback()
                raise

